INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-09-045937', '6-K', '2009-07-30', '2009-07-30', 2009, NULL, 'quarter', 'mines. Agnico-Eagle remains one of the', 'gold', 119053.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465909045937/a09-20165_16k.htm', 'we expect to release the results of two more expansion studies, at Meadowbank | and Kittila, further adding to our production growth beyond 2010”, added Mr. Boyd. | Second quarter 2009 highlights include: | · | Record Production | – record gold production of 119,053 | ounces. First gold poured at Pinos Altos | in July | · | Good Cost Performance | – LaRonde, Goldex and Lapa achieve good | minesite cost performance | ·', 'production-v2', 0.8, '2026-07-01T23:02:50.663292+00:00', '2026-07-01T23:02:50.663292+00:00');
