INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-11-055635', '6-K', '2011-10-11', '2011-10-11', 2011, NULL, 'quarter', 'Agnico-Eagle Mines Limited', 'gold', 2011.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465911055635/a11-27816_1ex99d1.htm', 'EX-99.1 | Exhibit 99.1 | TORONTO, Oct. 11, 2011 /CNW/ - | Agnico-Eagle Mines Limited | (“Agnico-Eagle” or the “Company”) is providing a quarter over quarter operating update in advance of the mailing of the bid circular relating to the proposed acquisition of Grayd Resource Corporation (“Grayd”). It is anticipated that the circular will be mailed to Grayd shareholders on October 13, 2011. | Third quarter 2011 payable gold production(1) totaled 265,978 ounces, an increase of approximately 11% over the second quarter 2011 level of 239,328 ounces. The higher level of production is largely due to improved performance at Kittila and Meadowbank. Cost data will be announced with the complete third quarter financial results on October 26, 2011. Further improvements in gold production and operating performance are anticipated in the fourth quarter of 2011. | For the first nine months of 2011, the Company produced a record 757,668 ounces of gold. This compares with the previous nine month record set in the first nine months of 2010 when gold production was 731,138 ounces. The higher gold production in 2011 is mainly due to higher mill throughput at Meadowbank, Pinos Altos, Kittila and Lapa. | (1) Payable production of a mineral means the quantity of mineral produced during a period contained in products that are sold by the Company whether such products are shipped during the period or held as inventory at the end of the period. | Goldex Mine - Program Underway for Assessment, Monitoring and Remediation of Water Inflow and Subsidence Issue | The Goldex mill processed an average of 8,222 tonnes per day (“tpd”) in the third quarter of 2011 as compared with 8,448 tpd in the second quarter of 2011. The mine and mill continue to run at capacity. | Gold production in the third quarter of 2011 was 40,224 ounces. This compares with the second quarter of 2011 when the payable gold production was 41,998 ounces. The decrease was largely due to the slightly lower throughput combined with', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:19.567117+00:00', '2026-06-17T12:00:19.567117+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-12-003484', '20-F', '2012-03-29', '2011-12-31', 2011, 'FY', 'annual', 'Consolidated', 'gold', 45036.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746912003484/a2208447z20-f.htm', '8,182 | 2011 ANNUAL REPORT | 107 | Table of Contents | Payable production: | (i) | Gold (ounces) | LaRonde mine | 45,036', 'production-v2', 0.75, '2026-07-01T23:02:25.874056+00:00', '2026-07-01T23:02:25.874056+00:00');
