INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-13-003581', '20-F', '2013-03-28', '2012-12-31', 2012, 'FY', 'annual', 'Consolidated', 'gold', 43281.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746913003581/a2211934z20-f.htm', '8,083 | 2012 ANNUAL REPORT | 115 | Table of Contents | Payable production: | (ii) | Gold (ounces) | LaRonde mine | 43,281', 'production-v2', 0.75, '2026-06-01T22:34:04.038369+00:00', '2026-07-01T23:22:53.033654+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-13-003581', '20-F', '2013-03-28', '2012-12-31', 2012, 'FY', 'annual', 'Meadowbank Mine', 'gold', 2015.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746913003581/a2211934z20-f.htm', 'had been compromised by the September 30, 2012 event and further leaching on the phase one leach pad is not expected as a result. The Company expects production to commence from the Creston | Mascota deposit phase two leach pad in the second quarter of 2013. Payable gold production forecasts reflect a buildup of inventory on the phase two leach pad and a related ramp up in production in | 2013, with steady state operations commencing in 2014. | Meadowbank Mine | In 2013, payable gold production at the Meadowbank mine is expected to be approximately 360,000 ounces at estimated total cash costs per ounce of gold produced of | approximately $985. The Meadowbank mine is expected to average 359,000 ounces of payable gold production per year between 2013 and 2015. | The | Meadowbank mine experienced a number of start-up issues during its first two years. However, forecasted annual payable gold production has increased significantly as a result of | improved operating performance achieved in 2012. The Company expects mill throughput of approximately 11,000 tonnes per day to be sustainable and has extended the expected Meadowbank mine life | to 2018. | 106 | AGNICO-EAGLE MINES LIMITED | Table of Contents', 'production-v2', 0.8500000000000001, '2026-06-01T22:34:04.038369+00:00', '2026-06-01T22:34:04.038369+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-13-033801', '6-K', '2013-04-29', '2013-03-31', 2013, 'Q1', 'quarter', 'Consolidated', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465913033801/a13-9427_4ex99d1.htm', '· | Total cash cost per ounce | 1 | guidance for 2013 revised upward to reflect current commodity prices and exchange rates | — expected 2013 total cash costs to be between $735 and $785 per ounce | Payable gold production | 2 | in the first quarter of 2013 was 236,975 ounces compared to 254,955 ounces | in the first quarter of 2012. | The lower level of production in the 2013 period was primarily due to the Creston Mascota heap leach being suspended during most of the quarter. A description of the production and cost performance for each mine is set out further below. | Total cash costs for the first quarter of 2013 were $740 per ounce. This compares with $594 per ounce in the first quarter of 2012. The higher cost in 2013 was largely attributable to lower byproduct revenue at LaRonde, lower grades at Meadowbank and a lack of production from the lower cost Creston Mascota mine. | Agnico-Eagle’s production guidance for 2013 remains unchanged at 970,000 to 1,010,000 ounces of gold, as the expected 15,000 ounce production from Goldex offsets anticipated production decrease at Kittila related to a longer than anticipated maintenance shutdown. The Company’s cash cost estimates have been revised to reflect the production changes at Goldex and Kittila, as well as changes in commodity | 1', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:17.501459+00:00', '2026-06-17T12:00:17.501459+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-13-005913', '6-K', '2013-05-10', '2013-03-31', 2013, 'Q1', 'quarter', 'Consolidated', 'gold', 2012.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746913005913/a2215045zex-99_1.htm', 'Agnico Eagle reported net income of $23.9 million, or $0.14 per share, in the first quarter of 2013 compared with a net | income of $78.5 million, or $0.46 per share, in the first quarter of 2012. In the first quarter of 2013, the operating margin (revenue from mining operations less production costs) decreased | 26.2% to $190.4 million from $257.9 million in the first quarter of 2012 due primarily to a 7.1% decrease in gold production, a 4.3% decrease in the average realized price of gold and a | 7.0% increase in production costs. Gold production decreased to 236,975 ounces from 254,955 ounces between the first quarter of 2012 and the first quarter of 2013. Cash provided by | operating activities amounted to $146.1 million in the first quarter of 2013 compared with $196.5 million in the first quarter of 2012. Total weighted average cash costs per ounce of | gold produced amounted to $740 in the first quarter of 2013 compared with $594 in the first quarter of 2012. | The | table below summarizes variances in the key drivers of net income for the three months ended March 31, 2013 compared with the three months ended March 31, 2012: | (millions of United States dollars) | Three Months Ended | March 31, 2013 | vs. Three Months Ended | March 31, 2012', 'production-v2', 0.8, '2026-06-17T12:00:17.472595+00:00', '2026-06-17T12:00:17.472595+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-13-008312', '6-K', '2013-08-09', '2013-06-30', 2013, 'Q2', 'quarter', 'Consolidated', 'gold', 2012.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746913008312/a2215629zex-99_1.htm', 'the first six months of 2012 due primarily to an 11.4% decrease in gold production, a 10.2% decrease in the average realized price of gold and a 4.8% increase in production costs. Gold production | decreased to 461,064 ounces in the first six months of 2013 compared with 520,305 ounces in the first six months of 2012 due primarily to the Kittila mine''s extended mill shutdown to | facilitate the | relining of its autoclave during the second quarter of 2013 and the temporary suspension of active leaching at the Creston Mascota deposit at Pinos Altos during the first quarter of 2013. Cash | provided by operating activities amounted to $221.4 million in the first six months of 2013 compared with $390.6 million in the first six months of 2012. Total weighted average cash | costs per ounce of gold produced amounted to $762 in the first six months of 2013 compared with $628 in the first six months of 2012. | 2 | The | table below summarizes variances in the key drivers of net income for the three and six months ended June 30, 2013 compared with the three and six months ended | June 30, 2012: | (millions of United States dollars) | Three Months Ended June 30, 2013 | vs. Three Months Ended', 'production-v2', 0.8, '2026-06-17T12:00:17.362716+00:00', '2026-06-17T12:00:17.362716+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-13-056977', '6-K', '2013-07-26', '2013-07-24', 2013, NULL, 'quarter', 'Project remains on schedule and on budget', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465913056977/a13-14722_4ex99d1.htm', 'Capital and cost reductions of approximately $50 million in 2013 and $250 million in 2014 | · | La India commissioning on track for year-end 2013 — | Project remains on schedule and on budget | 2 | Payable gold production | 1 | in the second quarter of 2013 was 224,089 ounces, including 5,389 ounces from Kittila, compared to 265,350 ounces | in the second quarter of 2012 | The lower level of production in the 2013 period was primarily due to the extended maintenance shutdown at Kittila. A description of the production and cost performance for each mine is set out below. | Given that the Kittila autoclave operated for only 14 days in the second quarter, the impact of its expenditures is excluded from total cash costs per ounce calculations. On that basis, total cash costs per ounce for the second quarter of 2013 were $785 per ounce. This compares with $660 per ounce in the second quarter of 2012. The higher cash cost per ounce in 2013 was largely attributable to lower byproduct revenue at LaRonde and Pinos Altos. | Payable gold production for the first half of 2013 was 461,064 ounces, including 48,534 ounces from Kittila, compared to payable gold production of 520,305 ounces in the comparable 2012 period, of which almost 82,000 ounces were from Kittila. | For the first half of 2013, t', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:17.418566+00:00', '2026-06-17T12:00:17.418566+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-13-077832', '6-K', '2013-10-25', '2013-10-23', 2013, NULL, 'quarter', 'Consolidated', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465913077832/a13-20594_4ex99d1.htm', '(iii) | Payable production is the quantity of mineral produced during a period contained in products that are or will be sold by the Company, whether such products are sold during the period or held as inventory at the end of the period. | (iv) | Total cash costs per ounce of gold produced is calculated net of silver, copper, zinc and other byproduct revenue credits. The weighted average total cash costs per ounce of gold produced is based on commercial production ounces. Total cash costs per ounce of gold produced is a non-GAAP measure that the Company uses to monitor the performance of its operations. See “Reconciliation of Production Costs to Total Cash Costs per Ounce of Gold Produced by Mine” contained herein for details. | (v) | Excludes the Goldex mine’s results for the third quarter of 2013. Initial non-commercial payable gold production of 1,505 ounces was achieved at the Goldex mine during the third quarter of 2013. | (vi) | Excludes the Kittila mine’s results for the second quarter of 2013. Due to scheduled maintenance, the Kittila mine only operated for 14 days during the second quarter of 2013. | 15 | AGNICO EAGLE MINES LIMITED | CONSOLIDATED BALANCE SHEETS | (thousands of United States dollars, US GAAP basis) | (Unaudited)', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:17.270750+00:00', '2026-06-17T12:00:17.270750+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-14-010227', '6-K', '2014-02-14', '2014-02-12', 2014, NULL, 'quarter', 'Consolidated', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465914010227/a14-5891_1ex99d1.htm', '(ii) | Payable production is the quantity of mineral produced during a period contained in products that are or will be sold by the Company, whether such products are sold during the period or held as inventory at the end of the period. | (iii) | Total cash costs per ounce of gold produced is calculated net of silver, copper, zinc and other byproduct revenue credits. The weighted average total cash costs per ounce of gold produced is based on commercial production ounces. Total cash costs per ounce of gold produced is a non-GAAP measure that the Company uses to monitor the performance of its operations. See “Reconciliation of Production Costs to Total Cash Costs per Ounce of Gold Produced by Mine” contained herein for details. | (iv) | Excludes the Goldex mine’s results for the third quarter of 2013. Initial non-commercial payable gold production of 1,505 ounces was achieved at the Goldex mine during the third quarter of 2013. | (v) | Excludes the Kittila mine’s results for the second quarter of 2013. Due to scheduled maintenance, the Kittila mine only operated for 14 days during the second quarter of 2013. The Kittila mine incurred $18,159 in production costs during the second quarter of 2013, which were excluded from total cash costs per ounce of gold produced. | (vi) | Excludes the Creston Mascota deposit at Pinos Altos’ results for the first quarter of 2013 and the fourth quarter of 2012 due to the temporary suspension of active leaching between October 1, 2012 and March 13, 2013. The Creston Mascota deposit at Pinos Altos incurred $3,117 and $6,439 in production costs during the first quarter of 2013 and the fourth quarter of 2012, respectively, which were excluded from total cash costs per ounce of gold produced. | 36 | AGNICO EAGLE MINES LIMITED | CONSOLIDATED BALANCE SHEETS', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:17.159937+00:00', '2026-06-17T12:00:17.159937+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-14-004840', '6-K', '2014-05-12', '2014-03-31', 2014, 'Q1', 'quarter', 'Consolidated', 'gold', 2014.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746914004840/a2219806zex-99_1.htm', 'on the recommendations of the World Gold Council in 2013, the Company has modified its calculation of all-in sustaining costs per ounce of gold produced for 2014 as the aggregate | of total cash costs per ounce of gold produced and sustaining capital expenditures (including capitalized exploration), general and administrative expenses (including stock options) and non-cash | reclamation provision expense per ounce of gold produced. | 19 | The | following table sets out a reconciliation of production costs to all-in sustaining costs per ounce of gold produced for the first quarter of 2014. | (United States dollars per ounce of gold produced, except where noted) | Three Months Ended | March 31, 2014 | Production costs per the consolidated statements of income and comprehensive income (thousands of United States dollars) | $ | 224,091 | Adjusted gold production (ounces)', 'production-v2', 0.8, '2026-06-17T12:00:16.953252+00:00', '2026-06-17T12:00:16.953252+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-14-034306', '6-K', '2014-05-05', '2014-05-01', 2014, NULL, 'quarter', 'Consolidated', 'gold', 2014.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465914034306/a14-11829_1ex99d1.htm', '· | Ventilation and cooling system at LaRonde now fully operational — | expected to have a positive impact on operating flexibility especially during the summer | · | 2014 production expected to exceed the high end of guidance with costs expected to be better than the low end of the forecast range | Payable gold production | 2 | in the first quarter of 2014 was 366,421 ounces compared to 236,975 ounces | in the first quarter of 2013. | The higher level of production in the 2014 period was primarily due to higher grades at Meadowbank, a full quarter of production at Goldex, higher grades and better recoveries at LaRonde, and the ramp-up to commercial production at La India, where commercial production was achieved as of February 2014. A description of the production and cost performance for each mine is set out further below. | Total cash costs for the first quarter of 2014 were $537 per ounce. This compares with $740 per ounce in the first quarter of 2013. The lower costs in the 2014 period were largely attributable to record quarterly production and lower costs at Meadowbank and higher grades at LaRonde. | Given the strong first quarter 2014 production, the Company now expects gold production to exceed the higher end of the 2014 guidance range of 1,175,000 to 1,205,000 ounces, while total cash costs are forecast to be better than the lower end of the guidance range of $670 to $690 per ounce. | As noted in the year-end 2013 results (see February 12, 2014 news release), 2014 production is expected to be higher in the first half of the year, largely due to higher expected grades at Meadowbank. For the full year 2014, the all-in sustaining costs', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:16.992992+00:00', '2026-06-17T12:00:16.992992+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-14-009152', '6-K', '2014-11-13', '2014-09-30', 2014, 'Q3', 'quarter', 'existing mine sites.', 'gold', 2014.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746914009152/a2221927zex-99_1.htm', 'existing mine sites. | Amortization | of property, plant and mine development increased by $38.1 million to $117.4 million between the third quarter of 2013 and the third quarter of 2014 due | primarily to the consolidation of the acquired interest in the Canadian Malartic mine and the achievement of commercial production at the La India mine and at the Goldex mine''s M and E Zones between | periods. The overall increase in amortization of property, plant and mine development was partially offset by impairment losses recorded on property, plant and mine development at the Meadowbank and | Lapa mines as at December 31, 2013 and decreased gold production at the Meadowbank and Kittila mines between the third quarter of 2013 and the third quarter of 2014. | General | and administrative expense increased to $25.0 million during the third quarter of 2014 compared with $24.0 million during the third quarter of 2013 due primarily to | increased acquisition-related legal and consulting expenses in the third quarter of 2014. Partially offsetting the overall increase in general and administrative expense, employee compensation and | insurance expenses decreased between periods. | An | impairment loss on certain available-for-sale securities of $0.5 million was recorded as at September 30, 2014 compared with $0.3 million as at | September 30, 2013. Impairment loss evaluations of available-for-sale securities are based on whether a decline in fair value is considered to be significant or prolonged. A gain of', 'production-v2', 0.8, '2026-06-17T12:00:16.662410+00:00', '2026-06-17T12:00:16.662410+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-15-010132', '6-K', '2015-02-13', '2015-02-12', 2015, NULL, 'quarter', 'Consolidated', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465915010132/a15-4366_1ex99d1.htm', 'For the full year 2014, payable production was 92,622 ounces of gold at total cash costs per ounce on a by-product basis of $667. The prior year production was 100,730 ounces of gold at total cash costs per ounce on a by-product basis of $677. Production in 2014 | 30 | was lower due to reduced grades, while costs were lower due to successful cost cutting measures implemented by the Company. | At Lapa, 2014 and 2015 are the last two years of full production based on the current life of mine plan. In 2016, production is expected to exhibit a decline from the current levels. Additional exploration drilling in the parallel Zulapa Z8 zone and on the adjoining Pandora property could potentially extend the mine life (see discussion under the Canadian Malartic General Partnership). | Goldex — Higher Tonnage, Grades and Recoveries Drive Increased Gold Production and Lower Cash Costs | The 100% owned Goldex mine in northwestern Quebec began operation in 2008 but mining operations in the original Goldex Extension Zone (GEZ) orebody were suspended in October 2011 (see October 19, 2011 news release). In July 2012, the M and E satellite zones were approved for development. Mining operations at GEZ remain suspended. Mining operations resumed on the M and E satellite zones in September 2013. Initial mill testing, late in the third quarter of 2013, yielded 1,505 ounces of pre-commercial gold production. The Goldex mine achieved commercial production in the fourth quarter of 2013. | The Goldex mill processed an average of 6,251 tpd in the fourth quarter of 2014. This compares with an average of 5,343 tpd in the fourth quarter of 2013. The higher throughput in the 2014 period was due to better than expected underground mining rates compared to the 2013 period. | Minesite costs per tonne were approximately C$34 in the fourth quarter of 2014, lower than the C$37 per tonne experienced in the fourth quarter of 2013. The decrease in costs over the prior-year period is partly due to acceler', 'production-v2', 0.8, '2026-06-17T12:00:16.529367+00:00', '2026-06-17T12:00:16.529367+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-15-006800', '6-K', '2015-08-12', '2015-06-30', 2015, 'Q2', 'quarter', 'Consolidated', 'gold', 2015.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746915006800/a2225677zex-99_1.htm', 'due primarily to increases in gold grade and tonnes of ore milled, partially offset by a decrease in tonnes of ore stacked on the heap leach pad between periods. Production costs at the Pinos Altos | mine were $54.0 million in the first six months of 2015, a decrease of 12.0% compared with production costs of $61.4 million in the first six months of 2014 driven primarily by a | weakening of the Mexican peso relative to the US dollar and a decrease in tonnes of ore stacked on the heap leach pad between periods, partially offset by an increase in mill throughput between | periods. | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production increased by 39.9% to 15,606 ounces in the second quarter of 2015 | compared with 11,159 ounces in the second quarter of 2014 due primarily to a 54.1% increase in ore stacked on the heap leach pad, partially offset by a decrease in gold grade between periods. | Production costs at the Creston Mascota deposit at Pinos Altos were $7.5 million in the second quarter of 2015, | 10 | AGNICO EAGLE MINES LIMITED | MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | for the three and six months ended June 30, 2015', 'production-v2', 0.8, '2026-06-17T12:00:16.163095+00:00', '2026-06-17T12:00:16.163095+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-15-055665', '6-K', '2015-08-04', '2015-08-04', 2015, NULL, 'quarter', 'Consolidated', 'gold', 2015.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465915055665/a15-16061_2ex99d1.htm', '. | 6 | NORTHERN BUSINESS OPERATING REVIEW | ABITIBI REGION, QUEBEC | Agnico Eagle is currently Quebec’s largest gold producer with a 100% interest in three mines (LaRonde, Goldex and Lapa) and a 50% interest in the Canadian Malartic mine. These mines are located within 50 kilometres of each other, which provides operating synergies and allows for the sharing of technical expertise. | LaRonde Mine — Gold Production Steadily Increasing, Commissioning of Coarse Ore Conveyor on Track for Late Q3 2015 | The 100% owned LaRonde mine in northwestern Quebec achieved commercial production in 1988. | The LaRonde mill processed an average of 6,242 tonnes per day (“tpd”) in the second quarter of 2015, compared with an average of 6,197 tpd in the corresponding period of 2014. Minesite costs per tonne | 4 | were approximately C$99 in the second quarter of 2015, higher than the C$96 per tonne experienced in the second quarter of 2014. The increased costs in the 2015 period were primarily due to higher underground development, mill maintenance and site administration costs compared to the prior-year period. | For the first six months of 2015, the LaRonde mill processed an average of 6,223 tpd, compared to 6,194 tpd in the first six months of 2014. Minesite costs per tonne were approximately C$101, compared to C$96 per tonne in the first six months of 2014. Costs were higher due to the reasons described above in spite of the higher throughput. | LaRonde’s total cash costs per ounce on a by-product basis were $613 in the second quarter of 2015 on payable production of 64,007 ounces of gold. This compares with the second quarter of 2014 when total cash costs per ounce on a by-product basis were $732 on production of 48,494 ounces of gold. Costs in the 2015 period were positively impacted by higher gold grades and favourable foreign exchange rates. | In the first six months of 2015, LaRonde produced 122,900 ounces of gold at total cash costs per ounce of $656 on a by-product basis. Thi', 'production-v2', 0.8, '2026-06-17T12:00:16.219099+00:00', '2026-06-17T12:00:16.219099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-15-055665', '6-K', '2015-08-04', '2015-08-04', 2015, NULL, 'quarter', 'Consolidated', 'silver', 2014.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465915055665/a15-16061_2ex99d1.htm', 'The Pinos Altos mill processed 5,854 tpd in the second quarter of 2015, compared to 5,513 tpd processed in the second quarter of 2014. During the second quarter of 2015, approximately 114,800 tonnes of ore were stacked on the leach pad at Pinos Altos, compared to 154,200 tonnes in the comparable 2014 period. Minesite costs per tonne at Pinos Altos were $43 in the second quarter of 2015, slightly lower than the $46 in the second quarter of 2014. The difference in minesite costs per tonne was largely attributable to variations in the proportion of heap leach ore to milled ore and open pit ore to underground ore, currency variations and routine fluctuations in the waste to ore stripping ratio in the open pit mines. | For the first six months of 2015, the Pinos Altos mill processed an average of 5,758 tpd, compared to 5,448 tpd processed in the first six months of 2014. Approximately 189,200 tonnes of ore were stacked on the Pinos Altos leach pad during the first six months of 2015, compared to 293,300 tonnes in the prior year period. Minesite costs per tonne were approximately $45 compared to $48 per tonne in the first six months of 2014 with variance due to the proportion of heap leach to mill ore and the proportion of underground ore to open pit, and variations in the proportion of waste to ore mined, and variations in the currency exchange rate. | 24 | Payable production in the second quarter of 2015 was 50,647 ounces of gold at a total cash costs per ounce on a by-product basis of $384. This compares with production of 43,978 ounces at total cash costs per ounce on a by-product basis of $516 in the second quarter of 2014. Higher production in 2015 is largely due to higher throughput and higher grades processed over the comparable prior year period. The decrease in the year over year total cash costs per ounce is largely due to higher silver production (offset, in part by a decline in realized silver prices) and favourable foreign exchange rates compared to the prio', 'production-v2', 0.8, '2026-06-17T12:00:16.219099+00:00', '2026-06-17T12:00:16.219099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-15-008179', '6-K', '2015-10-30', '2015-09-30', 2015, 'Q3', 'quarter', 'Consolidated', 'gold', 136298.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746915008179/a2226298zex-99_1.htm', 'are a number of factors that can significantly impact the Company''s effective tax rate including varying rates in different jurisdictions, the non-recognition of certain tax | assets, mining allowances, foreign currency exchange rate movements, changes in tax laws, the impact of specific transactions and assessments and the relative distribution of income in the Company''s | operating jurisdictions. As a result of these factors, the Company''s effective tax rate is expected to fluctuate in future periods. | Nine Months Ended September 30, 2015 vs. Nine Months Ended September 30, 2014 | In the first nine months of 2015, revenues from mining operations increased to $1,502.5 million from $1,393.7 million in | the first nine months of 2014 due primarily to a 19.9% increase in gold production and a 21.0% increase in silver production between periods. An incremental increase of 136,298 | attributable ounces of gold production from the Canadian Malartic mine which was jointly acquired on June 16, 2014, higher gold grade and tonnes of ore milled at the LaRonde mine, an | increase in tonnes of ore milled at the Kittila mine, and the ramp up of production from the La India mine which achieved commercial production in February 2014, partially offset by a 19.4% | decrease in gold grade at the Meadowbank mine, resulted in a 207,259 ounce net increase in total gold production between the first nine months of 2014 and the first nine months of 2015. | Partially offsetting the impact of increased gold and silver production on revenues from mining operations was a 8.7% decrease in the average realized price of gold, a 17.0% decrease in the average | realized price of silver and a 69.0% decrease in zinc production between periods. | Production | costs were $765.5 million in the first nine months of 2015, a 6.7% increase compared with $717.2 million in the first nine months of 2014 due primarily to a', 'production-v2', 0.8, '2026-06-17T12:00:16.006046+00:00', '2026-07-01T23:01:51.680442+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-15-004674', '6-K', '2015-05-12', '2015-12-05', 2015, 'FY', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2015.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746915004674/a2224749zex-99_1.htm', 'AGNICO EAGLE MINES LIMITED | MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | for the three months ended March 31, 2015 | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production increased 20.7% to 12,448 ounces in the first quarter of 2015 | compared with 10,317 ounces in the first quarter of 2014 due primarily to increases in ore stacked on the heap leach pad and gold grade. Production costs at the Creston Mascota deposit at Pinos | Altos decreased by 3.8% to $5.6 million in the first quarter of 2015 compared with $5.8 million in the first quarter of 2014 due primarily to a weakening of the Mexican peso relative to | the US dollar between periods. | La India mine | The La India mine achieved commercial production on February 1, 2014. During the first quarter of 2015, the La India mine | produced 26,523 ounces of gold compared with 13,700 ounces of gold in the first quarter of 2014, including 3,492 ounces of gold produced prior to the achievement of commercial | production. Production costs at the La India mine were $12.5 million in the first quarter of 2015 compared with $5.8 million in the first quarter of 2014 due primarily to the operations', 'production-v2', 0.8, '2026-06-17T12:00:16.306783+00:00', '2026-06-17T12:00:16.306783+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-16-096379', '6-K', '2016-02-12', '2016-02-10', 2016, NULL, 'quarter', ', and the potential to mine a portion of the', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465916096379/a16-4175_1ex99d1.htm', '. These opportunities, and the potential development of the Akasaba West deposit (see below), could enhance production levels or extend the current mine life and reduce operating costs. | In January 2014, Agnico Eagle acquired the | Akasaba West | gold-copper deposit from Alexandria Minerals. Located less than 30 km from Goldex, the Akasaba West deposit could create flexibility and synergies for the Company’s operations in the Abitibi region by utilizing extra milling capacity at both Goldex and LaRonde, while reducing overall costs. Akasaba West currently hosts a probable mineral reserve of 141,000 ounces of gold and | 15 | 24,557 tonnes of copper (4.76 million tonnes grading 0.92 g/t gold and 0.52% copper). Permitting and technical studies are ongoing with the goal of moving the project towards a production decision in late 2016 or early 2017. | Kittila Optimization | Previous drilling on the | Rimpi Zone | at Kittila has outlined a significant zone of mineralization with potentially wider widths and better grades than those currently being mined. The main underground ramp at Kittila is being extended to reach the Rimpi Zone, and it is also providing further underground drill access to test for additional depth extensions of the Rimpi, Suuri, Roura and the newly discovered Sisar mineralized zones. | In addition, a surface ramp is being driven into the Rimpi Zone (now at a depth of 190 metres below surface) for production purposes and to provide a second egress for the Suuri ramp system. It will serve as the main haulage route from the deeper portions of both Rimpi and Suuri and potentially the | Sisar Zone | .', 'production-v2', 0.8, '2026-06-17T12:00:15.928792+00:00', '2026-06-17T12:00:15.928792+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-16-096379', '6-K', '2016-02-12', '2016-02-10', 2016, NULL, 'quarter', 'Consolidated', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465916096379/a16-4175_1ex99d1.htm', 'Rehabilitation of the surface ramp has been completed which provides increased operational flexibility. This ramp also provides access to the M2 and M5 satellite zones for conversion drilling and development later this year. | The exploration ramp into the DX Zone (the top of the Deep Zone) has reached the 120 level, which is the proposed bottom of the Deep 1 development phase. Underground | 36 | development in the Deep 1 Zone will now shift to excavation of the various sublevels needed for mining development and excavation of the conveyor ramp. | Studies are underway to evaluate the potential to increase throughput from the Deep 1 Zone, and the potential to mine a portion of the Deep 2 Zone, both of which could enhance production levels or extend the current mine life at Goldex and reduce operating costs. | In January 2014, Agnico Eagle acquired the Akasaba West gold-copper deposit from Alexandria Minerals. Located less than 30 km from Goldex, the Akasaba West deposit could potentially create flexibility and synergies for the Company’s operations in the Abitibi region by utilizing extra milling capacity at both Goldex and LaRonde, while reducing overall costs. Permitting and technical studies are ongoing with the goal of moving the project towards a production decision in late 2016 or early 2017. | FINLAND AND SWEDEN | Agnico Eagle’s Kittila mine in Finland is the largest primary gold producer in Europe and hosts the Company’s largest mineral reserves. Exploration activities continue to expand the mineral resources and studies are underway to evaluate the potential to cost-effectively increase production. | Kittila — Strong Mining Performance in Q4 2015 and Available Mill Capacity Provide Potential for Increased Future Production | The 100% owned Kittila mine in northern Finland achieved commercial production in 2009. | The focus at Kittila in 2015 was on improving mill reliability. Several projects were carried out in the fourth quarter of 2015 which appear to hav', 'production-v2', 0.8, '2026-06-17T12:00:15.928792+00:00', '2026-06-17T12:00:15.928792+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-16-012725', '6-K', '2016-04-29', '2016-03-31', 2016, 'Q1', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2016.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746916012725/a2228334zex-99_1.htm', 'AGNICO EAGLE MINES LIMITED | MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three Months Ended March 31, 2016 | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production decreased by 7.2% to 11,551 ounces in the first quarter of 2016 | compared with 12,448 ounces in the first quarter of 2015 primarily due to a decrease in ore stacked on the heap leach pad and a decrease in gold grade between periods. Production costs at the | Creston Mascota deposit at Pinos Altos were $5.8 million in the first quarter of 2016, an increase of 3.1% compared with production costs of $5.6 million in the first quarter of 2015 | driven primarily by increased heap leach costs, partially offset by a weakening of the Mexican peso relative to the US dollar. | La India mine | At the La India mine, gold production increased by 6.4% to 28,231 ounces in the first quarter of 2016 compared with | 26,523 ounces in the first quarter of 2015 primarily due to an increase in ore stacked on the heap leach pad between periods. Production costs at the La India mine were $10.9 million in | the first quarter of 2016, a decrease of 12.4% compared with production costs of $12.5 million in the first quarter of 2015 driven primarily by a weakening of the Mexican peso relative to the', 'production-v2', 0.8, '2026-06-17T12:00:15.784248+00:00', '2026-06-17T12:00:15.784248+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-16-014517', '6-K', '2016-07-28', '2016-06-30', 2016, 'Q2', 'quarter', 'Consolidated', 'gold', 2015.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746916014517/a2229221zex-99_1.htm', 'In | the first six months of 2016, Agnico Eagle reported net income of $46.8 million, or $0.21 per share, compared with net income of $38.8 million, or $0.18 per share, in | the first six months of 2015. Agnico Eagle reported adjusted net income of $60.7 million, or $0.27 per share, in the first half of 2016 compared with adjusted net income of | $49.9 million, or $0.23 per share, in the first half of 2015. In the first half of 2016, operating margin (revenues from mining operations less production costs) increased to | $528.8 million from $482.8 million in the first half of 2015 primarily due to a 1.5% increase in gold production, a 2.6% increase in the average realized price of gold and a 2.2% | decrease in production costs between periods. Gold production increased to 820,268 ounces in the first six months of 2016 compared with 807,888 ounces in the first six months of 2015 | primarily due to higher gold grades at the LaRonde mine and an increase in tonnes of ore milled at the LaRonde, Goldex, and Canadian Malartic mines. Partially offsetting the overall increase in gold | production | 3 | AGNICO EAGLE MINES LIMITED | MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Six Months Ended June 30, 2016', 'production-v2', 0.8, '2026-06-17T12:00:15.692549+00:00', '2026-06-17T12:00:15.692549+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-16-016432', '6-K', '2016-11-01', '2016-09-30', 2016, 'Q3', 'quarter', 'Consolidated', 'gold', 2016.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746916016432/a2230110zex-99_1.htm', 'production decreased by 1.6% to 146,087 ounces in the first nine months of 2016 compared with 148,478 ounces in the first nine months of 2015 at the Pinos Altos mine, | due primarily to decreases in mill throughput and recoveries between periods. Production costs at the Pinos Altos mine were $88.1 million in the first nine months of 2016, an increase of 9.0% | compared with production costs of $80.8 million in the first nine months of 2015 driven primarily by the timing of inventory shipments, partially offset by a weakening of the Mexican peso | relative to the US dollar and a decrease in mill throughput between periods. | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production decreased by 4.6% to 12,134 ounces in the third quarter of 2016 | compared with 12,716 ounces in the third quarter of 2015 primarily due to a decrease in gold grade between periods, partially offset by an increase in tonnes stacked. Production costs at the | Creston Mascota deposit at Pinos Altos were $7.0 million in the third quarter of 2016, an increase of 15.0% compared with production costs of $6.1 million in the third quarter of 2015 | driven primarily by increased heap leach costs, partially offset by a weakening of the Mexican peso relative to the US dollar. | 9 | AGNICO EAGLE MINES LIMITED | MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards)', 'production-v2', 0.8, '2026-06-17T12:00:15.517292+00:00', '2026-06-17T12:00:15.517292+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-17-003035', '6-K', '2017-04-28', '2017-03-31', 2017, 'Q1', 'quarter', 'Pinos Altos mine', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746917003035/a2231960zex-99_1.htm', 'At the Pinos Altos mine, gold production decreased by 5.8% to 45,360 ounces in the first quarter of 2017 compared with | 48,117 ounces in the first quarter of 2016 primarily due to lower gold grade. Production costs at the Pinos Altos mine were $23.7 million in the first quarter of 2017, a decrease of 0.5% | compared with production costs of $23.9 million in the first quarter of 2016 driven primarily by a weakening of the Mexican peso relative to the US dollar, partially offset by increased mill | throughput. | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production decreased by 2.7% to 11,244 ounces in the first quarter of 2017 | compared with 11,551 ounces in the first quarter of 2016 primarily due to a decrease in gold grade between periods, partially offset by an increase in tonnes stacked. Production costs at the | Creston Mascota deposit at Pinos Altos were $7.0 million in the first quarter of 2017, an increase of 20.7% compared with production costs of $5.8 million in the first quarter of 2016 | driven primarily by the increase in tonnes of ore stacked, partially offset by a weakening of the Mexican peso relative to the US dollar. | La India mine | At the La India mine, gold production decreased by 6.9% to 26,296 ounces in the first quarter of 2017 compared with | 28,231 ounces in the first quarter of 2016 primarily due to lower gold grade. Production costs at the La India mine were $13.1 million in the first quarter of 2017, an increase of 20.1% | compared with production costs of $10.9 million in the first quarter of 2016 driven primarily by an increase in tonnes of ore stacked, partially offset by a weakening of the Mexican peso', 'production-v2', 0.8, '2026-06-17T12:00:15.170524+00:00', '2026-06-17T12:00:15.170524+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-17-004810', '6-K', '2017-07-27', '2017-06-30', 2017, 'Q2', 'quarter', 'Pinos Altos mine', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746917004810/a2232771zex-99_1.htm', 'Gold | production decreased by 4.1% to 93,556 ounces in the first six months of 2017 compared with 97,575 ounces in the first six months of 2016 at the Pinos Altos mine, due | primarily to lower gold grade between periods. Production costs at the Pinos Altos mine were $52.4 million in the first six months of 2017, a decrease of 0.5% compared with production costs of | $52.7 million in the first six months of 2016 driven primarily by a weakening of the Mexican peso relative to the US dollar, partially offset by an increase in mill throughput between periods. | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production decreased by 2.6% to 12,074 ounces in the second quarter of 2017 | compared with 12,398 ounces in the second quarter of 2016 primarily due to lower gold recoveries between periods, partially offset by an increase in the tonnes of ore stacked. Production costs | at the Creston Mascota deposit at Pinos Altos were $7.4 million in the second quarter of 2017, an increase of 11.1% compared with production costs of $6.6 million in the second quarter | of 2016 driven primarily by the increase in tonnes of ore stacked, partially offset by a weakening of the Mexican peso relative to the US dollar. | Gold | production decreased by 2.6% to 23,318 ounces in the first six months of 2017 compared with 23,949 ounces in the first six months of 2016 at the Creston Mascota | deposit at Pinos Altos primarily due to | 9', 'production-v2', 0.8, '2026-06-17T12:00:15.069719+00:00', '2026-06-17T12:00:15.069719+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-17-047616', '6-K', '2017-07-28', '2017-07-26', 2017, NULL, 'quarter', 'Consolidated', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465917047616/a17-18513_1ex99d1.htm', '(iii) Payable production (a non-GAAP non-financial performance measure) is the quantity of mineral produced during a period contained in products that have been or will be sold by the Company, whether such products are sold during the period or held as inventories at the end of the period. | (iv) The Canadian Malartic mine’s payable metal sold excludes the 5.0% net smelter royalty in favour of Osisko Gold Royalties Ltd.. | 48 | (v) Total cash costs per ounce of gold produced is not a recognized measure under IFRS and this data may not be comparable to data reported by other gold producers. Total cash costs per ounce of gold produced is reported on both a by-product basis (deducting by-product metal revenues from production costs) and co-product basis (without deducting by-product metal revenues). Total cash costs per ounce of gold produced on a by-product basis is calculated by adjusting production costs as recorded in the condensed interim consolidated statement of income for by-product metal revenues, unsold concentrate inventory production costs, smelting, refining and marketing charges and other adjustments, and then dividing by the number of ounces of gold produced. Total cash costs per ounce of gold produced on a co-product basis is calculated in the same manner as total cash costs per ounce of gold produced on a by-product basis except that no adjustment for by-product metal revenues is made. Accordingly, the calculation of total cash costs per ounce of gold produced on a co-product basis does not reflect a reduction in production costs or smelting, refining and marketing charges associated with the production and sale of by-product metals. The Company believes that these generally accepted industry measures provide a realistic indication of operating performance and provide useful comparison points between periods. Total cash costs per ounce of gold produced is intended to provide information about the cash generating capabilities of the Company’s mining ope', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:15.002589+00:00', '2026-06-17T12:00:15.002589+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-17-006574', '6-K', '2017-10-26', '2017-09-30', 2017, 'Q3', 'quarter', 'La India mine', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746917006574/a2233637zex-99_1.htm', 'MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Nine Months Ended September 30, 2017 | La India mine | At the La India mine, gold production decreased by 18.3% to 25,143 ounces in the third quarter of 2017 compared with | 30,779 ounces in the third quarter of 2016 primarily due to lower gold grade ore being processed. Production costs at the La India mine were $16.0 million in the third quarter of 2017, | an increase of 31.4% compared with production costs of $12.2 million in the third quarter of 2016 driven primarily by higher contractor costs and the timing of inventory. | Gold | production decreased by 12.5% to 75,650 ounces in the first nine months of 2017 compared with 86,448 ounces in the first nine months of 2016 primarily due to lower | gold grade ore being processed. Production costs at the La India mine were $44.1 million in the first nine months of 2017, an increase of 25.5% compared with production costs of | $35.1 million in the first nine months of 2016 driven primarily by higher contractor costs and the timing of inventory. | Liquidity and Capital Resources | As at September 30, 2017, the Company''s cash and cash equivalents, short-term investments and current restricted cash totaled', 'production-v2', 0.8, '2026-06-17T12:00:14.917352+00:00', '2026-06-17T12:00:14.917352+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-17-006574', '6-K', '2017-10-26', '2017-09-30', 2017, 'Q3', 'quarter', 'LaRonde mine', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746917006574/a2233637zex-99_1.htm', '71,784 ounces in the third quarter of 2016, primarily due to an increase in throughput levels and higher gold grade ore being processed. Production costs at the LaRonde mine were | $39.7 million in the third quarter of 2017, a decrease of 19.1% compared with production costs of $49.1 million in the third quarter of 2016 driven primarily by the timing of unsold | concentrate inventory. | Gold | production increased by 15.3% to 256,347 ounces in the first nine months of 2017 compared with 222,280 ounces in the first nine months of 2016 at the LaRonde mine, | primarily due to higher gold grade ore being processed. Production costs at the LaRonde mine were $130.7 million in the first nine months of 2017, | a decrease of 3.5% compared with production costs of $135.4 million in the first nine months of 2016 driven primarily by the timing of unsold concentrate inventory. | 7 | AGNICO EAGLE MINES LIMITED | MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Nine Months Ended September 30, 2017 | Lapa mine', 'production-v2', 0.8, '2026-06-17T12:00:14.917352+00:00', '2026-06-17T12:00:14.917352+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-17-006574', '6-K', '2017-10-26', '2017-09-30', 2017, 'Q3', 'quarter', 'Lapa mine', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746917006574/a2233637zex-99_1.htm', 'MANAGEMENT''S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Nine Months Ended September 30, 2017 | Lapa mine | At the Lapa mine, gold production increased by 5.7% to 17,169 ounces in the third quarter of 2017 compared with | 16,242 ounces in the third quarter of 2016, primarily due to higher gold grade ore being processed. Production costs at the Lapa mine were $12.1 million in the third quarter of 2017, | which was consistent with production costs of $12.2 million in the third quarter of 2016. | Gold | production decreased by 19.1% to 48,410 ounces in the first nine months of 2017 compared with 59,865 ounces in the first nine months of 2016 at the Lapa mine, | primarily due to a decrease in throughput levels and lower gold grade ore being processed. Production costs at the Lapa mine were $36.7 million in the first nine months of 2017, a 7.6% decrease | compared with production costs of $39.7 million in the first nine months of 2016, driven primarily by the expected decrease in mill throughput as the mine approaches the end | of operations. | Goldex mine', 'production-v2', 0.8, '2026-06-17T12:00:14.917352+00:00', '2026-06-17T12:00:14.917352+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-17-006574', '6-K', '2017-10-26', '2017-09-30', 2017, 'Q3', 'quarter', 'Pinos Altos mine', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746917006574/a2233637zex-99_1.htm', 'Gold | production decreased by 3.9% to 140,453 ounces in the first nine months of 2017 compared with 146,087 ounces in the first nine months of 2016 at the Pinos Altos mine, | due primarily to lower gold grade ore being processed through the mill. Production costs at the Pinos Altos mine were $78.0 million in the first nine months of 2017, a decrease of 11.5% | compared with production costs of $88.1 million in the first nine months of 2016 driven primarily by timing of inventory and lower materials costs. | Creston Mascota deposit at Pinos Altos | At the Creston Mascota deposit at Pinos Altos, gold production decreased by 8.9% to 11,054 ounces in the third quarter of 2017 | compared with 12,134 ounces in the third quarter of 2016 | primarily due to lower gold recoveries between periods, partially offset by an increase in the tonnes of ore processed. Production costs at the Creston Mascota deposit at Pinos Altos were | $7.8 million in the third quarter of 2017, an increase of 11.7% compared with production costs of $7.0 million in the third quarter of 2016 driven primarily by higher contractor costs. | Gold | production decreased by 4.7% to 34,372 ounces in the first nine months of 2017 compared with 36,083 ounces in the first nine months of 2016 at the Creston Mascota | deposit at Pinos Altos primarily due to lower gold recoveries, partially offset by an increase in tonnes processed. Production costs at the Creston Mascota deposit at Pinos Altos were | $22.2 million in the first nine months of 2017, an increase of 14.2% compared with production costs of $19.4 million in the first nine months of 2016 driven primarily by higher', 'production-v2', 0.8, '2026-06-17T12:00:14.917352+00:00', '2026-06-17T12:00:14.917352+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-17-064249', '6-K', '2017-10-27', '2017-10-27', 2017, NULL, 'quarter', 'Consolidated', 'gold', 100.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465917064249/a17-24530_1ex99d1.htm', '6 | NORTHERN BUSINESS REVIEW | ABITIBI REGION, QUEBEC | Agnico Eagle is currently Quebec’s largest gold producer with a 100% interest in three mines (LaRonde, Goldex and Lapa) and a 50% interest in the Canadian Malartic mine. These mines are located within 50 kilometres of each other, which provides operating synergies and allows for the sharing of technical expertise. | LaRonde — Higher than Expected Grades and Tonnage Drive Record Quarterly | Gold Production | The 100% owned LaRonde mine in northwestern Quebec achieved commercial production in 1988. | LaRonde Mine - Operating Statistics | All results exclude pre-commercial production tonnes and ounces | Three Months Ended | Three Months Ended | from LaRonde Zone 5 | September 30, 2017', 'production-v2', 0.8, '2026-06-17T12:00:14.843365+00:00', '2026-07-01T23:01:34.631371+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-18-003285', '6-K', '2018-04-27', '2018-03-31', 2018, 'Q1', 'quarter', 'Consolidated', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746918003285/a2235443zex-99_1.htm', 'Non-GAAP Financial | Performance Measures | in this MD&A. | In | the first quarter of 2018, the operating margin (revenues from mining operations less production costs) of $283.1 million decreased compared to $307.1 million in the | first quarter of 2017 primarily due to a 22.9% increase in production costs between periods. Gold production decreased to 389,278 ounces in the first quarter of 2018 compared with | 418,216 ounces in the first quarter of 2017 primarily due to an 18.7% decrease in gold grade at the Meadowbank mine and a decrease of 13,638 gold ounces produced at the Lapa mine as it | approaches the end of operations. Partially offsetting the overall decrease in gold production between the first quarter of 2018 and the first quarter of 2017 was a 19.1% increase in gold grade at the | LaRonde mine. Cash provided by operating activities amounted to $207.7 million in the first quarter of 2018 compared with $222.6 million in the first quarter of 2017. Total weighted', 'production-v2', 0.65, '2026-06-17T12:00:14.554069+00:00', '2026-06-17T12:00:14.554069+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-18-005198', '6-K', '2018-07-26', '2018-06-30', 2018, 'Q2', 'quarter', 'Goldex mine', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746918005198/a2236286zex-99_1.htm', 'production decreased by 48.0% to 16,255 ounces in the first six months of 2018 compared with 31,241 ounces in the first six months of 2017 at the Lapa mine, primarily | due to a decrease in the tonnes of ore being processed. Production costs at the Lapa mine were $11.3 million in the first six months of 2018, a 54.2% decrease compared with production costs of | $24.6 million in the first six months of 2017, driven primarily by the expected decrease in mill throughput as the mine approaches the end of operations. | Goldex mine | At the Goldex mine, gold production increased by 0.5% to 30,480 ounces in the second quarter of 2018 compared with | 30,337 ounces in the second quarter of 2017, primarily due to higher gold grade ore being processed. Production costs at the Goldex mine were $20.9 million in the second quarter of 2018, | an increase of 42.4% compared with production costs of $14.7 million in the second quarter of 2017, driven primarily by an increase in the cost of maintenance contractors and consumables. | Gold | production decreased by 7.3% to 58,404 ounces in the first six months of 2018 compared with 63,008 ounces in the first six months of 2017 at the Goldex mine, primarily | due to lower gold grade and a decrease in the tonnes of ore being processed. Production costs at the Goldex mine were $39.5 million in the first six months of 2018, an increase of 25.2% | compared with production costs of $31.6 million in the first six months of 2017, driven primarily by an increase in the cost of maintenance contractors and consumables. | Meadowbank mine | At the Meadowbank mine, gold production decreased by 37.4% to 59,627 ounces in the second quarter of 2018 compared with', 'production-v2', 0.8, '2026-06-17T12:00:14.398494+00:00', '2026-06-17T12:00:14.398494+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-18-006858', '6-K', '2018-10-25', '2018-09-30', 2018, 'Q3', 'quarter', 'Consolidated', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746918006858/a2236956zex-99_1.htm', 'inventory and other adjustment reflects production costs associated with the portion of production still in inventory and smelting, refining and | marketing charges associated with production. | (vi) | The | LaRonde Zone 5 mine''s per ounce of gold production calculations exclude 515 ounces for the three and nine months ended | September 30, 2017 of payable gold production and the associated costs which were produced prior to the achievement of commercial production on June 1, 2018. | (vii) | The | LaRonde Zone 5 mine''s per tonne calculations exclude 7,709 tonnes for the three and nine months ended September 30, 2017 and the | associated costs which were processed prior to the achievement of commercial production on June 1, 2018. | (viii) | The | Goldex mine''s data presented on a per ounce of gold produced basis for the nine months ended September 30, 2017 excludes 8,041 ounces', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:14.169118+00:00', '2026-06-17T12:00:14.169118+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-18-006858', '6-K', '2018-10-25', '2018-09-30', 2018, 'Q3', 'quarter', 'Goldex mine', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746918006858/a2236956zex-99_1.htm', 'primarily due to an expected decrease in the tonnes of ore being processed. Production costs at the Lapa mine were $17.3 million in the first nine months of 2018, a 52.8% decrease compared with | production costs of $36.7 million in the first nine months of 2017, driven primarily by the expected decrease in underground mining and development costs as the mine approaches the end | of operations. | Goldex mine | At the Goldex mine, gold production increased by 8.1% to 31,255 ounces in the third quarter of 2018 compared with | 28,906 ounces in the third quarter of 2017, primarily due to higher gold grade ore being processed. Production costs at the Goldex mine were $19.3 million in the third quarter of 2018, | an increase of 9.3% compared with production costs of $17.7 million in the third quarter of 2017, | driven primarily by higher underground maintenance costs during a planned shutdown and the timing of inventory. | Gold | production decreased by 2.5% to 89,659 ounces in the first nine months of 2018 compared with 91,914 ounces in the first nine months of 2017 at the Goldex mine, | primarily due to a decrease in the tonnes of ore being processed. Production costs at the Goldex mine were $58.8 million in the first nine months of 2018, an increase of 19.5% compared with | production costs of $49.2 million in the first nine months of 2017, driven primarily by an increase in underground production, maintenance, contractor and consumable costs. | 7', 'production-v2', 0.8, '2026-06-17T12:00:14.169118+00:00', '2026-06-17T12:00:14.169118+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-18-064031', '6-K', '2018-10-26', '2018-10-25', 2018, NULL, 'quarter', 'Consolidated', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465918064031/a18-37019_3ex99d1.htm', 'Minesite costs per tonne in the first nine months of 2018 increased when compared to the prior-year period due to reasons described above. Total cash costs per ounce in the first nine months of 2018 increased when compared to the prior-year period due to lower gold production and the reasons described above. | Gold production in the first nine months of 2018 decreased when compared to the prior-year period due to lower tonnes processed at lower grades which was as a result of delays in accessing the main Bravo pit as described above. | A new waste rock storage site has been located closer to the Bravo deposit, which is expected to reduce waste haulage costs. Permits for this new waste dump are expected to be received by the end of 2018. | 34 | Work relating to the Phase V heap leach pad expansion was paused from mid-August to late September as a result of the rainy season. The heap leach pad expansion is ongoing and proceeding on budget with completion now expected in the fourth quarter of 2018. | La India — Heap Leach Optimization Initiatives Completed; Improved Gold Production in the Third Quarter of 2018 | The La India mine in Sonora, Mexico, located approximately 70 kilometres northwest of the Company’s Pinos Altos mine, achieved commercial production in February 2014. | La India Mine - Operating Statistics | Three Months Ended | Three Months Ended | September 30, 2018 | September 30, 2017 | Tonnes of ore processed (thousands of tonnes)', 'production-v2', 0.8, '2026-06-17T12:00:14.028803+00:00', '2026-06-17T12:00:14.028803+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-19-009196', '6-K', '2019-02-19', '2019-02-14', 2019, NULL, 'quarter', 'Consolidated', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465919009196/a19-4871_1ex99d1.htm', '(ii) Operating margin is calculated as revenues from mining operations less production costs. | (iii) The information set out in this table reflects the Company’s 50% interest in the Canadian Malartic mine. | (iv) Payable production (a non-GAAP non-financial performance measure) is the quantity of mineral produced during a period contained in products that have been or will be sold by the Company, whether such products are sold during the period or held as inventories at the end of the period. | (v) The Canadian Malartic mine’s payable metal sold excludes the 5.0% net smelter royalty in favour of Osisko Gold Royalties Ltd. | (vi) Total cash costs per ounce of gold produced is not a recognized measure under IFRS and this data may not be comparable to data reported by other gold producers. Total cash costs per ounce of gold produced is presented on both a by-product basis (deducting by-product metal revenues from production costs) and co-product basis (without deducting by-product metal revenues). Total cash costs per ounce of gold produced on a by-product basis is calculated by adjusting production costs as recorded in the consolidated statements of income for by-product metal revenues, inventory production costs, smelting, refining and marketing charges, other adjustments, and then dividing by the number of ounces of gold produced. Total cash costs per ounce of gold produced on a co-product basis is calculated in the same manner as total cash costs per ounce of gold produced on a by-product basis except that no adjustment for by-product metal revenues is made. Accordingly, the calculation of total cash costs per ounce of gold produced on a co-product basis does not reflect a reduction in production costs or smelting, refining and marketing charges and other adjustments associated with the production and sale of by-product metals. The Company believes that these generally accepted industry measures provide a realistic indication of operating performance and provide u', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:13.893016+00:00', '2026-06-17T12:00:13.893016+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-19-002610', '6-K', '2019-04-26', '2019-03-31', 2019, 'Q1', 'quarter', 'Canadian Malartic mine', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746919002610/a2238546zex-99_1.htm', 'Canadian Malartic mine | Agnico Eagle and Yamana Gold Inc. ("Yamana") jointly acquired 100% of Osisko Mining Corporation ("Osisko") on June 16, 2014 pursuant to | a court-approved plan of arrangement under the Canada Business Corporations Act (the "Osisko Arrangement"). As a result of the Osisko Arrangement, Agnico Eagle and Yamana each indirectly own 50% of | Osisko and Canadian Malartic General Partnership ("CMGP"), a general partnership (the "Partnership"), which now holds the Canadian Malartic mine in northwestern Quebec. | At | the Canadian Malartic mine, attributable gold production was virtually unchanged between 83,670 ounces in the first quarter of 2019 and 83,403 ounces in the first quarter of 2018. | Attributable production costs at the Canadian Malartic mine were $49.8 million in the first quarter of 2019, an increase of 5.2% compared with production costs of $47.3 million in the first quarter of | 2018 primarily due to a lower capitalized deferred stripping costs, partially offset by lower re-handling costs and the weakening of the Canadian dollar relative to the US dollar between periods. | On | August 2, 2016, CMGP was served with a class action lawsuit filed in the Superior Court of Quebec with respect to allegations involving the Canadian Malartic mine. The complaint was | in respect of "neighbourhood annoyances" arising from dust, noise, vibrations and blasts at the mine. The plaintiffs are seeking damages in an unspecified amount as well as punitive damages in the | amount of C$20 million. The class action was certified in May 2017. In November 2017, a declaratory judgment was issued allowing the Partnership to settle individually with class members for 2017 | under its Good Neighbor Guide (the "Guide"). In September 2018, the Superior Court introduced an annual revision of the ending date of the class action period and a mechanism for the partial exclusion', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:13.586440+00:00', '2026-06-17T12:00:13.586440+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-19-002610', '6-K', '2019-04-26', '2019-03-31', 2019, 'Q1', 'quarter', 'Creston Mascota mine', 'gold', 11988.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746919002610/a2238546zex-99_1.htm', 'At the Pinos Altos mine, gold production increased by 2.1% to 42,730 ounces in the first quarter of 2019 compared with 41,836 ounces in | the first quarter of 2018 primarily due to higher gold grade ore processed at the mill. Production costs at the Pinos Altos mine were $29.7 million in the first quarter of 2019, a decrease of 14.5% | compared with production costs of $34.7 million in the first quarter of 2018 driven primarily by a decrease in open pit mining costs as the Pinos Altos mine transitioned into a predominantly | underground mining operation towards the end of 2018, the timing of inventory sales and the weakening of the Mexican peso relative to the US dollar between periods. | Creston Mascota mine | At the Creston Mascota mine, gold production increased by 12.9% to 13,529 ounces in the first quarter of 2019 compared with 11,988 | ounces in the first quarter of 2018 primarily due to higher gold grade processed on the heap leach and optimizations made to the heap leaching process, partially offset by lower tonnes processed at | the heap leach. Production costs at the Creston Mascota mine were $9.8 million in the first quarter of 2019, an increase of 1.9% compared with production costs of $9.7 million in the first quarter of | 2018 driven primarily by the timing of inventory sales, partially offset by the weakening of the Mexican peso relative to the US dollar between periods. | La India mine | At the La India mine, gold production was virtually unchanged between 22,988 ounces in the first quarter of 2019 and 23,055 ounces in | the first quarter of 2018. Production costs at the La India mine were $17.7 million in the first quarter of 2019, an increase of 15.2% compared with production costs of $15.4 million in the first | quarter of 2018 driven primarily by higher chemicals and reagents costs, the timing of inventory sales, partially offset by the weakening of the Mexican peso relative to the US dollar between periods.', 'production-v2', 0.8, '2026-06-17T12:00:13.586440+00:00', '2026-07-01T23:01:25.027648+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-19-025233', '6-K', '2019-04-30', '2019-04-25', 2019, NULL, 'quarter', 'Amaruq drilling continues to infill and expand known mineralized zones', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465919025233/a19-9048_1ex99d1.htm', '— Highlights include 14.7 g/t gold over 11.5 metres at 170 metres depth at Trinidad and 5.1 g/t gold over 4.5 metres at 33 metres depth at Greta. Additional work is planned to test new targets and further expand the mineral resource potential | · | Kirkland Lake drilling expands near-surface deposits at Upper Beaver and extends mineralization at depth | — Shallow drilling has yielded 3.63 g/t gold and 0.21% copper over 14.0 metres at 102 metres depth, while deeper drilling has encountered 7.62 g/t gold and 0.36% copper over 3.4 metres at 1,983 metres depth, approximately 400 metres below any previous intersection | First Quarter Financial and Production Highlights | In the first quarter of 2019, solid operational performance continued at the Company’s mines, which led to payable gold production of 398,217 ounces (including 17,582 ounces of pre-commercial gold production at the Meliadine project), compared to 389,278 ounces in the first quarter of 2018. | The lower level of gold production, in the first quarter of 2019 (when excluding the Meliadine project pre-commercial production ounces), when compared with the prior-year period, was primarily due to expected reduced throughput levels at Meadowbank as the mine transitions to the Amaruq satellite deposit in the second half of 2019. A detailed description of the production of each mine is set out below. | Production costs per ounce in the first quarter of 2019 were $727, compared to $759 in the prior-year period. Total cash costs per ounce in the first quarter of 2019 were $623, compared to $648 in the prior-year period. | 3 | Production costs per ounce and total cash costs per ounce in the first quarter of 2019 were lower, when compared to the prior-year period, primarily due to lower costs at several mines and the weakening of local currencies against the U.S. dollar, partially offset by lower gold production. The lower total cash costs per ounce in the first quarter of 2019, when compared to the prior-year period,', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:13.525812+00:00', '2026-06-17T12:00:13.525812+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-19-001828', '6-K', '2019-04-01', '2019-04-26', 2019, NULL, 'quarter', 'Consolidated', 'gold', 2017.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746919001828/a2237516zex-99_1.htm', 'Production (10% of total weighting): | • | 2018 production of 1,626,669 ounces of gold exceeded the original production guidance of 1,530,000 million | ounces of gold | • | The gold production target (and actual amount of gold produced) was less than the gold amount produced in 2017 | primarily because it was expected that ore from the Meadowbank mine pits would be depleted during the year and therefore guidance was decreased accordingly; ore from the satellite Amaruq deposit is | expected to feed the Meadowbank mill beginning in 2019 | • | Seventh year in a row of gold production outperformance relative to guidance | • | Beyond 2018, because of the strong progress made during 2018 at the Nunavut projects (Meliadine and Amaruq), the Company | increased production guidance for 2019 to 1,750,000 ounces of gold', 'production-v2', 0.8, '2026-06-17T12:00:13.677577+00:00', '2026-06-17T12:00:13.677577+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-19-041990', '6-K', '2019-07-26', '2019-07-24', 2019, NULL, 'quarter', 'Consolidated', 'gold', 2019.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465919041990/a19-13303_1ex99d1.htm', 'The decrease in cash provided by operating activities, before changes in non-cash components of working capital, in the first six months of 2019 compared to the prior year period was mainly due to lower gold sales volumes (which does not include pre-commercial production ounces at Meliadine and Amaruq), lower by-product revenue and slightly lower realized gold prices, partially offset by lower costs. Lower gold sales were largely as a result of the expected lower gold production as described above. | “The second quarter of 2019 was another period of strong operating performance with production and costs tracking well with guidance. One of the key highlights in the quarter was the declaration of commercial production at our Meliadine mine in Nunavut”, said Sean Boyd, Agnico Eagle’s Chief Executive Officer. “With Meliadine ramping up to full production over the balance of the year and Amaruq on schedule to achieve commercial production in the third quarter of 2019, the Company is well positioned for a strong second half from both a financial and operational perspective”, added Mr. Boyd. | Second quarter of 2019 highlights include: | · | Solid operating results — | Payable gold production | 2 | in the second quarter of 2019 was 412,315 ounces (including pre-commercial production ounces of 29,699 ounces | 2 | Payable production of a mineral means the quantity of a mineral produced during a period contained in products that have been or will be sold by the Company whether such products are shipped during the period or held as inventory at the end of the period. | 2 | at Meliadine and 2,147 ounces at Amaruq) at production costs per ounce of $735, total cash costs per ounce | 3', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:13.370252+00:00', '2026-06-17T12:00:13.370252+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-19-041990', '6-K', '2019-07-26', '2019-07-24', 2019, NULL, 'quarter', 'Minesite costs per tonne', 'gold', 2019.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465919041990/a19-13303_1ex99d1.htm', '395 | Production costs per tonne in the second quarter of 2019 decreased when compared to the prior-year period due to the timing of unsold concentrate inventory, partially offset by lower throughput. Production costs per ounce in the second quarter of 2019 decreased when compared to the prior-year period due to the reason described above, partially offset by lower gold production. | Minesite costs per tonne | 5 | in the second quarter of 2019 increased when compared to the prior-year period due to lower throughput. Total cash costs per ounce in the second quarter of 2019 increased when compared to the prior-year period due to lower gold production and lower by-product revenue. | Gold production in the second quarter of 2019 decreased when compared to the prior-year period primarily due to lower tonnage as a result of a nine-day mill maintenance shutdown in May 2019. | 5 | Minesite costs per tonne is a non-GAAP measure. For a reconciliation of this measure to production costs as reported in the financial statements, see “Reconciliation of Non-GAAP Financial Performance Measures” below. See also “Note Regarding Certain Measures of Performance” below. | 10 | LaRonde Mine — Operating Statistics | Six Months Ended | Six Months Ended | June 30, 2019', 'production-v2', 0.8, '2026-06-17T12:00:13.370252+00:00', '2026-06-17T12:00:13.370252+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-19-056418', '6-K', '2019-10-25', '2019-10-24', 2019, NULL, 'quarter', 'Consolidated', 'gold', 2019.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465919056418/a19-20589_3ex99d1.htm', 'The increase in net income and in cash provided by operating activities in the first nine months of 2019 compared to the prior year period was mainly due to higher realized gold prices, partially offset by slightly lower gold sales volume (excluding pre-commercial production ounces at Meliadine and Amaruq) and the contribution of production costs from Meliadine. Lower gold sales were largely due to decreased production as a result of mill maintenance shutdowns at LaRonde and Kittila in the second quarter of 2019 and expected lower throughput levels at Meadowbank as described above. | “With record performance at several of our operations and the ongoing ramp up of our two new mines in Nunavut, we achieved record quarterly gold production in the third quarter of 2019. As expected, this strong result, combined with the completion of the extensive construction spending program in Nunavut, resulted in the generation of substantial free cash flow in the quarter,” said Sean Boyd, Agnico Eagle’s Chief Executive Officer. “With the expectation of growing production and strong free cash flow generation, we are in a good position to continue to invest in our project pipeline, improve our financial flexibility and grow our dividend. We are pleased to announce a 40 percent increase in our quarterly dividend,” added Mr. Boyd. | Third quarter of 2019 highlights include: | • | Record quarterly gold production — | Payable gold production | 2 | in the third quarter of 2019 was 476,937 ounces (including pre-commercial production ounces of 33,134 ounces at Amaruq) at production costs per ounce of $713, total cash costs per ounce | 3 | of $653 and all-in sustaining costs per ounce | 4 | of $903. Production costs, total cash | 2', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:13.207750+00:00', '2026-06-17T12:00:13.207750+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-19-056418', '6-K', '2019-10-25', '2019-10-24', 2019, NULL, 'quarter', 'Goldex — Record Quarterly Since Re-start of Operations in', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465919056418/a19-20589_3ex99d1.htm', 'Hole MEX19-148, which intersected 2.4 g/t gold over 19.8 metres at 1,924 metres depth, is the deepest drill intersection to date of the East Gouldie Zone. The thickest intercept so far is seen in the lower central part of the East Gouldie Zone in hole MEX19-151, which intersected 4.9 g/t gold over 56.0 metres at 1,523 metres depth | . | The recent drill results are expected to have a positive impact on the total mineral reserves and mineral resources at the Canadian Malartic property at year-end. Studies are underway to evaluate potential mining scenarios for the various zones located under and east of the current open-pit operations. | In March 2019, the Partnership acquired a 100% interest in the Rand Malartic property, which extends 1.7 kilometres immediately eastward from the Odyssey project and provides an additional 262 hectares of prospective ground with the same favourable geological setting as the Odyssey zone. | The host porphyry intrusion seen at depth at Odyssey is exposed at surface on the Rand Malartic property, providing both shallow and deeper drill targets. The Partnership has a $1.9 million (100% basis) exploration budget at Rand Malartic in 2019, with 14,800 metres of drilling already completed at the end of August 2019. | Goldex — Record Quarterly Gold Production Since Re-start of Operations in 2013 | The 100% owned Goldex mine in northwestern Quebec began production from the M and E zones in September 2013. Commercial production from the Deep 1 Zone commenced on July 1, 2017. | Goldex Mine — Operating Statistics | Three Months Ended | Three Months Ended | September 30, 2019 | September 30, 2018 | Tonnes of ore milled (thousands of tonnes)', 'production-v2', 0.8, '2026-06-17T12:00:13.207750+00:00', '2026-06-17T12:00:13.207750+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-20-022277', '6-K', '2020-02-18', '2019-12-31', 2019, 'FY', 'quarter', 'Drilling at Santa Gertrudis extends high-grade mineral resources', 'gold', 2018.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465920022277/a20-8158_1ex99d1.htm', '· | Drilling at Santa Gertrudis extends high-grade mineral resources | — The Amelia deposit continues to grow with an updated inferred mineral resource of 70,000 ounces of gold (1.6 million tonnes grading 1.38 g/t gold) at open pit depth, as well as an initial underground inferred mineral resource of 451,000 ounces of gold (3.1 million tonnes grading 4.58 g/t gold) in higher-grade sulphide material | Fourth Quarter and Full Year 2019 Financial and Production Highlights | In the fourth quarter of 2019, strong operational performance continued at the Company’s mines, which led to record quarterly payable gold production of 494,678 ounces, which includes the pre-commercial production from the Barnat deposit at Canadian Malartic. Excluding the pre-commercial production ounces at Barnat, payable gold production was 491,541 ounces, compared to 410,712 ounces in the fourth quarter of 2018. | For the full year 2019, payable gold production was a record 1,782,147 ounces, which includes the pre-commercial production ounces at the Meliadine mine, the Amaruq satellite deposit and the Barnat deposit. Excluding the pre-commercial production ounces, payable gold production was 1,696,443 ounces, compared to 1,626,669 ounces in 2018. | The higher level of gold production in the fourth quarter of 2019 and the full year 2019, when compared with the prior-year periods, was primarily due to the start of production at the Meliadine mine in 2019. A detailed description of the production at each mine is set out below. | Production costs per ounce in the fourth quarter of 2019 were $763, compared to $693 in the prior-year period. Total cash costs per ounce in the fourth quarter of 2019 were $745, compared to $608 in the prior-year period. | 4 | Production costs per ounce for the full year 2019 were $735, compared to $713 in the prior-year period. Total cash costs per ounce for the full year 2019 were $673, compared to $637 in the prior-year period. | Production costs per ounce and total cas', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:13.099923+00:00', '2026-06-17T12:00:13.099923+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-20-002746', '6-K', '2020-04-30', '2020-03-31', 2020, 'Q1', 'quarter', 'Consolidated', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746920002746/a2241472zex-99_1.htm', 'Non-GAAP Financial Performance Measures | in this MD&A. | In | the first quarter of 2020, the operating margin (revenues from mining operations less production costs) of $315.8 million increased compared to $255.3 million in the first quarter of | 2019 primarily due to a 26.2% increase in revenues from mining operations as a result of a 21.2% higher average realized price in gold and a 4.3% increase in the sales volume of gold ounces between | periods which excludes 2,974 pre-commercial gold ounces from the Barnat deposit at the Canadian Malartic mine. Gold production increased to 411,366 ounces in the first quarter of 2020 | compared with 398,217 ounces in the first quarter of 2019 primarily due to increased gold production from the Meliadine mine. Partially offsetting the overall increase in gold production was a | decrease in gold production from the LaRonde mine as a result of the delay in accessing higher grade ore from the West mine as additional ground support was being completed, and a nine-day shutdown of | the Company''s Quebec operations, as mandated by the Quebec Government, and significantly reduced mining activities in Nunavut related to COVID-19 precautionary measures. Cash provided by operating | activities amounted to $163.4 million in the first quarter of 2020 compared with $148.7 million in the first quarter of 2019. Total weighted average cash costs per ounce of gold produced | amounted to $836 on a by-product basis and $889 on a co-product basis in the first quarter of 2020 compared with $623 on a by-product basis and $704 on a co-product basis in the first quarter of 2019. | For a reconciliation of total cash costs per ounce of gold produced on both a by-product basis (deducting by-product metal revenues from production costs) and co-product basis (without | 5', 'production-v2', 0.8, '2026-06-17T12:00:12.811551+00:00', '2026-06-17T12:00:12.811551+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-20-055900', '6-K', '2020-05-04', '2020-04-30', 2020, NULL, 'quarter', 'Consolidated', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465920055900/a20-15881_5ex99d1.htm', '558 | $ | 558 | Production costs per tonne in the first quarter of 2020 were essentially the same when compared to the prior-year period. Production costs per ounce in the first quarter of 2020 increased when compared to the prior-year period primarily due to the timing of unsold inventory and slightly lower gold production. | Minesite costs per tonne in the first quarter of 2020 were the same when compared to the prior-year period. Total cash costs per ounce in the first quarter of 2020 were the same when compared to the prior-year period. | Gold production in the first quarter of 2020 decreased slightly when compared to the prior-year period primarily due to the temporary suspension of operations ordered by the Government of Quebec on March 23, 2020, which was partially offset by the increased production resulting from the utilization of the Rail-Veyor system. The utilization of the Rail-Veyor continues to improve with a new quarterly performance record for hauled tonnage of approximately 7,144 tpd (based on 82 days of operation in the first quarter of 2020). | A new underground Rail-Veyor maintenance facility is expected to be completed in the second quarter of 2020. This new facility is expected to have a positive impact on future Rail-Veyor productivity. | Mining operations at Goldex progressively restarted on April 15, 2020 after the Government of Quebec permitted mining activities to resume. Milling activities resumed in late April 2020. | Mining in the South Zone continued in the first quarter of 2020. Stopes mined to date continue to show better grades than anticipated and have confirmed dilution and recovery assumptions. The South Zone consists of quartz veins that have higher grades than those in the primary mineralized zones at Goldex. In the first quarter of 2020, mining rates at the | 20 | South Zone were better than expected, averaging approximately 497 tpd over the 82 days of operation. Mining rates at the South Zone are expected to ramp up to 750 tp', 'production-v2', 0.8, '2026-06-17T12:00:12.743278+00:00', '2026-06-17T12:00:12.743278+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-20-055900', '6-K', '2020-05-04', '2020-04-30', 2020, NULL, 'quarter', 'Meadowbank Complex', 'gold', 2019.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465920055900/a20-15881_5ex99d1.htm', '4 | · | Meadowbank Complex | — During this period of reduced activities, the focus was on reducing the equipment maintenance backlog, development of the eastern portion of the Whale Tail pit and mining at approximately 50% capacity (approximately 50,000 tpd) to build stockpiles as milling activities were suspended in March 2020. It is anticipated that the processing facility will restart in early to mid-June | First Quarter Financial and Production Highlights | In the first quarter of 2020, quarterly payable gold production was 411,366 ounces, which includes the pre-commercial gold production from the Barnat deposit at Canadian Malartic, compared to 398,217 ounces in the first quarter of 2019. | The higher level of gold production in the first quarter of 2020, when compared with the prior-year period, was primarily due to increased production at the Meliadine mine, which achieved commercial production in May 2019. A detailed description of the production at each mine is set out below. | Production costs per ounce in the first quarter of 2020 were $872, compared to $727 in the prior-year period. Total cash costs per ounce in the first quarter of 2020 were $836, compared to $623 in the prior-year period. | Production costs per ounce and total cash costs per ounce in the first quarter of 2020 increased when compared to the prior-year period primarily due to higher costs at the Meadowbank Complex and Meliadine mine which were still ramping up operations during the quarter, partially offset by higher gold production. | AISC in the first quarter of 2020 was $1,099 per ounce, compared to $836 in the prior-year period. AISC in the first quarter of 2020 increased when compared to the prior-year periods primarily due to higher total cash costs per ounce and higher sustaining capital costs, partially offset by higher gold production. A detailed description of the cost performance of each mine is set out below. | Production and costs in the first quarter of 2020 were negatively', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:12.743278+00:00', '2026-06-17T12:00:12.743278+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-20-004310', '6-K', '2020-07-29', '2020-06-30', 2020, 'Q2', 'quarter', 'Consolidated', 'gold', 2019.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746920004310/a2242129zex-99_1.htm', 'in this MD&A. | Gold | production decreased to 331,064 ounces in the second quarter of 2020 compared with 412,315 ounces in the second quarter of 2019, primarily due to decreased gold production from all | of the Company''s mines (other than at the Kittila mine) as operations were reduced to minimum levels which were the result of | measures taken by the Quebec and Mexican governments and the Company related to the COVID-19 pandemic. Partially offsetting the overall decrease in gold production compared to the prior period was an | increase in gold production from the Kittila mine where autoclave relining required the mill to be shutdown for 58 days during the second quarter of 2019. | Cash | provided by operating activities amounted to $162.6 million in the second quarter of 2020 compared with $126.3 million in the second quarter of 2019. | Agnico | Eagle reported net income of $83.7 million or $0.35 per share, in the six months ended June 30, 2020, compared with net income of $64.8 million, or $0.28 per share, in the | six months ended June 30, 2019. Agnico Eagle reported adjusted net income of $100.3 million, or $0.42 per share, in the first six months of 2020 compared with adjusted net income of | $54.6 million, or $0.23 per share, in the first six months of 2019. Adjusted net income is a non-GAAP measure; for a reconciliation of adjusted net income to net income as presented in the | condensed interim consolidated statements of income in accordance with IFRS, see', 'production-v2', 0.8, '2026-06-17T12:00:12.666616+00:00', '2026-06-17T12:00:12.666616+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-20-088760', '6-K', '2020-07-31', '2020-07-29', 2020, NULL, 'quarter', 'Consolidated', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465920088760/tm2025179d3_ex99-1.htm', '2 | Second quarter of 2020 highlights include: | • | Solid operational performance in the second quarter of | 2020 despite COVID-19 interruptions – | Payable gold production | 2 | in the | second quarter of 2020 was 331,064 ounces (including 2,651 ounces of pre-commercial gold | production from the Barnat deposit at Canadian Malartic) at production costs per ounce of | $854, total cash costs per ounce | 3 | of $825 and all-in sustaining costs per ounce', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:12.578185+00:00', '2026-06-17T12:00:12.578185+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-20-005321', '6-K', '2020-10-28', '2020-09-30', 2020, 'Q3', 'quarter', 'Consolidated', 'gold', 13305.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746920005321/a2242563zex-99_1.htm', 'The | Meliadine mine''s cost calculations per tonne for the three and nine months ended September 30, 2020 exclude 13,374 tonnes of ore from | the Tiriganiaq open pit deposit, which were processed during these periods as commercial production at the Tiriganiaq open pit deposit has not yet been achieved. | (viii) | The | Canadian Malartic mine''s cost calculations per ounce of gold produced for the three and nine months ended September 30, 2020 exclude 13,305 | and 18,930 ounces of payable gold production, respectively, which were produced during these periods as commercial production at the Barnat deposit has not yet been achieved. | (ix) | The | Canadian Malartic mine''s cost calculations per tonne for the three and nine months ended September 30, 2020 exclude 469,966 and | 731,309 tonnes of ore from the Barnat deposit, respectively, which were processed during these periods as commercial production at the Barnat deposit has not yet been achieved. | 26 | AGNICO EAGLE MINES LIMITED', 'production-v2', 0.8, '2026-06-17T12:00:12.456154+00:00', '2026-07-01T23:01:13.594278+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-20-119804', '6-K', '2020-10-30', '2020-10-28', 2020, NULL, 'quarter', 'Consolidated', 'gold', 47281.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465920119804/tm2032390d3_ex99-1.htm', '822 | $ | 776 | * | In the first nine months of 2020, the | Tiriganiaq open pit had 1,982 ounces of pre-commercial gold production. In the first nine months of 2019, Meliadine had 47,281 | ounces of pre-commercial gold production | . | **Excluding tonnes milled on a pre-commercial | production basis, the mill operated for an equivalent of 139 days in the first nine months of 2019. | Production costs per tonne in the first | nine months of 2020 were C$243. Production costs per ounce in the first nine months of 2020 were $814. Minesite costs per tonne | in the first nine months of 2020 were C$243. Total cash costs per ounce in the first nine months of 2020 were $822. Gold production', 'production-v2', 0.8, '2026-06-17T12:00:12.369309+00:00', '2026-07-01T23:01:13.300794+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-023483', '6-K', '2021-02-16', '2020-12-31', 2020, 'FY', 'quarter', 'Consolidated', 'gold', 10995.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921023483/tm214428d1_ex99-1.htm', 'which achieved their targeted operating rates, partially offset by lower production from the LaRonde Complex due to lower grade | and throughput as a result of adjustments to the mining sequences and lower production from the Kittila mine due to a planned shutdown | at the start of the quarter. | 5 | In the full year 2020, payable gold production | was 1,736,568 ounces (including pre-commercial gold production of 18,930 ounces from the Barnat deposit at Canadian Malartic, 10,995 | ounces from the IVR pit at the Meadowbank Complex and 6,491 ounces from the Tiriganiaq open pit at Meliadine), compared to 1,782,147 | ounces in the prior-year period (which included an aggregate of 85,699 ounces of pre-commercial gold production at the Meliadine | mine, the Amaruq satellite deposit and the Barnat deposit). | The lower gold production in the full year | 2020, when compared to the prior-year period, was primarily due to lower production at four of the Company''s eight mines as a result | of temporary shutdowns or reduction in activities in the second quarter of 2020 related to government mandated COVID-19 restrictions, | partially offset by the contribution of a full year of production from the Meliadine mine which achieved commercial production', 'production-v2', 0.8, '2026-06-17T12:00:12.260397+00:00', '2026-07-01T23:01:12.580040+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-023483', '6-K', '2021-02-16', '2020-12-31', 2020, 'FY', 'quarter', 'Minesite costs per tonne in the full year', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921023483/tm214428d1_ex99-1.htm', '7 | Minesite costs per tonne is a non-GAAP measure. For a reconciliation of this measure to production costs as reported in the financial | statements, see "Reconciliation of Non-GAAP Financial Performance Measures" below. See also "Note Regarding Certain | Measures of Performance" below. | 57 | Gold production in the full year 2020 | decreased when compared to the prior-year primarily due to the government mandated suspension of operations (LaRonde mill circuit | from March 23, 2020 to April 29, 2020 and the LZ5 mill circuit from March 23, 2020 to May 2, 2020), to the | delay in accessing higher grade ore from the West mine area as additional ground support work was being completed in the first | quarter of 2020 and as a higher proportion of ore milled was sourced from the lower grade LZ5 mine in the second half of 2020. | LaRonde Mine | Mining activities in the West mine area | progressed ahead of schedule in the fourth quarter of 2020. The West mine area contributed approximately 19% of the tonnage mined', 'production-v2', 0.8, '2026-06-17T12:00:12.260397+00:00', '2026-06-17T12:00:12.260397+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-023483', '6-K', '2021-02-16', '2020-12-31', 2020, 'FY', 'quarter', 'Mining activities in the West mine area', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921023483/tm214428d1_ex99-1.htm', 'quarter of 2020 and as a higher proportion of ore milled was sourced from the lower grade LZ5 mine in the second half of 2020. | LaRonde Mine | Mining activities in the West mine area | progressed ahead of schedule in the fourth quarter of 2020. The West mine area contributed approximately 19% of the tonnage mined | at the LaRonde Complex, operating at an average rate of 1,421 tpd, exceeding the forecast of 1,150 tpd. The ore extracted from | this area returned higher grade than anticipated, leading the strong gold production performance from the Complex. In 2021, the | West mine area is expected to contribute approximately 15% of the ore mined and 21% of the gold ounces produced at the LaRonde | Complex. | The good performance at the LaRonde mine', 'production-v2', 0.65, '2026-06-17T12:00:12.260397+00:00', '2026-06-17T12:00:12.260397+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-21-001062', '6-K', '2021-04-29', '2021-03-31', 2021, 'Q1', 'quarter', 'Canadian Malartic mine', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746921001062/a2243227zex-99_1.htm', 'periods, partially offset by lower underground development costs. | Hope Bay mine | The Company completed the acquisition of TMAC on February 2, 2021. For the period from February 2, 2021 to March 31, 2021, gold | production at the Hope Bay mine was 12,259 ounces and production costs at the Hope Bay mine were $24.1 million. | Canadian Malartic mine | At the 50% owned Canadian Malartic mine, attributable gold production increased by 38.3% to 89,550 ounces in the first quarter of 2021, | compared with 64,763 ounces in the first quarter of 2020 (which includes 2,974 ounces produced prior to the achievement of commercial production at | the Barnat deposit), primarily due to the impact of the Quebec Order in the prior period. Attributable production costs at the Canadian Malartic mine were $55.5 million in the first quarter of | 2021, an increase of 14.0% compared with production costs of $48.7 million in the first quarter of 2020 primarily due to the suspension of operations required by the Quebec Order in the first | quarter of 2020. | Kittila mine | At the Kittila mine, gold production increased by 23.2% to 60,716 ounces in the first quarter of 2021 compared with 49,297 ounces in | the first quarter of 2020, primarily due to increased mill throughput and higher gold grades. Production costs at the Kittila mine were $48.7 million in the first quarter of 2021, an increase', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:11.931800+00:00', '2026-06-17T12:00:11.931800+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001047469-21-001062', '6-K', '2021-04-29', '2021-03-31', 2021, 'Q1', 'quarter', 'Consolidated', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000104746921001062/a2243227zex-99_1.htm', 'ore from the West mine area, and the strengthening of the Canadian dollar and Euro relative to the US dollar between periods. Partially offsetting the total increase in production costs was a decrease | in production costs at the Creston Mascota mine due to ceasing of mining operations at the open pit in the third quarter of 2020. | Weighted | average total cash costs per ounce of gold produced decreased to $734 on a by-product basis and $797 on a co-product basis in the first quarter of 2021, compared with $836 on a by-product | basis and $889 on a co-product basis in the first quarter of 2020, primarily due to increased gold production at the Quebec and Nunavut mines, partially offset by the strengthening of the Canadian and | Euro relative to the US dollar and the decrease in gold production at the Creston Mascota mine due to ceasing of mining operations at the open pit in the third quarter of 2020. | Exploration | and corporate development expenses decreased to $28.7 million in the first quarter of 2021, compared with $29.6 million in the first quarter of 2020, primarily due to lower | corporate development expenses, partially offset by increased exploration activities at the Upper Beaver project. | Amortization | of property, plant and mine development increased by $27.6 million to $181.1 million between the first quarter of 2020 and the first quarter of 2021, primarily due to an | increase in the tonnage of ore processed at the Company''s mines between periods and the contribution of amortization from the Hope Bay mine which was acquired during the first quarter of 2021. | General', 'production-v2', 0.8, '2026-06-17T12:00:11.931800+00:00', '2026-06-17T12:00:11.931800+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-059801', '6-K', '2021-05-03', '2021-05-03', 2021, NULL, 'quarter', 'Consolidated', 'gold', 516804.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921059801/tm2112392d3_ex99-1.htm', 'First Quarter 2021 Financial and Production Highlights | In the first quarter of 2021, the Company set | a second consecutive record in quarterly payable gold production of 504,545 ounces (excluding 12,259 ounces of payable gold production | at Hope Bay, and including 8,123 ounces of pre-commercial production of gold at the Tiriganiaq open pit at Meliadine). This compares to | quarterly payable gold production of 411,366 ounces in the prior-year period (which included 2,974 ounces of pre-commercial production | of gold at the Barnat deposit at Canadian Malartic). Including the Hope Bay mine, the Company''s quarterly gold production was 516,804 | ounces in the first quarter of 2021. | The higher gold production in the first quarter | of 2021, when compared to the prior-year period, was primarily due to strong performance at the LaRonde and Meadowbank complexes and at | the Canadian Malartic, Meliadine and Kittila mines, especially in the month of March 2021, partially offset by lower production at | Pinos Altos resulting from lower gold grades encountered under the mining sequence, at La India related to water conservation efforts | and at Creston Mascota where only residual leaching remains. In the first quarter of 2020, gold production was negatively affected by | COVID-19 related reductions in mining activities. A detailed description of the production at each mine is set out below.', 'production-v2', 0.8, '2026-06-17T12:00:11.864844+00:00', '2026-07-01T23:01:10.515594+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-098028', '6-K', '2021-07-30', '2021-07-30', 2021, NULL, 'quarter', 'Consolidated', 'gold', 500698.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921098028/tm2121456d3_ex99-1.htm', '2 | Second quarter of 2021 highlights include: | • | Strong operating results and record safety performance in the second quarter of 2021 – | Payable | gold production | 3 | was 500,698 ounces (excluding 25,308 ounces of payable gold production at Hope Bay, and including | 9,053 ounces and 348 ounces of pre-commercial production of gold at the Tiriganiaq open pit at Meliadine and Amaruq underground project, | respectively) at production costs per ounce of $834, total cash costs per ounce | 4 | of $739 and all-in sustaining costs | ("AISC") per ounce', 'production-v2', 0.8, '2026-06-17T12:00:11.568188+00:00', '2026-07-01T23:01:08.956158+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-130548', '6-K', '2021-10-28', '2021-10-28', 2021, NULL, 'quarter', 'Consolidated', 'gold', 2020.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921130548/tm2129214d1_ex99-1.htm', 'in this MD&A. | Gold production increased to 541,663 ounces in the third quarter of 2021 compared with 492,693 ounces in the third quarter of 2020, primarily due to the contribution of gold production from the Hope Bay mine and increased gold production at the Meadowbank and LaRonde Complexes and the Canadian Malartic and Kittila mines. Partially offsetting the overall increase in gold production between the third quarter of 2021 and the third quarter of 2020 was the ceasing of mining operations in the open pit at the Creston Mascota mine in the third quarter of 2020 and the lower tonnes of ore processed at the La India mine. | Cash provided by operating activities decreased to $291.0 million in the third quarter of 2021 compared with $462.5 million in the third quarter of 2020. | Agnico Eagle reported net income of $440.2 million or $1.81 per share, in the nine months ended September 30, 2021, compared with net income of $306.4 million, or $1.27 per share, in the nine months ended September 30, 2020. Agnico Eagle reported adjusted net income of $476.0 million, or $1.96 per share, in the first nine months of 2021 compared with adjusted net income of $289.5 million, or $1.20 per share, in the first nine months of 2020. | In the first nine months of 2021, the operating margin increased to $1,583.1 million, compared with $1,160.4 million in the first nine months of 2020, primarily due to a 24.9% increase in the sales volume of commercial gold ounces (which excludes 23,595 and 348 ounces of pre-commercial gold production from the Tiriganiaq open pit deposit at the Meliadine mine and the Amaruq underground project, respectively) and a 2.3% higher average realized price of gold between periods. | Gold production increased to 1,584,473 ounces in the first nine months of 2021, compared with 1,235,123 ounces in the first nine months of 2020, primarily due to the impact of COVID-19 precautionary measures in the prior period and the contribution of gold production from the Hop', 'production-v2', 0.8, '2026-06-17T12:00:11.341574+00:00', '2026-06-17T12:00:11.341574+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-21-130821', '6-K', '2021-10-28', '2021-10-28', 2021, NULL, 'quarter', 'Consolidated', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465921130821/tm2129214d2_ex99-1.htm', 'In the third quarter of 2021, the Company''s payable | gold production was 523,706 ounces (excluding 17,957 ounces of payable gold production at Hope Bay, and including 6,881 ounces of pre-commercial | production of gold at the Tiriganiaq open pit at Meliadine). This compares to quarterly payable gold production of 492,693 ounces in the | prior-year period (which included 13,305 ounces of pre-commercial production of gold at the Barnat deposit at Canadian Malartic and 1,982 | ounces of pre-commercial gold production at the Tiriganiaq open pit at Meliadine). Including the Hope Bay mine, the Company''s quarterly | gold production was a record of 541,663 ounces in the third quarter of 2021. | In the first nine months of 2021, the Company''s | payable gold production was 1,528,949 ounces (excluding 55,524 ounces of payable gold production at Hope Bay, and including 24,057 ounces | and 348 ounces of pre-commercial production of gold at the Tiriganiaq open pit at Meliadine and Amaruq underground project, respectively). | This compares to payable gold production of 1,235,123 ounces in the prior-year period (which included 18,930 ounces of pre-commercial | production of gold at the Barnat deposit at Canadian Malartic and 1,982 ounces of pre-commercial gold production at the Tiriganiaq open | pit at Meliadine). Including the Hope Bay mine, the Company''s payable gold production was also a record of 1,584,473 ounces for the first | nine months of 2021.', 'production-v2', 0.8, '2026-06-17T12:00:11.432285+00:00', '2026-06-17T12:00:11.432285+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-027214', '6-K', '2022-02-25', '2022-02-23', 2022, NULL, 'quarter', 'Consolidated', 'gold', 2086405.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922027214/tm222650d1_ex99-1.htm', 'For the full year 2021, the Company''s payable | gold production was a record 2,030,176 ounces (excluding 56,229 ounces of payable gold production at Hope Bay, and including 24,057 ounces | and 1,956 ounces of pre-commercial gold production at the Tiriganiaq open pit at Meliadine and Amaruq underground project, respectively). | This compares to payable gold production of 1,736,568 ounces in the prior-year period (which included pre-commercial gold production of | 18,930 ounces from the Barnat deposit at Canadian Malartic, 10,995 ounces from the IVR pit at the Meadowbank Complex and 6,491 ounces | from the Tiriganiaq open pit at Meliadine). Including the Hope Bay mine, the Company''s payable gold production was a record 2,086,405 | ounces for the full year 2021. | The higher gold production for the full year 2021, | when compared to the prior-year period, was primarily due to strong performance at the Company''s mines, including higher gold grades and | tonnage at the Canadian Malartic, Meliadine and Pinos Altos mines and the Meadowbank Complex, and higher tonnage at the LaRonde Complex | and the Goldex and Kittila mines. This was partially offset by lower production at the La India mine related mostly to water conservation | efforts and at Creston Mascota, where only residual leaching occurred. Gold production for the full year 2020 was negatively affected | by COVID-19 related reductions in mining activities which affected seven of the Company''s then eight operations. A detailed description', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:10.587691+00:00', '2026-07-01T23:00:42.798800+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-027214', '6-K', '2022-02-25', '2022-02-23', 2022, NULL, 'quarter', 'The Fosterville mine is located approximately', 'gold', 150000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922027214/tm222650d1_ex99-1.htm', 'Reviewing the development program and the mining sequence in several areas of the underground mine | Fosterville Mine – Exploration Drilling | Continues to Target Mineral Reserve Replacement and Growth as well as the Potential Discovery of New High-Grade Zones | The Fosterville mine is located approximately | 20 kilometres northeast of Bendigo in Victoria, Australia. Kirkland Lake Gold acquired Fosterville as part of a business combination with | Newmarket Gold Inc. in November 2016. At the time of the transaction, Fosterville had annual gold production of approximately 150,000 | ounces with mineral reserves of 388,000 ounces of gold (1.7 million tonnes at 7.3 g/t gold). | A key consideration in the decision to acquire | Fosterville was strong exploration potential. Exploration had demonstrated a trend towards improving grades within the host sulphide mineralization | as it progressed down-plunge, and it identified a new form of mineralization; high-grade quartz veins containing significant amounts of | visible gold starting at a depth of approximately 800 metres from surface. | In 2017 to 2018, considerable exploration | success was achieved, both growing mineral reserves and increasing average grades, ultimately leading to the establishment of the', 'production-v2', 0.8, '2026-06-17T12:00:10.587691+00:00', '2026-07-01T23:00:42.798800+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-027214', '6-K', '2022-02-25', '2022-02-23', 2022, NULL, 'quarter', 'mine', 'gold', 3210000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922027214/tm222650d1_ex99-1.htm', '65,000 | 75,000 | 20,000 | 25,000 | Total | Gold Production | 3,210,000 | 3,390,000 | 3,235,000 | 3,425,000 | 3,250,000 | 3,450,000 | *', 'production-v2', 0.8, '2026-06-17T12:00:10.587691+00:00', '2026-07-01T23:00:42.798800+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-027214', '6-K', '2022-02-25', '2022-02-23', 2022, NULL, 'quarter', 'of pre-commercial at the Amaruq underground project). This compares to quarterly  of', 'gold', 501445.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922027214/tm222650d1_ex99-1.htm', 'in the full year 2021, compared to the prior-year period, is primarily due to an increase in operating margins that resulted from higher | sales volumes and higher average realized metals prices, partially offset by higher cash taxes related to the higher mine operating margins | and payments for taxes related to the 2020 tax year in the first quarter of 2021. | In the fourth quarter of 2021, the Company''s | payable gold production was 501,227 ounces (excluding 705 ounces of payable gold production at Hope Bay, and including 1,608 ounces | of pre-commercial gold production at the Amaruq underground project). This compares to quarterly payable gold production of 501,445 | ounces in the prior-year period (which included pre-commercial gold production of 10,995 ounces from the IVR pit at the Meadowbank | Complex and 4,509 ounces from the Tiriganiaq open pit at Meliadine). Including the Hope Bay mine, the Company''s quarterly gold | production was 501,932 ounces in the fourth quarter of 2021. | 9 | Gold production in the fourth quarter of 2021, | when compared to the prior-year period, was essentially the same. However, production in the fourth quarter of 2021 was negatively affected | by a reduction in operating activities in Nunavut largely due to a COVID-19 outbreak in mid-December 2021.', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:10.587691+00:00', '2026-07-01T23:00:42.798800+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-027214', '6-K', '2022-02-25', '2022-02-23', 2022, NULL, 'quarter', 'pipeline projects (the Odyssey and Hope Bay projects)', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922027214/tm222650d1_ex99-1.htm', '10 years | – In 2022, the Company expects to realize Merger-related corporate and operational synergies of approximately $40 million | to $60 million, of which $12 million have already been realized at the time of this news release. In subsequent years, the Company expects | to ramp up these synergies to approximately $165 million per year. A further $590 million over 10 years are expected to be realized through | strategic optimizations which include the development of the Amalgamated Kirkland ("AK") deposit at the Kirkland Lake camp with | initial gold production potentially as early as 2024 | • | Detour Lake mine | – Successful exploration programs in 2020 and 2021 led to | a significant increase in open-pit mineral resources in 2021. These new mineral resources and ongoing business improvement | initiatives will be incorporated into a new technical report expected to be filed in the second quarter of 2022. This report is | expected to show growth in mineral reserves and provide additional opportunities to | enhance the future production profile of the mine', 'production-v2', 0.8, '2026-06-17T12:00:10.587691+00:00', '2026-06-17T12:00:10.587691+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-054202', '6-K', '2022-05-02', '2022-04-28', 2022, NULL, 'quarter', 'Consolidated', 'gold', 1320.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922054202/tm2211395d2_ex99-1.htm', '$ | 787 | *In the first quarter of 2022, the operating | statistics are reported for the period from February 8, 2022 to March 31, 2022. | For the period from February 8, 2022 to March 31, | 2022, gold production at Macassa mine was 24,488 ounces, with production costs per tonne of C$871, production costs per ounce of $1,320, | minesite costs per tonne of C$523 and total cash costs per ounce of $787. | The difference | between production costs per tonne and minesite costs per tonne and the difference between production costs per ounce and total cash costs | per ounce are primarily due to the inventory re-valuation | at the forecasted gold price in the period the inventory was expected | to be sold | done as part of the Purchase Price Allocation following the completion of the Merger.', 'production-v2', 0.8, '2026-06-17T12:00:09.962777+00:00', '2026-07-01T23:00:40.950843+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-083229', '6-K', '2022-07-27', '2022-06-30', 2022, 'Q2', 'quarter', 'Creston Mascota mine', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922083229/tm2220357d2_ex99-1.htm', 'The Company is evaluating the decisions of the Vaasa Administrative Court to determine the impact they may have on operations at the Kittila mine. In addition, the Company will appeal the decisions of the Vaasa Administrative Court to the Supreme Administrative Court of Finland in early August. The Company intends to continue to operate at current levels while it communicates with relevant regulatory authorities and other stakeholders to determine additional next steps regarding these permits. | Pinos Altos mine | At the Pinos Altos mine, gold production decreased by 29.4% to 23,020 ounces in the second quarter of 2022, compared with 32,614 ounces in the second quarter of 2021, primarily due to fewer tonnes of ore processed, partially offset by higher recoveries. Production costs at the Pinos Altos mine were $39.9 million in the second quarter of 2022, an increase of 1.3% compared with production costs of $39.3 million in the second quarter of 2021, primarily due to higher underground mining costs, partially offset by lower milling costs. | Gold production decreased by 22.0% to 48,190 ounces in the first six months of 2022, compared with 61,789 ounces in the first six months of 2021 at the Pinos Altos mine, primarily due to fewer tonnes of ore processed, partially offset by higher gold grades and recoveries. Production costs at the Pinos Altos mine were $72.4 million in the first six months of 2022, an increase of 1.5% compared with production costs of $71.3 million in the first six months of 2021, primarily due to higher underground mining costs and the timing of inventory sales, partially offset by lower milling costs. | Creston Mascota mine | At the Creston Mascota mine, gold production decreased by 80.3% to 635 ounces in the second quarter of 2022, compared with 3,228 ounces in the second quarter of 2021. The Company ceased mining operations at the open pit in the third quarter of 2020. Gold production in the second quarter of 2022 and 2021 was the result of res', 'production-v2', 0.8, '2026-06-17T12:00:09.864455+00:00', '2026-06-17T12:00:09.864455+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-084113', '6-K', '2022-07-29', '2022-07-27', 2022, NULL, 'quarter', 'Consolidated', 'gold', 105205.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922084113/tm2220357d3_ex99-1.htm', 'In | the second quarter 2022, the Macassa mine had strong results in terms of health and safety, | recording its second best quarterly performance since 2016 | • | For | the complete first six months of 2022, gold production at the Macassa mine was 105,205 | ounces. The higher than forecast mined and milled tonnage was partially offset by lower | mined grades than anticipated | • | The | connection of Shaft #4 to the mine infrastructure resulted in increased ventilation in | the deep mine which contributed to reducing air temperatures and improve working conditions | underground', 'production-v2', 0.8, '2026-06-17T12:00:09.622009+00:00', '2026-07-01T23:00:37.920432+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-084113', '6-K', '2022-07-29', '2022-07-27', 2022, NULL, 'quarter', 'Ore Mined', 'gold', 2022000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922084113/tm2220357d3_ex99-1.htm', 'Ore Mined | Strip Ratio | Mill Throughput | Milled | Grade | Gold Production | (million tonnes) | waste tonnes : Ore tonnes | (million tonnes) | (g/)t | (thousand ounces) | 2022 Q2-Q4* | 31.0', 'production-v2', 0.8, '2026-06-17T12:00:09.622009+00:00', '2026-06-17T12:00:09.622009+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-111609', '6-K', '2022-10-26', '2022-09-30', 2022, 'Q3', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922111609/tm2226859d2_ex99-1.htm', '​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Nine Months Ended September 30, 2022 | Gold production decreased by 79.2% to 2,179 ounces in the first nine months of 2022, compared with 10,468 ounces in the first nine months of 2021 at the Creston Mascota mine. The Company ceased mining operations at the open pit in the third quarter of 2020. Gold production during the first nine months of 2022 and 2021 was the result of residual leaching. Production costs at the Creston Mascota mine were $1.7 million in the first nine months of 2022, a decrease of 71.9% compared with production costs of $6.2 million in the first nine months of 2021. | La India mine | At the La India mine, gold production decreased by 4.9% to 16,285 ounces in the third quarter of 2022, compared with 17,124 ounces in the third quarter of 2021, primarily due to fewer tonnes of ore processed, partially offset by higher gold grades. Production costs at the La India mine were $20.3 million in the third quarter of 2022, an increase of 27.3% compared with production costs of $15.9 million in the third quarter of 2021, driven primarily by the timing of inventory sales and higher heap leach costs and the impact of the reduced irrigation issues in 2021. | Gold production increased by 49.2% to 58,003 ounces in the first nine months of 2022, compared with 38,869 ounces in the first nine months of 2021, primarily due to higher gold grades, partially offset by fewer tonnes of ore processed. Gold production in the comparative period was adversely affected by reduced irrigation of the heap leach pads starting in early 2021 to manage low water levels at the minesite due to low rainfall in the La India region in early 2021. Production costs at the La India mine were $55.5 million in the first nine months of 2022, an increase of 43.9% compared with production costs of $38.6 million in the first nine mo', 'production-v2', 0.8, '2026-06-17T12:00:09.423414+00:00', '2026-06-17T12:00:09.423414+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-111609', '6-K', '2022-10-26', '2022-09-30', 2022, 'Q3', 'quarter', 'Consolidated', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922111609/tm2226859d2_ex99-1.htm', '​ | (viii) | The Meliadine mine’s cost calculations per tonne for the three and nine months ended September 30, 2021 excludes 43,491 and 213,867 tonnes of ore, from the Tiriganiaq open pit deposit, respectively, which were processed prior to the achievement of commercial production at the Tiriganiaq open pit deposit on August 15, 2021. | ​ | (ix) | The Meadowbank complex’s cost calculations per ounce of gold produced for the nine months ended September 30, 2021 exclude 348 ounces of payable gold production which were produced prior to the achievement of commercial production at the Amaruq Underground project on August 1, 2022. | ​ | (x) | The Meadowbank complex’s cost calculations per tonne for the nine months ended September 30, 2021 exclude 1,913 tonnes of ore from the Amaruq Underground project which were processed prior to the achievement of commercial production at the Amaruq Underground project on August 1, 2022. | ​ | (xi) | The Creston Mascota mine’s cost calculations per tonne for the three and nine months ended September 30, 2022 exclude approximately $0.6 and $1.7 million of production costs incurred during these periods following the ceasing of mining activities at the Bravo pit during the third quarter of 2020. The Creston Mascota mine’s cost calculations per tonne for the three and six months ended September 30, 2021 excludes approximately $1.8 million and $6.2 million of production costs incurred during these periods, respectively, following the ceasing of mining activities at the Bravo pit during the third quarter of 2020. | ​', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:09.423414+00:00', '2026-06-17T12:00:09.423414+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-22-111609', '6-K', '2022-10-26', '2022-09-30', 2022, 'Q3', 'quarter', 'Creston Mascota mine', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465922111609/tm2226859d2_ex99-1.htm', 'In August 2022, the Company appealed the decisions of the Vaasa Administrative Court to the Supreme Administrative Court of Finland (“SAC”) and requested that the SAC restore the permits through an interim decision pending the ultimate result of Agnico Finland''s appeal. Applicable Finnish authorities have submitted statements to the SAC that the Company believes to be favorable to the Company. Agnico Finland has also received positive support from local stakeholders. The Company expects a final decision from the SAC in late 2023. The Company intends to continue to operate at current levels until the SAC issues a final decision. | Pinos Altos mine | At the Pinos Altos mine, gold production decreased by 28.9% to 23,041 ounces in the third quarter of 2022, compared with 32,402 ounces in the third quarter of 2021, primarily due to fewer tonnes of ore processed and lower gold grades, partially offset by higher recoveries. Production costs at the Pinos Altos mine were $34.5 million in the third quarter of 2022, a decrease of 7.8% compared with production costs of $37.4 million in the third quarter of 2021, primarily due to the timing of inventory sales, lower open pit mining costs and lower royalty costs, partially offset by higher underground mining costs. | Gold production decreased by 24.4% to 71,231 ounces in the first nine months of 2022, compared with 94,191 ounces in the first nine months of 2021 at the Pinos Altos mine, primarily due to fewer tonnes of ore processed and lower gold grades, partially offset by higher recoveries. Production costs at the Pinos Altos mine were $106.9 million in the first nine months of 2022, a decrease of 1.7% compared with production costs of $108.8 million in the first nine months of 2021, primarily due to lower open pit production, milling and royalty costs and the timing of inventory sales, partially offset by higher underground mining costs. | Creston Mascota mine | At the Creston Mascota mine, gold production decreased by 82.0% t', 'production-v2', 0.8, '2026-06-17T12:00:09.423414+00:00', '2026-06-17T12:00:09.423414+00:00');
