INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-023723', '6-K', '2023-02-21', '2023-02-16', 2023, NULL, 'quarter', 'Consolidated', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923023723/tm234901d1_ex99-1.htm', 'C$ | 50.00 | At Goldex, the production forecast is essentially | in line with Previous Guidance. In 2022, the Company commenced development activities at the Akasaba West project and expects to complete | construction for production in early 2024. Akasaba West is expected to provide additional production flexibility to Goldex and is forecast | to contribute approximately 12,000 ounces of gold per year to Goldex payable production starting in 2024. | 25 | ABITIBI REGION, ONTARIO | Detour Lake Forecast | 2022 | 2023 | 2024 | 2025', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:08.936099+00:00', '2026-06-17T12:00:08.936099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-023723', '6-K', '2023-02-21', '2023-02-16', 2023, NULL, 'quarter', 'Minesite costs per tonne is a non-GAAP', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923023723/tm234901d1_ex99-1.htm', 'Minesite costs per tonne is a non-GAAP | measure that does not have a standardized meaning under the financial reporting framework used to prepare the Company''s financial statements. | For a reconciliation to production costs see "Reconciliation of Non-GAAP Performance Measures" below. See also "Note Regarding Certain | Measures of Performance". | 66 | Gold production in the fourth quarter of 2022 | decreased when compared to the prior-year period primarily due to lower processing volumes related to changes in the mining sequence | at the LaRonde mine as explained above (see above under the heading "New Mining Plan Adopted at the LaRonde Complex to Maintain | Operational Flexibility and Ensure Longer-Term Production of 300,000 to 325,000 Ounces of Gold per Year" for a discussion of the | new mining plan at the LaRonde Complex), partially offset by higher grades at the LZ5 mine. | Production costs per tonne in the fourth quarter | of 2022 increased when compared to the prior-year period primarily as a result of higher unit costs for fuel, materials and reagents | combined with lower mill throughput levels, partially offset by the timing of unsold concentrate inventory. Production costs per ounce', 'production-v2', 0.8, '2026-06-17T12:00:08.936099+00:00', '2026-06-17T12:00:08.936099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-023723', '6-K', '2023-02-21', '2023-02-16', 2023, NULL, 'quarter', 'Operations delivered in the fourth quarter despite challenging cost environment', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923023723/tm234901d1_ex99-1.htm', 'of Yamana Gold’s Canadian assets (including the other half of the world-class Canadian Malartic mine). | 1 | • | Operations delivered in the fourth quarter despite challenging cost environment | – Payable | gold production | 1 | in the fourth quarter of 2022 was 799,438 ounces at production costs per ounce of $834, total cash costs | per ounce | 2 | of $863 and all-in sustaining costs (“AISC”) per ounce | 3 | of $1,231. Quarterly unit costs', 'production-v2', 0.8, '2026-06-17T12:00:08.936099+00:00', '2026-06-17T12:00:08.936099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-023723', '6-K', '2023-02-21', '2023-02-16', 2023, NULL, 'quarter', 'Project and Exploration Highlights', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923023723/tm234901d1_ex99-1.htm', 'Yamana Transaction | • | An | update on Yamana Transaction is set out in the Update on Yamana Transaction section above | Goldex – Record Annual Ore Hoisting | and Tonnes Milled Sets New Record for Annual Gold Production Since Re-start in 2013 | The 100% owned Goldex mine in northwestern Quebec | began production from the M and E zones in September 2013. Commercial production from the Deep 1 Zone commenced on July 1, | 2017. The Company approved the development of the Akasaba West project, located less than 30 kilometres from Goldex, in July 2022 | . | 71 | Goldex Mine – Operating Statistics | Three Months Ended', 'production-v2', 0.8, '2026-06-17T12:00:08.936099+00:00', '2026-06-17T12:00:08.936099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-023723', '6-K', '2023-02-21', '2023-02-16', 2023, NULL, 'quarter', 'open pit at Meliadine and Amaruq underground project, respectively.', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923023723/tm234901d1_ex99-1.htm', 'gold production was 799,438 ounces. This compares to quarterly payable gold production of 501,932 ounces in the prior-year period. In | the full year 2022, the Company’s gold production was a record 3,135,007 ounces. Including the entire full year’s production from the | pre-Merger Kirkland Lake Gold mines, total gold production in the full year 2022 was 3,280,731 ounces. This compares to payable gold production | of 2,086,405 ounces in the full year 2021, which included 24,057 ounces and 1,956 ounces of pre-commercial production of gold at the Tiriganiaq | open pit at Meliadine and Amaruq underground project, respectively. | Gold production in the fourth quarter of 2022 | and the full year 2022, when compared to the prior-year periods, was higher primarily due to the inclusion of the production from the | Detour Lake, Fosterville and Macassa mines. This was partially offset by the cessation of gold production in 2022 at Hope Bay following | the Company’s decision to dedicate the infrastructure at Hope Bay to exploration activities and lower production at the Company’s Pinos | Altos mine, Kittila mine and the LaRonde Complex. | Production costs per ounce in the fourth quarter | of 2022 were $834, compared to $934 in the prior-year period. Total cash costs per ounce in the fourth quarter of 2022 were $863, compared | to $814 in the prior-year period.', 'production-v2', 0.8, '2026-06-17T12:00:08.936099+00:00', '2026-06-17T12:00:08.936099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-023723', '6-K', '2023-02-21', '2023-02-16', 2023, NULL, 'quarter', 'plan and achieved a record breaking year in terms of since Goldex restarted operations in', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923023723/tm234901d1_ex99-1.htm', 'Gold production | in the | full year 2022 | increased when compared to the prior-year period primarily due to higher | gold grades and higher throughput levels. In 2022, the Goldex mine continued to deliver solid performance in line with the production | plan and achieved a record breaking year in terms of gold production since Goldex restarted operations in 2013. | Production | costs per tonne in the | full year 2022 | increased when compared to the prior-year period primarily | due to higher mine development and production costs resulting from higher | ground support costs, increased | development', 'production-v2', 0.8, '2026-06-17T12:00:08.936099+00:00', '2026-06-17T12:00:08.936099+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-053855', '6-K', '2023-05-01', '2023-03-31', 2023, 'Q1', 'quarter', 'Consolidated', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923053855/tm2310410d3_ex99-1.htm', 'quarter of 2022 when cash provided by operating activities was $507.4 million ($366.0 million before changes in non-cash components | of working capital). | Cash provided by operating activities (before | changes in non-cash components of working capital) increased in the first quarter of 2023 when compared to the prior-year period primarily | due to higher sales volumes following the merger (the "Merger") between Agnico Eagle and Kirkland Lake Gold Ltd. ("Kirkland | Lake Gold") as opposed to the 58 days of production that followed the Merger in 2022. | In the first quarter of 2023, the Company''s payable | gold production was 812,813 ounces. This compares to quarterly payable gold production of 660,604 ounces in the prior-year period. Including | the entire quarter''s production from the pre-Merger Kirkland Lake Gold mines, | pro forma | total gold production in the first quarter | of 2022 was 806,329 ounces. | 5', 'production-v2', 0.8, '2026-06-17T12:00:08.402977+00:00', '2026-06-17T12:00:08.402977+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-073599', '6-K', '2023-06-22', '2023-06-20', 2023, 'Q2', 'quarter', 'Consolidated', 'gold', 2042.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923073599/tm2319184d1_ex99-1.htm', 'year, compared to $56 million per year estimated in the 2020 Study. | Total | cash costs per ounce are now forecast to be approximately $768 from 2029 to 2042, compared to $630 from 2029 to 2039 in the 2020 Study. | Costs estimates, including underground development and mining costs, processing costs and equipment procurement, reflect the new cost | environment following three years of high inflationary cost pressures. The Company continues to evaluate opportunities to further optimize | and improve gold production and unit costs from 2029 through 2042. | A larger mineable resource, construction | progress and current higher gold price environment contributed to offset cost inflation and resulted in stronger mine economics. Using | a gold price of $1,650 per ounce and a C$/US$ foreign exchange rate assumption of 1.32, the Odyssey mine has an after-tax IRR of 24% and | an after-tax NPV (5% discount rate) of $1.60B. Using a recent spot gold price ($1,950 per ounce) the Odyssey mine after-tax IRR improves | to 33% and the after-tax NPV (5% discount rate) to $2.46 billion. | In the 2020 Study, the Odyssey | project had an estimated after-tax IRR of 17.5% and an after-tax NPV (5% discount rate) of $1.14B, using a gold price of $1,550 per ounce', 'production-v2', 0.8, '2026-06-17T12:00:08.306771+00:00', '2026-06-17T12:00:08.306771+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-084368', '6-K', '2023-07-26', '2023-06-30', 2023, 'Q2', 'quarter', 'Fosterville mine', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923084368/tm2318988d2_ex99-1.htm', 'Meadowbank complex | At the Meadowbank complex, gold production decreased by 2.0% to 94,775 ounces in the second quarter of 2023, compared with 96,698 ounces in the second quarter of 2022, primarily due to lower grades, partially offset by higher volume of ore processed. Production costs at the Meadowbank complex were $117.5 million in the second quarter of 2023, an increase of 9.4% compared with production costs of $107.4 million in the second quarter of 2022, primarily due to higher underground mining costs and higher fuel and logistics costs, partially offset by the weakening of the Canadian dollar relative to the US dollar between periods. | Gold production increased by 31.6% to 205,885 ounces in the first six months of 2023 compared with 156,463 ounces in the first six months of 2022 at the Meadowbank complex, due to higher volume of ore tonnes processed and gold grades. In mid-January 2022, the mine had returned to normal operating levels after the Company had focused on production and reduced the level of some supporting activities, including underground development, in response to an outbreak of the COVID-19 Omicron variant in December 2021, which affected the mining sequence. Production costs at the Meadowbank complex were $247.5 million in the first six months of 2023, an increase of 21.3% compared with production costs of $204.1 million in the first six months of 2022, primarily due to higher mining and fuel and logistics costs, partially offset by a build up in stockpiles, a decrease in deferred stripping costs, and the weakening of the Canadian dollar relative to the US dollar between periods. | Commercial production was achieved at the Amaruq underground project in August 2022. | Fosterville mine | At the Fosterville mine, gold production decreased by 4.9% to 81,813 ounces in the second quarter of 2023 compared with 86,065 ounces in the second quarter of 2022, primarily due to lower grade from mining sequencing, partially offset by higher tonnage. Prod', 'production-v2', 0.8, '2026-06-17T12:00:08.265538+00:00', '2026-06-17T12:00:08.265538+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-085219', '6-K', '2023-07-28', '2023-07-26', 2023, NULL, 'quarter', 'Consolidated', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923085219/tm2318988d3_ex99-1.htm', 'First Six Months of 2023 – Minesite costs per tonne increased when compared to the prior-year period | primarily due to the reasons outlined above. Total cash costs per ounce increased when compared to the prior-year period primarily due | to the reasons outlined above | Highlights | · | Despite the decrease in gold production when compare to the prior-year period, the second quarter of 2023 | saw higher than expected gold production due to solid underground productivity from both the LaRonde and the LaRonde Zone 5 mines and | higher than expected grades from the LaRonde mine. Underground development remained above target despite fewer production days as a result | of the poor air quality from wildfires in the area. The mill also outperformed targets despite power outages in the area related to the | wildfires | · | The LaRonde Zone 5 processing facility is now planned to be idled late in the fourth quarter of 2023 (previously | the third quarter of 2023) to take advantage of the approximately 2,000 tpd of excess capacity in the LaRonde mill. A planned 10-day shutdown', 'production-v2', 0.8, '2026-06-17T12:00:08.055008+00:00', '2026-06-17T12:00:08.055008+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-085219', '6-K', '2023-07-28', '2023-07-26', 2023, NULL, 'quarter', 'Minesite costs per tonne is a non-GAAP measure that does', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923085219/tm2318988d3_ex99-1.htm', '8 | Minesite costs per tonne is a non-GAAP measure that does | not have a standardized meaning under IFRS. For a reconciliation to production costs see "Reconciliation of Non-GAAP Performance Measures" | below. See also "Note Regarding Certain Measures of Performance". | 21 | Gold Production | · | Second Quarter of 2023 – Gold production decreased when compared to the prior-year period primarily | due to lower processing volumes and lower grades as a result of changes in the mining method at the LaRonde mine that resulted in more | lower grade ore being sourced from upper portions of the mine and a slower mining rate | · | First Six Months of 2023 – Gold Production decreased when compared to the prior-year period due | to lower grades and lower processing volumes as a result of the changes in mining method described above', 'production-v2', 0.8, '2026-06-17T12:00:08.055008+00:00', '2026-06-17T12:00:08.055008+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-085219', '6-K', '2023-07-28', '2023-07-26', 2023, NULL, 'quarter', 'of the Canadian Malartic complex.', 'gold', 858170.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923085219/tm2318988d3_ex99-1.htm', 'Operating margin is a non-GAAP measure | that is not a standardized measure under IFRS. For a reconciliation to net income see "Reconciliation of Non-GAAP Financial Performance | Measures" below. See also "Note Regarding Certain Measures of Performance". | 6 | In the second quarter | of 2023, the Company''s payable gold production was a record 873,204 ounces. This compares to quarterly payable gold production of 858,170 | ounces in the prior-year period as the additional production from the acquisition of the remaining 50% of the Canadian Malartic complex | was partially offset by lower production at the Detour Lake and LaRonde mines. | In the first six | months of 2023, the Company''s payable gold production was 1,686,017 ounces compared to the first six months of 2022 when payable gold | production was 1,518,774 ounces. The increase in payable gold production is a result of additional days of production in 2023 at the | Detour Lake, Macassa and Fosterville mines as described above and the additional production from the acquisition of the remaining 50% | of the Canadian Malartic complex, partially offset by lower production at the Detour Lake and LaRonde mines.', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:08.055008+00:00', '2026-07-01T23:00:29.663178+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-111470', '6-K', '2023-10-25', '2023-09-30', 2023, 'Q3', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923111470/tm2326479d2_ex99-1.htm', '​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Nine Months Ended September 30, 2023 | costs and higher mill services costs from the transition to dry tailings disposition, partially offset by a weaker Canadian dollar relative to the U.S. dollar. | Production costs per tonne increased when compared to the prior-year period due to the reasons outlined above and lower volume of ore milled in the current period, Production costs per ounce increased when compared to the prior-year period due to the reasons outlined above and fewer gold ounces produced in the current period. | Minesite cost per tonne and total cash costs per ounce of gold produced | Third Quarter of 2023 — Minesite costs per tonne increased when compared to the prior-year period primarily due lower volume of ore milled. Total cash costs per ounce increased when compared to the prior-year period primarily due to fewer ounces of gold produced as a result of lower throughput levels and lower grades, partially offset by a weaker Canadian dollar relative to the U.S. dollar.', 'production-v2', 0.65, '2026-06-17T12:00:07.954986+00:00', '2026-06-17T12:00:07.954986+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-111470', '6-K', '2023-10-25', '2023-09-30', 2023, 'Q3', 'quarter', 'Consolidated', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923111470/tm2326479d2_ex99-1.htm', '​ | $ | 590 | ​ | ​ | Gold production | Third Quarter of 2023 — At the LaRonde mine, gold production decreased by 22.4% to 49,303 ounces in the third quarter of 2023, compared with 63,573 ounces in the third quarter of 2022, primarily due to lower throughput levels and lower grades as a result of an extended planned shutdown at the mill and for the maintenance of the ore handling systems as well as changes in the mining method which resulted in more lower grade ore being sourced from upper portions of the mine and a slower mining rate. | First Nine Months of 2023 — Gold production decreased by 24.5% to 167,471 ounces in the first nine months of 2023, compared with 221,858 ounces in the first nine months of 2022 at the LaRonde mine, primarily due to lower throughput levels and lower grades as a result of the reasons described above. | Production costs | Third Quarter of 2023 — Production costs at the LaRonde mine were $66.5 million in the third quarter of 2023, a decrease of 20.8% compared with production costs of $83.9 million in the third quarter of 2022, primarily due to the timing of inventory sales and the weakening of the Canadian dollar relative to the US dollar between periods. | Production costs per tonne decreased when compared to the prior-year period due to the reasons outlined above and lower volume of ore milled in the current period. Production costs per ounce increased when compared to the prior-year period due to fewer gold ounces produced in the current period. | First Nine Months of 2023 — Production costs at the LaRonde mine were $170.2 million in the first nine months of 2023, an increase of 3.9% compared with production costs of $163.7 million in the first nine months of 2022, primarily due to higher underground mining costs from higher labour and materials | 8', 'production-v2', 0.8, '2026-06-17T12:00:07.954986+00:00', '2026-06-17T12:00:07.954986+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-23-111470', '6-K', '2023-10-25', '2023-09-30', 2023, 'Q3', 'quarter', 'Minesite cost per tonne and total cash costs per ounce of gold produced', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465923111470/tm2326479d2_ex99-1.htm', 'Third Quarter of 2023 — Production costs at the Meadowbank complex were $133.9 million in the third quarter of 2023, an increase of 21.8% compared with production costs of $109.9 million in the third quarter of 2022, primarily due to a higher stripping ratio at the open pit and the consumption of stockpiles during 2023, partially offset by the weakening of the Canadian dollar relative to the US dollar between periods. | Production costs per tonne increased when compared to the prior-year period due to a higher stripping ratio at the open pit and the consumption of stockpiles, partially offset by the higher volume of ore milled in the current period. Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above as well as fewer ounces of gold being produced in the current period and the weaker Canadian dollar relative to the U.S. dollar. | First Nine Months of 2023 — Production costs at the Meadowbank complex were $381.4 million in the first nine months of 2023, an increase of 21.5% compared with production costs of $314.0 million in the first nine months of 2022, primarily due to a higher stripping ratio at the open pit and the consumption of stockpiles during 2023, partially offset by the weakening of the Canadian dollar relative to the US dollar between periods. | Production costs per tonne increased when compared to the prior-year period due to a higher stripping ratio at the open pit and the consumption of stockpiles during 2023, partially offset by the higher volume of ore milled in the current period. Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above, partially offset by more ounces of gold produced in the current period and the weaker Canadian dollar relative to the U.S. dollar. | Commercial production was achieved at the Amaruq underground project in August 2022. | Minesite cost per tonne and total cash costs per ounce of gold produced | Thir', 'production-v2', 0.65, '2026-06-17T12:00:07.954986+00:00', '2026-06-17T12:00:07.954986+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-025342', '6-K', '2024-02-20', '2024-02-15', 2024, NULL, 'quarter', 'Consolidated', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924025342/tm242398d2_ex99-1.htm', '$ | 1,109 | * Production and Cost Results Summary reflect: (i) Agnico Eagle''s | 50% interest in the Canadian Malartic complex up to and including March 30, 2023 and 100% thereafter; and (ii) Agnico Eagle''s | acquisition of the Detour Lake, Macassa and Fosterville mines on February 8, 2022. | Gold Production | · | Fourth | Quarter of 2023 – Gold production increased when compared to the prior year primarily | due to additional production from the acquisition of the remaining 50% of the Canadian Malartic | complex following the closing of the transaction with Yamana Gold Inc. (the "Yamana | Transaction") and higher production from the Macassa and Kittila mines, partially offset | by lower production at the Fosterville mine', 'production-v2', 0.8, '2026-06-17T12:00:07.719029+00:00', '2026-06-17T12:00:07.719029+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-025342', '6-K', '2024-02-20', '2024-02-15', 2024, NULL, 'quarter', 'Minesite and Total Cash Costs', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924025342/tm242398d2_ex99-1.htm', 'Fourth Quarter of 2023 – Minesite costs per tonne decreased when compared to the prior-year period | due to the same reasons as the higher production costs per tonne. Total cash costs per ounce decreased when compared to the prior-year | period due to more ounces of gold produced and the weaker Canadian dollar relative to the U.S. dollar | · | Full Year 2023 – Minesite costs per tonne increased when compared to the prior-year period due to | the same reasons as the higher production costs per tonne. Total cash costs per ounce decreased when compared to the prior-year period | due to more gold ounces produced and the weaker Canadian dollar relative to the U.S. dollar | Highlights | ·', 'production-v2', 0.65, '2026-06-17T12:00:07.719029+00:00', '2026-06-17T12:00:07.719029+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-025342', '6-K', '2024-02-20', '2024-02-15', 2024, NULL, 'quarter', 'performance drove the lowest minesite costs per tonne since the Merger', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924025342/tm242398d2_ex99-1.htm', '· | In the fourth quarter and full year of 2023, realized gold grades were lower than forecast largely due | to the addition to the mine plan of lower grade opportunity ounces as a result of the increased mining rate and available mill capacity | · | At the Portal (ramp access to the NSUR) production from long hole stopes continued in the fourth quarter | of 2023. Gold production from NSUR was approximately 4,800 ounces in the fourth quarter of 2023 | · | The construction of the enclosure of the surface fans continued according to schedule in the fourth quarter | of 2023 and both fans were operating at 60%. The overall ventilation system upgrade is currently on track for completion in the first | quarter of 2024, when both fans are anticipated to reach full capacity | 34 | NUNAVUT | Meliadine Mine – Record Annual Safety', 'production-v2', 0.8, '2026-06-17T12:00:07.719029+00:00', '2026-06-17T12:00:07.719029+00:00');
