INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-052055', '6-K', '2024-04-25', '2024-03-31', 2024, 'Q1', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924052055/tm249129d2_ex99-1.htm', '​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three Months Ended March 31, 2024 | Gold production | First Quarter of 2024 — Gold production decreased when compared to the prior-year period due to lower volumes of ore milled and lower gold grades expected under the mining sequence. | Production costs | First Quarter of 2024 — Production costs at the LaRonde complex increased by 52.7% in the first quarter of 2024 when compared with the first quarter of 2023, primarily due to stockpile consumption, the timing of inventory sales, and higher underground maintenance costs. | Production costs per tonne increased when compared to the prior-year period primarily due to lower volume of ore milled in the current period and the reasons explained above for the increase in production costs, excluding the timing of inventory sales. Production costs per ounce increased when compared to the prior-year period primarily due to fewer ounces of gold produced and the reasons outlined above for production costs. | Minesite cost per tonne and total cash costs per ounce | First Quarter of 2024 — Minesite costs per tonne increased when compared to the prior-year period primarily due to the reasons outlined above regarding the increase in production costs per tonne. Total cash costs per ounce increased when compared to the prior-year period primarily for the same reasons as the increase in production costs per ounce. | Canadian Malartic complex', 'production-v2', 0.8, '2026-06-17T12:00:07.242272+00:00', '2026-06-17T12:00:07.242272+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-052055', '6-K', '2024-04-25', '2024-03-31', 2024, 'Q1', 'quarter', 'Consolidated', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924052055/tm249129d2_ex99-1.htm', '​ | $ | 892 | ​ | ​ | Gold production | First Quarter of 2024 — At the LaRonde mine, gold production decreased by 13.0% to 51,815 ounces in the first quarter of 2024, compared with 59,533 ounces in the first quarter of 2023, primarily due to lower gold grades as a result of mining sequencing and lower recovery due to ore with high copper content which was partially offset by higher throughput levels. | Production costs | First Quarter of 2024 — Production costs at the LaRonde mine were $75.6 million in the first quarter of 2024, an increase of 90.3% compared with production costs of $39.7 million in the first quarter of 2023, primarily due to the timing of inventory sales and higher underground maintenance costs. | Production costs per tonne increased when compared to the prior-year period due to the same reasons outlined above for the increase in production costs, partially offset by the higher volume of ore milled in the current period. Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above for production costs and fewer ounces of gold produced in the current period. | Minesite cost per tonne and total cash costs per ounce | First Quarter of 2024 — Minesite costs per tonne decreased when compared to the prior-year period primarily due to higher volume of ore milled. Total cash costs per ounce increased when compared to the prior-year period primarily due to fewer ounces of gold produced as a result of lower grades and recovery, partially offset by higher throughput. | 5', 'production-v2', 0.8, '2026-06-17T12:00:07.242272+00:00', '2026-06-17T12:00:07.242272+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-053618', '6-K', '2024-04-29', '2024-04-29', 2024, NULL, 'quarter', 'Consolidated', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924053618/tm249129d3_ex99-1.htm', '1,190 | $ | 1,125 | * Reflects Agnico Eagle''s 50% interest in the Canadian Malartic | complex up to and including March 30, 2023 and 100% interest thereafter. | Gold Production | Gold production increased in the first quarter | of 2024 when compared to the prior-year period primarily due to additional production from the acquisition of the remaining 50% of the | Canadian Malartic complex following the closing of the acquisition of the Canadian assets of Yamana Gold Inc. (the "Yamana Transaction") | and higher production from the Meadowbank complex, partially offset by lower production at the Fosterville mine. | Production Costs per Ounce | Production costs per ounce increased in the first | quarter of 2024 when compared to the prior-year period primarily due to higher production costs at most mine sites resulting from inflation,', 'production-v2', 0.8, '2026-06-17T12:00:07.098327+00:00', '2026-06-17T12:00:07.098327+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-073878', '6-K', '2024-06-21', '2024-06-19', 2024, 'Q2', 'quarter', 'Consolidated', 'gold', 17300000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924073878/tm2417599d1_ex99-1.htm', 'Average Mill Throughput | Mtpa | 28.0 | 28.0 | 29.0 | Gold production | Open Pit | Moz | 17.3 | 18.0 | 18.0 | Underground | Moz', 'production-v2', 0.8, '2026-06-17T12:00:07.024016+00:00', '2026-07-01T23:00:24.395659+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-084418', '6-K', '2024-07-31', '2024-06-30', 2024, 'Q2', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924084418/tm2416946d2_ex99-1.htm', '​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | (Prepared in accordance with International Financial Reporting Standards) | For the Three and Six Months Ended June 30, 2024 | Gold production | Second Quarter of 2024 — At Macassa, gold production increased by 12.3% to 64,062 ounces in the second quarter of 2024 compared with 57,044 ounces in the second quarter of 2023, primarily due to higher throughput, as a result of increased productivity from a larger workforce, new ventilation infrastructure, and improved equipment availability and the addition of ore sourced from the Near Surface deposit, partially offset by lower gold grades. | First Six Months of 2024 — Gold production at Macassa increased by 9.2% to 132,321 ounces in the first six months of 2024 compared to 121,159 ounces in the first six months of 2023, primarily due to higher throughput, as a result of increased productivity from a larger workforce, new ventilation infrastructure and improved equipment availability and the addition of ore sourced from the Near Surface deposit, partially offset by lower gold grades. | Production costs | Second Quarter of 2024 — Production costs were $51.0 million in the second quarter of 2024, an increase of 32.4% compared with production costs of $38.5 million in the second quarter of 2023, primarily due to higher mining costs resulting from increased mining activities in the period when compared to the prior period. | Production costs per tonne decreased when compared to the prior-year period due to the higher volume of ore milled in the current period, partially offset by higher underground development and mining costs. Production costs per ounce increased when compared to the prior-year period due to higher underground development and mining costs, partially offset by increased gold production in the current period. | First Six Months of 2024 — Production costs were $98.7 million in the first six months of 2024, an increase of 29.0% compared to p', 'production-v2', 0.8, '2026-06-17T12:00:06.978897+00:00', '2026-06-17T12:00:06.978897+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-084418', '6-K', '2024-07-31', '2024-06-30', 2024, 'Q2', 'quarter', 'Consolidated', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924084418/tm2416946d2_ex99-1.htm', '​ | $ | 840 | ​ | ​ | Gold production | Second Quarter of 2024 — At the LaRonde mine, gold production increased by 6.2% to 62,260 ounces in the second quarter of 2024, compared with 58,635 ounces in the second quarter of 2023, primarily due to higher throughput levels partially offset by lower gold grades and recovery. | First Six Months of 2024 — Gold production decreased by 3.5% to 114,075 ounces in the first six months of 2024, compared with 118,168 ounces in the first six months of 2023 at the LaRonde mine primarily due to lower gold grades and recovery, partially offset by higher throughput levels. | Production costs | Second Quarter of 2024 — Production costs at the LaRonde mine were $43.7 million in the second quarter of 2024, a decrease of 31.7% compared with production costs of $64.0 million in the second quarter of 2023, primarily due to the timing of inventory sales partially offset by the consumption of stockpiles and higher royalty costs. | Production costs per tonne decreased when compared to the prior-year period due to the same reasons outlined above for production costs and the higher volume of ore milled in the current period. Production costs per ounce decreased when compared to the prior-year period due to the same reasons outlined above for production costs and more gold ounces produced in the current period. | First Six Months of 2024 — Production costs at the LaRonde mine were $119.2 million in the first six months of 2024, an increase of 15.0% compared with production costs of $103.7 million in the first six months of 2023, primarily due to timing of inventory sales and higher milling and royalty costs. | 7', 'production-v2', 0.8, '2026-06-17T12:00:06.978897+00:00', '2026-06-17T12:00:06.978897+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-084864', '6-K', '2024-08-01', '2024-07-31', 2024, NULL, 'quarter', 'Consolidated', 'gold', 82334.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924084864/tm2416946d3_ex99-1.htm', 'June 30, | 2024 | 2023 | 2024 | 2023 | Gold production | (ounces) | 82,334 | 76,780 | 150,698 | 156,387 | (thousands) | ($ per ounce)', 'production-v2', 0.8, '2026-06-17T12:00:06.687012+00:00', '2026-07-01T23:00:23.342605+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-084864', '6-K', '2024-08-01', '2024-07-31', 2024, NULL, 'quarter', 'mine at Canadian Malartic', 'gold', 3750.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924084864/tm2416946d3_ex99-1.htm', 'potential at depth and within satellite deposits in the Company''s Kirkland Lake camp | ■ | Odyssey | mine at Canadian Malartic | – At Odyssey South, record quarterly mining rates and | gold production | were achieved at approximately 3,750 tpd and 22,300 ounces of gold, | respectively. In the second quarter of 2024, ramp development continued to exceed the Company''s | target, reaching the third production level at East Gouldie at a depth of 832 metres as at | June 30, 2024. Shaft sinking advanced at an average rate of 2.5 metres per day and reached | a depth of 680 metres as at June 30, 2024. Surface construction is progressing as planned, | with a focus on the main hoist building, phase two of the paste plant and the operations | complex', 'production-v2', 0.8, '2026-06-17T12:00:06.687012+00:00', '2026-07-01T23:00:23.342605+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-112652', '6-K', '2024-10-30', '2024-09-30', 2024, 'Q3', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924112652/tm2423828d1_ex99-1.htm', '20 | ​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | For the Three and Nine Months Ended September 30, 2024 | First Nine Months of 2024 — Gold production decreased by 62.4% to 21,190 ounces in the first nine months of 2024, compared with 56,423 ounces in the first nine months of 2023 for the same reasons outlined above for the third quarter of 2024. | Production costs | Third Quarter of 2024 — Production costs at La India were $10.4 million in the third quarter of 2024, a decrease of 63.2% compared with production costs of $28.3 million in the third quarter of 2023, driven primarily by the cessation of mining activities. | Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above primarily due to fewer ounces of gold produced in the period. | First Nine Months of 2024 — Production costs at La India were $39.4 million in the first nine months of 2024, a decrease of 45.3% compared with production costs of $72.1 million in the first nine months of 2023, driven primarily by the cessation of mining activities. | Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above primarily due to fewer ounces of gold produced in the period. | Minesite cost per tonne and total cash costs per ounce | Third Quarter of 2024 — Total cash costs per ounce increased when compared to the prior-year period primarily due to fewer ounces of gold produced in the period.', 'production-v2', 0.8, '2026-06-17T12:00:06.580628+00:00', '2026-06-17T12:00:06.580628+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-112652', '6-K', '2024-10-30', '2024-09-30', 2024, 'Q3', 'quarter', 'Consolidated', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924112652/tm2423828d1_ex99-1.htm', '​ | $ | 850 | ​ | ​ | Gold production | Third Quarter of 2024 — At the LaRonde mine, gold production decreased by 4.0% to 47,313 ounces in the third quarter of 2024, compared with 49,303 ounces in the third quarter of 2023, primarily due to lower throughput levels and lower gold grades expected under the planned mining sequence. | First Nine Months of 2024 — Gold production decreased by 3.6% to 161,388 ounces in the first nine months of 2024, compared with 167,471 ounces in the first nine months of 2023 at the LaRonde mine primarily due to lower gold grades and recovery, partially offset by higher throughput levels. | Production costs | Third Quarter of 2024 — Production costs at the LaRonde mine were $74.2 million in the third quarter of 2024, an increase of 11.7% compared with production costs of $66.5 million in the third quarter of 2023, primarily due to the consumption of stockpiles, including re-handling costs, in the current quarter compared to a stockpile build up in the prior year, due to planned mine shutdowns in the current period, partially offset by the weakening of the Canadian dollar relative to the US dollar between periods. | Production costs per tonne increased when compared to the prior-year period due to the lower volume of ore milled in the current period and the same reasons outlined above for production costs, other than foreign exchange effects between periods. Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above for production costs and fewer gold ounces produced in the current period. | First Nine Months of 2024 — Production costs at the LaRonde mine were $193.5 million in the first nine months of 2024, an increase of 13.7% compared with production costs of $170.2 million in the first nine months of 2023, primarily due to timing of inventory sales, the consumption of stockpiles, including re-handling costs, and higher underground and mill maintenance costs, partially offset by th', 'production-v2', 0.8, '2026-06-17T12:00:06.580628+00:00', '2026-06-17T12:00:06.580628+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-24-113149', '6-K', '2024-11-01', '2024-10-30', 2024, NULL, 'quarter', 'Consolidated', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465924113149/tm2423828d4_ex99-1.htm', '1,214 | $ | 1,162 | * Production and Cost Results Summary reflects Agnico Eagle''s 50% | interest in Canadian Malartic up to and including March 30, 2023 and 100% thereafter. | Gold Production | · | Third | Quarter of 2024 – Gold production increased when compared to the prior-year period | primarily due to higher production from the Nunavut operations, Macassa and Detour Lake, | partially offset by lower production at Canadian Malartic and La India | · | First', 'production-v2', 0.8, '2026-06-17T12:00:06.362693+00:00', '2026-06-17T12:00:06.362693+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-013049', '6-K', '2025-02-13', '2024-12-31', 2024, 'FY', 'quarter', 'Consolidated', 'gold', 3485336.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925013049/aem-20241231xex99d3.htm', 'Agnico Eagle earns a significant proportion of its revenue and cash flow from the production and sale of gold in both doré bar and concentrate form. The remainder of revenue and cash flow is generated by the production and sale of by-product metals, primarily silver, zinc and copper. In 2024, Agnico Eagle recorded production costs per ounce of $885 and total cash costs per ounce | (i) | of $903 on a by-product basis and $940 on a co-product basis on payable production of 3,485,336 ounces of gold. The average realized price of gold increased by 22.5% from $1,946 per ounce in 2023 to $2,384 per ounce of payable production in 2024. | Agnico Eagle’s operating mines and development projects are located in what the Company believes to be politically stable countries that are supportive of the mining industry. The political stability of the regions in which Agnico Eagle operates helps to provide confidence in its current and future prospects and profitability. This is important for Agnico Eagle as it believes that many of its new mines and recently acquired mining projects have long-term mining potential. | Highlights | ● | Strong operational performance with payable production of 3,485,336 ounces of gold and production costs per ounce of gold of $885 during 2024. | ●', 'production-v2', 0.95, '2026-06-11T02:57:23.691159+00:00', '2026-07-01T23:00:19.685339+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-013049', '6-K', '2025-02-13', '2024-12-31', 2024, 'FY', 'quarter', 'Minesite and Total Cash Costs', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925013049/aem-20241231xex99d1.htm', 'Fourth Quarter of 2024 – Minesite costs per tonne increased when compared to the prior-year period due to higher royalty costs during the quarter and a lower volume of ore milled. Total cash costs per ounce increased when compared to the prior-year period primarily due to fewer ounces of gold produced in the current period | ● | Full Year 2024 – Minesite costs per tonne increased when compared to the prior year due to higher royalty costs in the current period partially offset by a higher volume of ore milled. Total cash costs per ounce increased when compared to the prior year for the same reasons outlined above for the increased production costs per ounce | Highlights | ● | At Odyssey South, total development during the quarter was ahead of plan at approximately 3,630 metres. Gold production was in line with target at approximately 21,500 ounces of gold supported by record performance in December at approximately 3,838 tpd. The increased use of tele-operated and automated equipment, including scoops, trucks, jumbos and cable bolters, were the main drivers for exceeding the development and production targets in the fourth quarter of 2024 | 22 | ● | The Company began in-pit tailings disposal in July 2024. During the ramp-up in the fourth quarter of 2024, the Company made adjustments to the process to address the migration of fine materials through the central berm. The adjustments include installing a filtering layer on the central berm. It is expected that in-pit tailings deposition will resume in the first quarter of 2025 and ramp-up to design capacity in the second quarter of 2025 | ● | An update on the Odyssey development and construction highlights is set out in the Update on Key Value Drivers and Pipeline | Projects section above. An update on the exploration results is set out in the Company’s exploration news release dated February 13, | 2025', 'production-v2', 0.8, '2026-06-17T12:00:06.244923+00:00', '2026-06-17T12:00:06.244923+00:00');
