INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-038730', '6-K', '2025-04-24', '2025-03-31', 2025, 'Q1', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925038730/tm2512606d2_ex99-1.htm', '7 | ​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | For the Three Months Ended March 31, 2025 | Gold production | First Quarter of 2025 — At Canadian Malartic, gold production decreased by 14.5% to 159,773 ounces in the first quarter of 2025 compared with 186,906 ounces in the first quarter of 2024, primarily due to lower grades as per the mining sequence and an increased sourcing of ore processed from the low grade stockpiles, and lower throughput. | Production costs | First Quarter of 2025 — Production costs at Canadian Malartic were $119.3 million in the first quarter of 2025, a decrease of 5.8% compared with production costs of $126.6 million in the first quarter of 2024. The decrease is mainly attributed to lower open-pit mining costs and the weakening of the Canadian dollar relative to the US dollar between periods, partially offset by higher royalty costs and the timing of inventory sales in the current period. | Production costs per tonne increased when compared to the prior-year period primarily due to lower volume of ore milled. Production costs per ounce increased when compared to the prior-year period due to fewer ounces of gold produced in the current period. | Minesite cost per tonne and total cash costs per ounce | First Quarter of 2025 — Minesite costs per tonne increased when compared to the prior-year period mainly due to the lower volume of ore milled. Total cash costs per ounce increased when compared to the prior-year period primarily due to fewer ounces of gold produced in the current period. | Goldex', 'production-v2', 0.8, '2026-06-17T12:00:05.373876+00:00', '2026-06-17T12:00:05.373876+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-038730', '6-K', '2025-04-24', '2025-03-31', 2025, 'Q1', 'quarter', 'Consolidated', 'gold', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925038730/tm2512606d2_ex99-1.htm', '​ | $ | 1,028 | ​ | ​ | Gold production | First Quarter of 2025 — At the LaRonde mine, gold production increased by 39.7% to 72,369 ounces in the first quarter of 2025, compared with 51,815 ounces in the first quarter of 2024, primarily due to higher gold grades as a result of mining sequencing, partially offset by lower throughput levels. | Production costs | First Quarter of 2025 — Production costs at the LaRonde mine were $64.5 million in the first quarter of 2025, a decrease of 14.6% compared with production costs of $75.6 million in the first quarter of 2024, primarily due to the timing of inventory sales, lower mining and milling costs and the weakening of the Canadian dollar relative to the US dollar between periods, partially offset by higher royalty costs. | Production costs per tonne increased when compared to the prior-year period mainly due to the lower volume of ore milled in the current period. Production costs per ounce decreased when compared to the prior-year period due to the same reasons outlined above for decreased production costs and increased ounces of gold produced in the current period. | 5 | ​ | AGNICO EAGLE MINES LIMITED', 'production-v2', 0.8, '2026-06-17T12:00:05.373876+00:00', '2026-06-17T12:00:05.373876+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-039916', '6-K', '2025-04-28', '2025-04-24', 2025, NULL, 'quarter', 'Consolidated', 'gold', 873794.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925039916/tm2512606d3_ex99-1.htm', 'First | quarter 2025 highlights: | · | Strong quarterly gold production and cost performance | – Payable | gold production | 1 | was 873,794 ounces at production costs per ounce of $879, total cash costs per ounce | 2 | of $903 | and all-in sustaining costs ("AISC") per ounce | 2 | of $1,183. The strong operational performance in the first quarter', 'production-v2', 0.8, '2026-06-17T12:00:05.232758+00:00', '2026-07-01T23:00:16.049753+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-072219', '6-K', '2025-07-30', '2025-07-30', 2025, NULL, 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925072219/tm2519744d2_ex99-1.htm', '14 | ​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | For the Three and Six Months Ended June 30, 2025 | Gold production | Second Quarter of 2025 — At Meliadine, gold production increased by 1.8% to 90,263 ounces in the second quarter of 2025 compared with 88,675 ounces in the second quarter of 2024, primarily due to higher throughput, partially offset by lower gold grades resulting from an increase sourcing of ore from the open pit in the current period. | First Six Months of 2025 — Gold production increased by 2.4% to 188,775 ounces in the first six months of 2025 compared with 184,400 ounces in the first six months of 2024, primarily due to higher throughput, partially offset by lower gold grades resulting from an increase sourcing of ore from the open pit in the current period. | Production costs | Second Quarter of 2025 — Production costs at Meliadine were $113.1 million in the second quarter of 2025, an increase of 31.6% compared with production costs of $85.9 million in the second quarter of 2024, primarily due the consumption of stockpiles, with associated re-handling costs, in the current period, higher underground development, mill maintenance, consumables and royalty costs, partially offset by lower open pit mining costs. | Production costs per tonne increased when compared to the prior-year period for the same reasons outlined above for higher production costs, partially offset by a higher volume of ore milled in the current period. Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above for higher production costs, partially offset by more ounces of gold produced in the current period. | First Six Months of 2025 — Production costs at Meliadine were $196.9 million during the first six months of 2025, an increase of 9.8% compared to production costs of $179.4 million during the first six months of 2024, primarily due the consumption of stockpiles, with associated re-handling', 'production-v2', 0.8, '2026-06-17T12:00:05.170518+00:00', '2026-06-17T12:00:05.170518+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-072219', '6-K', '2025-07-30', '2025-07-30', 2025, NULL, 'quarter', 'Consolidated', 'gold', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925072219/tm2519744d2_ex99-1.htm', '​ | $ | 874 | ​ | ​ | Gold production | Second Quarter of 2025 — At the LaRonde mine, gold production increased by 12.1% to 69,778 ounces in the second quarter of 2025, compared with 62,260 ounces in the second quarter of 2024, primarily due to higher gold grades as expected under the mining sequence and as result of positive grade reconciliation, partially offset by lower throughput levels due to a scheduled 10-day shutdown at the LaRonde mill during the current period. | First Six Months of 2025 — Gold production at the LaRonde mine increased by 24.6% to 142,147 ounces in the first six months of 2025, compared with 114,075 ounces in the first six months of 2024 primarily due to higher gold grades as expected under the mining sequence and as a result of positive grade reconciliation, partially offset by lower throughput levels. | Production costs | Second Quarter of 2025 — Production costs at the LaRonde mine were $60.7 million in the second quarter of 2025, an increase of 38.9% compared with production costs of $43.7 million in the second quarter of 2024, primarily due to the timing of inventory sales and higher underground development, milling, royalty and maintenance costs, partially offset by lower underground maintenance costs incurred in the current period. | Production costs per tonne increased when compared to the prior-year period due to the same reasons outlined above for higher production costs and the lower volume of ore tonnes processed in the current period. Production costs per ounce increased when compared to the prior-year period due to the same reasons outlined above for higher production costs, partially offset by higher gold production in the current period. | First Six Months of 2025 — Production costs at the LaRonde mine were $125.2 million in the first six months of 2025, an increase of 5.0% compared with production costs of $119.2 million in the first six months of 2024, primarily due to higher milling and underground maintenance costs and h', 'production-v2', 0.8, '2026-06-17T12:00:05.170518+00:00', '2026-06-17T12:00:05.170518+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-072613', '6-K', '2025-07-31', '2025-07-30', 2025, NULL, 'quarter', 'Consolidated', 'gold', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925072613/tm2519744d3_ex99-1.htm', 'the 5% in-kind net smelter return royalty held by Osisko Gold Royalties Ltd. Detour Lake''s payable metal sold excludes the 2% in-kind | net smelter royalty held by Franco-Nevada Corporation. Macassa''s payable metal sold excludes the 1.5% in-kind net smelter royalty held | by Franco-Nevada Corporation. For the six months ended June 30, 2025, 2,500 payable gold ounces sold are excluded at La India. | ***Production costs per ounce, total cash costs | per ounce and AISC per ounce are reported on a per ounce of gold produced basis. | Gold Production | · | Second Quarter and First Six Months of 2025 – Gold production decreased when compared to the prior-year | periods primarily due to lower production from Meadowbank (longer than expected Caribou migration affecting both mining and milling operations), | Fosterville (lower grade and throughput) and Canadian Malartic (lower throughput), partially offset by higher production at Macassa and | LaRonde (higher grades) | Production Costs per Ounce | ·', 'production-v2', 0.8, '2026-06-17T12:00:04.953110+00:00', '2026-06-17T12:00:04.953110+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-25-104746', '6-K', '2025-10-31', '2025-10-30', 2025, NULL, 'quarter', 'Consolidated', 'gold', 189.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465925104746/tm2525021d3_ex99-1.htm', 'Note Regarding | Certain Measures of Performance – Operating Margin | for more information on the Company''s calculation and use of operating margin. | (ii) Payable production (a non-GAAP | non-financial performance measure) is the quantity of mineral produced during a period contained in products that are or will be sold | by the Company, whether such products are sold during the period or held as inventories at the end of the period. For the three | months ended September 30, 2025, it excludes 945 payable gold ounces produced at La India and 189 payable gold ounces produced at | Creston Mascota as well as 2,442 ounces of gold recovered at Hope Bay. For the nine months ended September 30, 2025, it excludes | 3,614 payable gold ounces produced at La India and 253 payable gold ounces produced at Creston Mascota as well as 2,442 ounces of gold', 'production-v2', 0.65, '2026-06-17T12:00:04.864671+00:00', '2026-07-01T23:00:13.013065+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-26-014451', '6-K', '2026-02-13', '2025-12-31', 2025, 'FY', 'quarter', 'Annual Strengthened by Higher Grades; Updated Mine Plan Increases Production in', 'gold', 2028.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465926014451/aem-20251231xex99d1.htm', 'An update on Hope Bay is set out in the Update on Key Value Drivers and Pipeline Projects section above | ​ | 33 | AUSTRALIA | ​ | Annual Gold Production Strengthened by Higher Grades; Updated Mine Plan Increases Production in 2028 | ​ | ​ | ​ | ​ | ​ | ​ | ​', 'production-v2', 0.8, '2026-06-17T12:00:04.771626+00:00', '2026-06-17T12:00:04.771626+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-26-014451', '6-K', '2026-02-13', '2025-12-31', 2025, 'FY', 'quarter', 'Consolidated', 'gold', 323.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465926014451/aem-20251231xex99d1.htm', '​ | (i) | Operating margin is not a recognized measure under IFRS Accounting Standards and this data may not be comparable to data reported by other gold producers. See | Note Regarding Certain Measures of Performance – Operating Margin | for more information on the Company’s calculation and use of operating margin. | (ii) | Payable production (a non-GAAP non-financial performance measure) is the quantity of mineral produced during a period contained in products that are or will be sold by the Company, whether such products are sold during the period or held as inventories at the end of the period. For the three months ended December 31, 2025, it excludes 925 ounces of payable gold ounces at La India and 70 ounces of payable gold ounces at Creston Mascota as well as 7,026 ounces of gold recovered at Hope Bay. For the year ended December 31, 2025, it excludes 4,539 payable gold ounces produced at La India and 323 payable gold ounces produced at Creston Mascota as well as 9,468 ounces of gold recovered at Hope Bay. | (iii) | Payable metals sold at Canadian Malartic, Detour Lake and Macassa exclude the in-kind royalties of 5.0%, 2.0% and 1.5%, respectively, paid in respect of gold production at such mines. For the year ended December 31, 2025, it excludes 2,500 payable gold ounces sold at La India.', 'production-v2', 0.65, '2026-06-11T02:57:23.578841+00:00', '2026-07-01T23:00:10.953561+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-26-032153', '40-F', '2026-03-19', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 3447367.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465926032153/aem-20251231xex99d3.htm', 'Agnico Eagle earns substantially all of its revenue and cash flow from the production and sale of gold in both doré bar and concentrate form. In 2025, Agnico Eagle recorded production costs per ounce of $965 and total cash costs per ounce | (i) | of $979 on a by-product basis and $1,035 on a co-product basis on payable production of 3,447,367 ounces of gold. The average realized price of gold increased by 44.9% from $2,384 per ounce in 2024 to $3,454 per ounce of payable production in 2025. | Agnico Eagle’s operating mines and development projects are located in what the Company believes to be politically stable countries that are supportive of the mining industry. The political stability of the regions in which Agnico Eagle operates helps to provide confidence in its current and future prospects and profitability. This is important for Agnico Eagle as it believes that many of its mines and recently acquired mining projects have long-term mining potential. | Highlights | ● | Strong operational performance with payable production of 3,447,367 ounces of gold and production costs per ounce of gold of $965 during 2025. | ●', 'production-v2', 0.95, '2026-06-17T12:14:55.726689+00:00', '2026-07-01T23:22:51.105060+00:00');
