INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-26-053113', '6-K', '2026-04-30', '2026-03-31', 2026, 'Q1', 'quarter', 'AGNICO EAGLE MINES LIMITED', 'gold', 2026.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465926053113/tm2612722d2_ex99-1.htm', '8 | ​ | AGNICO EAGLE MINES LIMITED | MANAGEMENT’S DISCUSSION AND ANALYSIS | For the Three Months Ended March 31, 2026 | Gold production | First Quarter of 2026 — Gold production decreased by 35.4% to 55,593 ounces in the first quarter of 2026 compared with 86,028 ounces in the first quarter of 2025, primarily due to lower gold grades from the mining sequence. | Production costs | First Quarter of 2026 — Production costs were $72.5 million in the first quarter of 2026, an increase of 45.4% compared with production costs of $49.8 million in the first quarter of 2025, primarily due to higher mining costs from increased ore tonnes mined, the timing of inventory sales, higher royalty costs and the strengthening of the Canadian dollar relative to the US dollar between periods. | Production costs per tonne increased when compared to the prior-year period, primarily due to higher mining and royalty costs. Production costs per ounce increased when compared to the prior-year period primarily due to the same reasons outlined above for higher production costs and fewer ounces produced. | Minesite cost per tonne and total cash costs per ounce | First Quarter of 2026 — Minesite costs per tonne increased when compared to the prior-year period due to the same reasons outlined for higher production costs per tonne above. Total cash costs per ounce increased when compared to the prior-year period due to the same reasons outlined above for higher production costs per ounce. | Meliadine', 'production-v2', 0.8, '2026-06-17T12:00:03.439717+00:00', '2026-06-17T12:00:03.439717+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-26-053113', '6-K', '2026-04-30', '2026-03-31', 2026, 'Q1', 'quarter', 'Consolidated', 'gold', 2026.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465926053113/tm2612722d2_ex99-1.htm', '​ | ​ | * | The statistics above include operations at the LaRonde mine and LZ5. | ​ | Gold production | First Quarter of 2026 — Gold production at LaRonde decreased by 10.8% to 81,596 ounces in the first quarter of 2026 compared with 91,491 ounces in the first quarter of 2025, primarily due to lower gold grades from the mining sequence at the LaRonde mine, partially offset by higher throughput. | Production costs | First Quarter of 2026 — Production costs at LaRonde were $88.0 million in the first quarter of 2026 an increase of 1.6% compared with production costs of $86.6 million in the first quarter of 2025, primarily due to higher royalty, mining and milling costs, combined with the strengthening of the Canadian dollar relative to the US dollar between periods, partially offset by the timing of inventory sales. | Production costs per tonne decreased when compared to the prior-year period primarily due to the timing of inventory sales and the higher volume of ore milled, partially offset by the higher royalty, mining and milling costs. Production costs per ounce increased when compared to the prior-year period primarily due to the same reasons outlined above for higher production costs combined with fewer ounces of gold produced in the current period. | 5 | ​ | AGNICO EAGLE MINES LIMITED', 'production-v2', 0.8, '2026-06-17T12:00:03.439717+00:00', '2026-06-17T12:00:03.439717+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AEM', '0000002809', '0001104659-26-054134', '6-K', '2026-05-01', '2026-04-30', 2026, NULL, 'quarter', 'Consolidated', 'gold', 418.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2809/000110465926054134/tm2612722d3_ex99-1.htm', 'composition of this measure for periods ending on or prior to December 31, 2025, total | cash costs per ounce were $903 for the consolidated Company and AISC per ounce was $1,183 | for the consolidated Company. | ** | Gold production for the three months ended | March 31, 2026 excludes payable gold production at La India and Creston Mascota of 418 | and 76 ounces, respectively, which were produced from residual leaching. Gold production | for the three months ended March 31, 2025 excludes payable gold production at La India | and Creston Mascota of 1,811 ounces and 25 ounces, respectively, which were producing from | residual leaching. | *** | Payable metals sold at Canadian Malartic, | Detour Lake and Macassa exclude the in-kind royalties of 5.0%, 2.0% and 1.5%, respectively,', 'production-v2', 0.8500000000000001, '2026-06-17T12:00:03.309303+00:00', '2026-07-01T23:22:50.519977+00:00');
