INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-20-014443', '6-K', '2020-10-13', '2020-10-13', 2020, NULL, 'quarter', 'At the La Encantada Silver Mine', 'silver', 2014.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828020014443/ag-2020x10x13nrxex9911.htm', '• | The Company is expecting to release an updated NI 43-101 Technical Report on Santa Elena in the first quarter of 2021. | At the La Encantada Silver Mine | : | • | During the quarter, La Encantada processed 261,425 tonnes of ore and produced 978,416 ounces of silver, or approximately 92% above the previous quarter and the second highest quarterly production since 2014. | • | Silver grades and recoveries during the quarter averaged 152 g/t and 77%, respectively. | • | Caving production from the San Javier and La Prieta areas contributed approximately 73% of the total silver production during the quarter. The Company anticipates continued strong production rates from these caving areas for the remainder of the year. As a result, La Encantada is now expected to fully recover its lost silver ounces from the recent COVID-19 shutdown by year-end. | • | The mill modernization project designed to improve processing efficiencies is expected to accelerate in the fourth quarter with the installation of new scrubbers for the foundry, main gear replacement and new impellers for two thickener tanks, filter press upgrades and improvements to the electrical control room. | 3', 'production-v2', 0.8, '2026-06-16T14:48:40.943213+00:00', '2026-06-17T12:00:27.759191+00:00');
