INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-21-000592', '6-K', '2021-01-20', '2021-01-20', 2021, NULL, 'quarter', 'Consolidated', 'gold', 100081.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828021000592/ag-2021x01x20nrxex991.htm', '13,241,118 | (12%) | 26,343 | 25,771 | 2% | Gold ounces produced | 100,081 | 134,580 | (26%) | 2 | QUARTERLY REVIEW | Total ore processed during the quarter at the Company''s mines amounted to 625,332 tonnes, representing a 5% decrease compared to the previous quarter. The decrease in tonnes processed was primarily due to lower production at Santa Elena’s Main Vein partially offset by higher production rates at San Dimas. | Consolidated silver and gold grades in the quarter averaged 194 g/t and 1.37 g/t, respectively, compared to 170 g/t and 1.27 g/t, respectively, in the previous quarter. The increase in consolidated grades were primarily due to the increased tonnage of higher grade material at San Dimas and La Encantada.', 'production-v2', 0.8, '2026-06-16T14:48:40.898426+00:00', '2026-07-01T23:04:36.978997+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-21-000592', '6-K', '2021-01-20', '2021-01-20', 2021, NULL, 'quarter', 'At the La Encantada Silver Mine', 'silver', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828021000592/ag-2021x01x20nrxex991.htm', 'A total of seven drill rigs, consisting of five surface rigs and two underground rigs, were active at the end of the quarter. | • | The Company is expecting to release an updated NI 43-101 Technical Report on Santa Elena by the end of the first quarter of 2021. | At the La Encantada Silver Mine: | • | During the quarter, La Encantada processed 248,408 tonnes of ore and produced 1,093,521 ounces of silver, or approximately 12% above the previous quarter and the highest quarterly production since Q2 2013. | • | Silver grades and recoveries during the quarter averaged 172 g/t and 80%, respectively. | • | Strong production from the San Javier and La Prieta caving areas contributed approximately 81% of the total silver production during the quarter. Caving production benefited from higher than expected grades and tonnage during the quarter. | • | The mill modernization project designed to improve processing efficiencies had some installation delays throughout 2020 due to the impacts caused by the COVID-19 pandemic. As a result, the project is expected to continue into 2021 with the installation of new scrubbers for the foundry, main gear replacement and new impellers for two thickener tanks, filter press upgrades and improvements to the electrical control room. | •', 'production-v2', 0.8, '2026-06-16T14:48:40.898426+00:00', '2026-06-17T12:00:27.685607+00:00');
