INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-21-009164', '6-K', '2021-05-06', '2021-03-31', 2021, 'Q1', 'quarter', 'Consolidated', 'silver', 30000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828021009164/ag-2021q1fsxex991.htm', 'Page 5 | NOTES TO CONDENSED INTERIM CONSOLIDATED FINANCIAL STATEMENTS | Condensed Interim Consolidated Financial Statements - Unaudited | (Tabular amounts are expressed in thousands of US dollars) | 1. NATURE OF OPERATIONS | First Majestic Silver Corp. (the “Company” or “First Majestic”) is in the business of silver production, development, exploration, and acquisition of mineral properties with a focus on silver and gold production in North America. The Company owns three producing mines: the San Dimas Silver/Gold Mine, the Santa Elena Silver/Gold Mine and the La Encantada Silver Mine, four mines in suspension: the San Martin Silver Mine, the Del Toro Silver Mine, the La Parrilla Silver Mine and the La Guitarra Silver/Gold Mine, and several exploration stage projects. The Company acquired the Jerritt Canyon Gold Mine in Nevada, USA on April 30, 2021. | First Majestic is incorporated in Canada with limited liability under the legislation of the Province of British Columbia and is publicly listed on the New York Stock Exchange under the symbol “AG”, on the Toronto Stock Exchange under the symbol “FR” and on the Frankfurt Stock Exchange under the symbol “FMV”. The Company’s head office and principal address is located at 925 West Georgia Street, Suite 1800, Vancouver, British Columbia, Canada, V6C 3L2. | 2. BASIS OF PRESENTATION | These condensed interim consolidated financial statements have been prepared in accordance with International Accounting Standard (“IAS”) 34, | “Interim Financial Reporting” | . These condensed interim consolidated financial statements should be read in conjunction with the Company’s audited consolidated financial statements as at and for the year ended December 31, 2020, as some disclosures from the annual consolidated financial statements have been condensed or omitted. | These condensed interim consolidated financial statements have been prepared on a historical cost basis except for certain items that are measured at fair value including', 'production-v2', 0.8, '2026-06-16T14:48:40.541573+00:00', '2026-07-01T23:04:30.330382+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-21-006855', '6-K', '2021-04-14', '2021-04-14', 2021, NULL, 'quarter', 'Consolidated', 'gold', 4540296.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828021006855/ag-2021x04x14nrxex991.htm', '23,873 | 32,202 | (26%) | 26,343 | (9%) | Gold ounces produced | 4,540,296 | 6,195,057 | (27%) | 5,477,492 | (17%) | QUARTERLY REVIEW | Total ore processed during the quarter at the Company''s mines amounted to 614,245 tonnes, representing a 2% decrease compared to the previous quarter. The decrease in tonnes processed was primarily due to a severe winter ice storm in the month of February which temporarily reduced plant throughput rates at La Encantada offset by improved underground ore deliveries and plant production rates at Santa Elena.', 'production-v2', 0.8, '2026-06-16T14:48:40.637260+00:00', '2026-07-01T23:04:31.292442+00:00');
