INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-21-011684', '6-K', '2021-11-26', '2021-06-30', 2021, 'Q2', 'quarter', 'Mineral Resource and Mineral Reserve Estimates', 'gold', 2013.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299321011684/exhibit99-1.htm', 'Mineral Resource and Mineral Reserve Estimates | Dawe (1928) reported that Jesus Maria Estrada and his brother were extracting gold from the historical Santa Elena mine in 1928. There is no indication of any further significant mining or exploration at Santa Elena until the 1960s when Industrias Peñoles S.A de C.V. drilled two or three holes on the property. No records are available for this drilling. | During the early 1980s, Tungsteno de Baviacora (Tungsteno) owned the property and mined 45,000 t grading 3.5 g/t Au and 60 g/t Ag from an open cut. This material was shipped for processing to the company''s flotation mill near Baviacora, approximately 30 km southwest of Santa Elena. Tungsteno periodically surface mined high silica/low fluorine material from Santa Elena and shipped it to the Grupo Mexico smelter in El Tajo near Nacozari, approximately 60 km to the northeast. In 2003, Tungsteno collected 117 surface and underground samples. There is limited documentation regarding this result of this sampling. | In 2003, Nevada Pacific Gold Inc. of Vancouver, BC completed a brief surface and underground sampling program with the collection of 119 samples. There is limited documentation regarding this result of this sampling. | In 2004, Fronteer Development Group of Vancouver, BC, completed a surface and underground mapping and sampling program. A total of 145 channel samples (89 underground and 56 surface) were collected and analyzed by ALS-Chemex of Hermosillo, Mexico. | The property remained under control of Tungsteno until 2009, when SilverCrest acquired 100% of the Santa Elena property. SilverCrest started production of gold and silver in July 2011 and by 2015 was producing gold and silver from a 3,000 tpd open pit, underground mine, and reprocessing of heap leaching material using a CCD/Merrill Crowe processing facility. Commercial production for the 3,000 tpd mill and plant facility was declared on August 1, 2014. Underground development has been ongoing since Jan', 'production-v2', 0.8, '2026-06-16T14:48:40.122236+00:00', '2026-06-17T12:00:26.351035+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-21-013765', '6-K', '2021-07-13', '2021-07-12', 2021, NULL, 'quarter', 'Consolidated', 'gold', 46545.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828021013765/ag-2021x07x13nrxex991.htm', '3,274,026 | 1,834,575 | 78% | 2,908,024 | 13% | Gold ounces produced | 46,545 | 15,764 | 195% | 23,873 | 95% | Total production - ounces of silver equivalent | 6,435,023', 'production-v2', 0.8, '2026-06-16T14:48:40.223095+00:00', '2026-07-01T23:04:28.071819+00:00');
