INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-22-000992', '6-K', '2022-01-18', '2021-12-31', 2021, 'FY', 'quarter', 'Consolidated', 'gold', 192353.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828022000992/ag-2022x01x18nrxex991.htm', '11,598,380 | 11% | 67,411 | 54,525 | 24% | Gold ounces produced | 192,353 | 100,081 | 92% | QUARTERLY REVIEW | Total ore processed during the quarter at the Company''s mines amounted to 955,810 tonnes, representing a 1% increase compared to the previous quarter. The slight increase in tonnes processed was primarily due to Jerritt Canyon processing higher volumes of lower grade surface material and underground ore partially offset by slightly lower throughput rates at San Dimas, Santa Elena and La Encantada. | Consolidated silver and gold grades in the quarter averaged 125 g/t and 2.42 g/t, respectively, compared to 122 g/t and 2.00 g/t, respectively, in the previous quarter. The increase in consolidated silver and gold grades were primarily due to processing higher grade ore within the Jessica vein at San Dimas and the introduction of Ermitaño’s ore into the Santa Elena plant in November. | Consolidated silver and gold recoveries averaged 88% and 91%, respectively, during the quarter. The Company continues to work towards optimizing the metallurgical recoveries of Ermitaño’s ore which achieved 61% for silver and 91% for gold during the fourth quarter. The Company plans to modify the Santa Elena processing plant to facilitate finer grinding and improve metallurgical recoveries with the commissioning of a new tailing filter-press, an additional leaching tank and a fourth CCD thickener in the fourth quarter of 2022.', 'production-v2', 0.8, '2026-06-16T14:48:39.918453+00:00', '2026-07-01T23:04:24.111727+00:00');
