INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001628280-23-001216', '6-K', '2023-01-19', '2023-01-19', 2023, NULL, 'quarter', 'At the Jerritt Canyon Gold Mine', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000162828023001216/ag-2023x01x19nrxex991.htm', '3 | first half of 2023 as higher-grade ore pods from the Smith Zone 10, West Generator and Saval II areas are processed at the mill. | • | During the quarter, an ore purchase agreement was signed with a third-party to provide up to 32,000 tonnes of sulphide gold ore by the end of 2023. Limited initial ore deliveries were received and processed in the month of December. Furthermore, improvements in blend optimization will result in a reduction in coal consumption in the roasters due to the higher sulphur content of the purchased material. | • | The Company completed the secondary escapeway in the West Generator mine in November which is now allowing for improved ore deliveries and gold production. This new ore feed, along with the start of the Saval II mine, is anticipated to increase gold grades and increase the amount of fresh ore feed to the plant in 2023. | • | During the quarter, two underground drill rigs completed 4,185 metres of drilling on the property. | At the Santa Elena Silver/Gold Mine: | • | Santa Elena produced 2,302,904 AgEq ounces consisting of 199,388 ounces of silver and 25,830 ounces of gold during the quarter, representing a 35% decrease in silver ounces and a 4% decrease in gold ounces when compared to the prior quarter. The decrease in silver production was primarily due to processing a higher percentage of ore from the Ermitaño mine with higher gold grades than the Santa Elena mine. | • | The mill processed a total of 207,188 tonnes of ore consisting of 41,953 tonnes (20% of total) from Santa Elena and 165,235 tonnes (80% of total) from Ermitaño.', 'production-v2', 0.8, '2026-06-16T14:48:39.526578+00:00', '2026-06-17T12:00:25.409253+00:00');
