INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-25-006602', '40-F', '2025-04-01', '2024-12-31', 2024, 'FY', 'annual', 'Consolidated', 'silver', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299325006602/exhibit99-1.htm', '") and La Cuesta applied for the original Los Gatos concession in 2005. | There are no records of historical Mineral Resource and Mineral Reserve estimates before the involvement of MPR and La Cuesta. A feasibility study (" | FS | ") was completed on Los Gatos in 2017 (Tetra Tech, 2017) and the project secured financing for construction, commissioning, and start up with first concentrate produced in the second half of 2019. | The Company holds a 70% interest in the Los Gatos Joint Venture that owns the Los Gatos Silver Mine following the acquisition of Gatos completed in January 2025. | Table 17 below depicts the Los Gatos Silver Mine production from 2019 through December 2024. | 49 | Table 17: Cerro Los Gatos Production History | PRODUCCION MCLG | 2019 | 2020 | 2021 | 2022', 'production-v2', 0.8, '2026-06-17T12:00:22.555277+00:00', '2026-06-17T12:00:22.555277+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-25-006602', '40-F', '2025-04-01', '2024-12-31', 2024, 'FY', 'annual', 'Material Mined from Areas Not In Reserves', 'silver', 4543931.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299325006602/exhibit99-1.htm', '73,456 | - | 677,057 | - | 750,513 | Silver Produced | Ounces | 4,543,931 | 1,514,364 | 2,342,502 | - | 8,400,797 | Gold Produced', 'production-v2', 0.8, '2026-06-17T12:00:22.555277+00:00', '2026-07-01T23:03:55.081730+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-25-006602', '40-F', '2025-04-01', '2024-12-31', 2024, 'FY', 'annual', 'Minera La Encantada', 'silver', 2014.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299325006602/exhibit99-1.htm', 'From November 2006 to June 2010, La Encantada operated a 1,000 tpd flotation plant. All production during this period from the flotation plant was in the form of a lead‐silver concentrate. In 2007, La Encantada commenced construction of a cyanidation plant with a capacity of 3,750 tpd, and in 2009 began producing precipitates and silver doré bars. Commercial production was achieved on April 1, 2010, and the flotation circuit was placed in care-and-maintenance in June 2010. During 2011, several modifications were made to the cyanidation plant increasing its capacity to 4,000 tpd. Since that time, the La Encantada operation has only produced doré bars. | During the period of 2010 to 2013, La Encantada reprocessed old tailings from the flotation circuit with approximately 1,000 tpd of ore feed from the underground mine for a combined throughput of 4,000 tpd. Starting in 2014, silver market economic conditions precluded the reprocessing of tailings, and only ore production from underground workings was fed to the mill and the cyanidation plant. In 2015, the plant was expanded to bring the crushing and grinding capacity to 3,000 tpd. | In 2017, La Encantada started the construction of a roasting facility with the objective of increasing recoveries when reprocessing tailings. In 2018, the main components of the roasting system were installed, and commissioning tests were started in the last quarter and continued into 2019. Observations from the commissioning tests revealed materials handling issues at the feed and discharge of the roasting system. Engineering work is in progress to analyze these issues to establish whether there is an option of processing tailings material economically. | 64 | Mine production tonnes and silver metal production since 2014 is summarised in Figure 5 below. | Figure 5: Mine and silver production since 2014 | Geological Setting, Mineralization and Deposit Types | La Encantada is in the Sierra Madre Oriental (SMO) fold and thrust belt where Jur', 'production-v2', 0.8, '2026-06-17T12:00:22.555277+00:00', '2026-06-17T12:00:22.555277+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-25-000536', '6-K', '2025-01-08', '2025-01-08', 2025, NULL, 'quarter', 'Consolidated', 'gold', 41761.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299325000536/exhibit99-1.htm', '1,967,574 | 20% | 39,506 | 46,585 | (15)% | Gold ounces produced | 41,761 | (5)% | Q4 2024 Mine-by-Mine Production Details: | Mine | Ore | Processed | Tonnes', 'production-v2', 0.8, '2026-06-16T14:48:38.217719+00:00', '2026-07-01T23:03:58.403066+00:00');
