INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-25-017379', '6-K', '2025-12-17', '2025-12-17', 2025, 'FY', 'quarter', 'Consolidated', 'silver', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299325017379/exhibit99-1.htm', 'within ten days of this news release. | The Transaction is conditional upon Sierra Madre completing a concurrent private placement financing raising at least CAD$40 million in gross proceeds, as well as customary conditions including the receipt by Sierra Madre of various approvals, namely acceptance by the TSXV, Mexican Antitrust approval as well as disinterested shareholder approval of Sierra Madre''s shareholders pursuant to Multilateral Instrument 61-101 | Protection of Minority Security Holders in Special Transactions | ("MI 61-101"). Sierra Madre has announced that it is undertaking an offering of up to CAD$50 million in subscription receipts, which it expects to be completed in January 2026. For further details regarding Sierra Madre''s financing, investors should refer to Sierra Madre''s news release dated December 17, 2025 announcing the Transaction. | Sierra Madre will seek shareholder approval for the Transaction at a meeting of its shareholders that it expects to hold by the end of April 2026. The Transaction will require approval of a simple majority of the votes cast at such shareholder meeting by shareholders of Sierra Madre present in person or represented by proxy excluding votes attached to Sierra Madre Shares held by First Majestic or any other persons required to be excluded under MI 61-101. | The Del Toro Silver Mine is a past producing silver, gold and lead operation that was placed under care and maintenance by First Majestic in January 2020. Sierra Madre is a precious metals company focused on the La Guitarra Silver Mine in the Temascaltepec mining district, Mexico, and the exploration and development of its Tepic property in Nayarit, Mexico. Sierra Madre acquired the La Guitarra mine from First Majestic in 2023 and commenced commercial production in January 2025. | ABOUT FIRST MAJESTIC | First Majestic is a publicly traded mining company focused on silver and gold production in Mexico and the United States. The Company presently owns and operat', 'production-v2', 0.8, '2026-06-16T14:48:37.313805+00:00', '2026-06-17T12:00:21.207670+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-26-001765', '40-F', '2026-03-31', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 3121.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299326001765/exhibit99-1.htm', '5,385,150 | 1,416,862 | 2,764,123 | - | 15,435,506 | Gold Produced | Ounces | 3,121 | 55,724 | 88,107 | 137 | 342 | 147,433', 'production-v2', 0.8, '2026-06-17T12:00:21.157812+00:00', '2026-07-01T23:22:54.738379+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-26-001765', '40-F', '2026-03-31', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'silver', 2025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299326001765/exhibit99-1.htm', 'The Los Gatos area has been the subject of very limited historical prospecting and mineral exploration. There are small prospect pits and minor historic workings in the Esther, San Luis, Tren/Margarita, and Paula zones. There is no known record keeping from this small-scale production. Los Gatos was initially recognized by reconnaissance activities by La Cuesta International Inc. (" | La Cuesta | ") and La Cuesta applied for the original Los Gatos concession in 2005. | There are no records of historical Mineral Resource and Mineral Reserve estimates before the involvement of MPR and La Cuesta. A feasibility study was completed on Los Gatos in 2017 (Tetra Tech, 2017) and the project secured financing for construction, commissioning, and start up with first concentrate produced in the second half of 2019. | The Company holds a 70% interest in the Los Gatos Joint Venture that owns the Los Gatos Silver Mine following the acquisition of Gatos completed in January 2025. | Figure 5 below shows the Los Gatos Silver Mine production from 2019 through to December 2025. | 52 | Figure 5: 2019 to 2025 Los Gatos District silver, lead and zinc production | 53 | Geological Setting, Mineralization and Deposit Types | The Los Gatos Silver Mine and Esther deposits are embedded within andesites of the Lower Volcanic Series (" | LVS | ") of the SM Occidental volcanic province. On the Los Gatos Joint Venture concessions, the LVS is exposed in a horst feature that stretches from the Los Gatos Silver Mine deposit approximately 25 km to the northwest to the edge of the concession package.', 'production-v2', 0.8, '2026-06-17T12:00:21.157812+00:00', '2026-06-17T12:15:10.524676+00:00');
