INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-26-001815', '6-K', '2026-04-02', '2026-04-02', 2026, NULL, 'quarter', 'Consolidated', 'silver', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299326001815/exhibit99-1.htm', ', and are also available of the Company''s website at | www.firstmajestic.com | . The technical information has been updated with more current information where appropriate. | Gonzalo Mercado, P.Geo., the Company''s Vice-President of Exploration & Technical Services, has reviewed and approved the scientific and technical information contained in this news release and has verified the underlying data. Mineral Resource estimates set out in this news release were prepared under the supervision of, or were reviewed by, David Rowe, CPG, the Company''s Director of Mineral Development. | ABOUT FIRST MAJESTIC | First Majestic is a publicly traded mining company focused on silver and gold production in Mexico and the United States. The Company presently owns and operates four producing underground mines in Mexico: the Santa Elena Silver/Gold Mine, the Los Gatos Silver Mine (the Company holds a 70% interest in the Los Gatos Joint Venture that owns and operates the mine), the San Dimas Silver/Gold Mine, and La Encantada Silver Mine, as well as a portfolio of development and exploration assets, including the Jerritt Canyon Gold Mine, which is an advanced-stage development asset that was placed on temporary suspension in March 2023. | 7 | First Majestic is proud to own and operate its own minting facility, First Mint, LLC, and to offer a portion of its silver production for sale to the public. Bars, ingots, coins, and medallions are available for purchase online at | www.firstmint.com | , at some of the lowest premiums available. | For further information, contact | info@firstmajestic.com | visit our website at', 'production-v2', 0.8, '2026-06-16T14:48:36.780361+00:00', '2026-06-17T12:00:20.747728+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-26-001902', '6-K', '2026-04-09', '2026-04-09', 2026, NULL, 'quarter', 'Consolidated', 'gold', 41417.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299326001902/exhibit99-1.htm', '4,165,334 | (15)% | 34,341 | 36,469 | (6)% | Gold ounces produced | 41,417 | (17)% | 15,407,856 | 12,492,869 | 23% | Zinc pounds produced | 14,238,927', 'production-v2', 0.8, '2026-06-16T14:48:36.766207+00:00', '2026-07-01T23:03:45.392538+00:00');
