INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-26-001902', '6-K', '2026-04-09', '2026-04-09', 2026, NULL, 'quarter', 'Standards of Disclosure for Mineral Projects', 'silver', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299326001902/exhibit99-1.htm', 'For further information regarding QA/QC and data verification procedures, key assumptions, parameters, and methods used to estimate Mineral Resources and Mineral Reserves, and a discussion of known risks that could materially affect the Company''s business and the potential development of Mineral Resources and Mineral Reserves, refer to the sections entitled "General Development of the Business - Material Mineral Properties" and "Risk Factors" in the 2025 AIF for the year ended December 31, 2025. | 6 | QUALIFIED PERSONS | Gonzalo Mercado, P.Geo., the Company''s Vice President of Exploration & Technical Services and a "Qualified Person" as defined under NI 43-101, has reviewed and approved the scientific and technical information contained in this news release and has verified the underlying data. First Majestic is authorized by The Association of Professional Engineers and Geoscientists of the Province of British Columbia to engage in Reserved Practice under Permit to Practice number 1005571. | ABOUT FIRST MAJESTIC | First Majestic is a publicly traded mining company focused on silver and gold production in Mexico and the United States. The Company presently owns and operates four producing underground mines in Mexico: the Santa Elena Silver/Gold Mine, the Los Gatos Silver Mine (the Company holds a 70% interest in the Los Gatos Joint Venture that owns and operates the mine), the San Dimas Silver/Gold Mine, and La Encantada Silver Mine, as well as a portfolio of development and exploration assets, including the Jerritt Canyon Gold Mine, which is an advanced-stage development asset that was placed on temporary suspension in March 2023. | First Majestic is proud to own and operate its own minting facility, First Mint, LLC, and to offer a portion of its silver production for sale to the public. Bars, ingots, coins and medallions are available for purchase online at | http://www.firstmint.com/ | , at some of the lowest premiums available. | For further information, contact', 'production-v2', 0.8, '2026-06-16T14:48:36.766207+00:00', '2026-06-17T12:00:20.725014+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AG', '0001308648', '0001062993-26-002215', '6-K', '2026-04-30', '2026-04-29', 2026, NULL, 'quarter', 'Consolidated', 'silver', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1308648/000106299326002215/exhibit99-1.htm', '. Please review the Meeting Materials for instructions relating to voting your First Majestic shares. | The Company looks forward to the support of its shareholders at the 2026 AGM, and notes that management recommends that shareholders vote " | FOR | " all resolutions that are set out in the Meeting Materials. | ABOUT FIRST MAJESTIC | First Majestic is a publicly traded mining company focused on silver and gold production in Mexico and the United States. The Company presently owns and operates four producing underground mines in Mexico: the Santa Elena Silver/Gold Mine, the Los Gatos Silver Mine (the Company holds a 70% interest in the Los Gatos Joint Venture that owns and operates the mine), the San Dimas Silver/Gold Mine, and La Encantada Silver Mine, as well as a portfolio of development and exploration assets, including the Jerritt Canyon Gold Mine, which is an advanced-stage development asset that was placed on temporary suspension in March 2023. | First Majestic is proud to own and operate its own minting facility, First Mint, LLC, and to offer a portion of its silver production for sale to the public. Bars, ingots, coins and medallions are available for purchase online at | http://www.firstmint.com | , at some of the lowest premiums available. | For further information, contact | info@firstmajestic.com | , visit our website at | www.firstmajestic.com', 'production-v2', 0.8, '2026-06-16T14:48:36.565507+00:00', '2026-06-17T12:00:20.354247+00:00');
