INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AGI', '0001178819', '0001052918-03-000149', '20-F', '2003-06-30', '2002-12-31', 2002, 'FY', 'annual', 'Consolidated', 'gold', 1994.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1178819/000105291803000149/alamos20fdec2002sec.htm', 'Director | Sharon Fleming | 52 | Secretary | Chester F. Millar | is a Professional Engineer and served as Chairman and a Director of Alamos Minerals from 1996 to the date of formation of the Company. He also served as President of Alamos Minerals from 1999 to the date of formation of the Company. Mr. Millar is a pioneer of bulk heap leaching gold production and the concept of large-scale bulk mining of low-grade deposits in the Western United States. Under his guidance, Afton Mines (1968-1973), Glamis Gold Ltd. (“Glamis”) and Eldorado Gold Corporation (“Eldorado”) grew from small producing operations to substantial mining companies. Mr. Millar served as Chairman of Glamis from 1985 to 1998 and Chairman of Eldorado between 1992 and 1994. | John A. McCluskey, | a self-employed investor relations consultant, served as a Director of Alamos Minerals from May 1996 to the date of formation of the Company. Mr. McCluskey has a 20 year history in mining finance and management. He has served as the President and Chief Executive Officer of Grayd Resource Corporation since 1996, as a Director of Aurcana Corporation since July, 2002 and as Vice-President of Inca Pacific Resources Inc. from 1996 to 2002. He has also worked with Miramar Mining Corporation | and Boron Chemical International Ltd. (now Atacama Minerals Corp.). | Stephen R. Stine | , an experienced mine operator, served as a Director of Alamos Minerals from February 2002 to the date of formation of the Company. He has 31 years experience in management, engineering, development and operations with mining companies. He was involved with the development of the following mines: Bismark (Mexico), Cuajone (Peru), Rio Chiquito (Costa Rica) and Twin Buttes (Arizona). He was previously the President & C.E.O. of Laguna Gold Company from 1998 to 2000; Vice-President, First Dynasty Mines, Ltd. from 1994 to 1998; and General Manager of FMC Gold Company from 1991 to 1994. | James M. McDonald | , a Professional Geologist, served as P', 'production-v2', 0.8, '2026-06-01T22:34:05.403335+00:00', '2026-06-01T22:34:05.403335+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AGI', '0001178819', '0001052918-03-000101', '6-K', '2003-05-12', '2003-05-01', 2003, NULL, 'quarter', 'Consolidated', 'gold', 1993.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1178819/000105291803000101/alamosgold6kapr2003.htm', '--------------------------------------------------------- | 1 The Behre Dolbear report, which examines this study, is available on SEDAR. Go to | http://www.sedar.com/command_servlet?cmd=DisplayCompanyDocuments&issuerNo=00005505&lang=EN | and click on the item with the July 4, 2002 date named". | An exploration plan is being designed to systematically test the entire land package over a number of years. While the various exploration targets that are already defined will be prioritized in coming months, the natural starting point for exploration work this year is in the Mulatos Deposit area. Potential exists to define additional resources both within and external to the existing reserve base. This can potentially benefit the feasibility program underway. The exploration work that will be undertaken this year will be detailed in a future news release. | The Company has a seasoned management team lead by Chester F. Millar, a pioneer in the extraction of gold through open pit heap leach methods, and the founder of Glamis Gold Ltd. and Eldorado Gold Corporation. Mulatos will mark Mr. Millar’s second gold mine start-up in the State of Sonora, following La Colorada, which he developed to profitable production in 1993. | The Company is listed on the Canadian Venture Exchange under the symbol AGI. The Company has working capital of $1.7 million and long-term debt of $5.7 million. During the first quarter of this year the Company has seen 4.1 million warrants exercised resulting in an additional $2.1 million in working capital for the Company. AGI owns 100% of the Salamandra property, which it acquired for $8.7 million under an asset purchase agreement completed in February 2003. | ON BEHALF OF THR BOARD OF DIRECTORS | ALAMOS GOLD INC. | “Chester F. Millar” | Chairman and President | For information, contact: | John A. McCluskey', 'production-v2', 0.8, '2026-07-01T23:10:04.760017+00:00', '2026-07-01T23:10:04.760017+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AGI', '0001178819', '0001178819-25-000031', '40-F', '2025-03-31', '2024-12-31', 2024, 'FY', 'annual', 'Consolidated', 'gold', 185100.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1178819/000117881925000031/ex9912024annualinformation.htm', 'Capital and Operating Costs | Actual results for 2023 and 2024 and guidance for 2025 production, operating costs, and capital are depicted below. | 2023 Actual | 2024 Actual | 2025 Guidance | Gold Production | (ounces) | 185,100 | 174,000 | 175,000 - 190,000 | Total Cash Costs | (1) | ($/ounce)', 'production-v2', 0.8, '2026-06-17T12:00:30.323551+00:00', '2026-07-01T23:07:25.161512+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AGI', '0001178819', '0001178819-25-000031', '40-F', '2025-03-31', '2024-12-31', 2024, 'FY', 'annual', 'Island Gold District', 'gold', 2023.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1178819/000117881925000031/ex9912024annualinformation.htm', '”). Together with the Island Gold Mine, the Magino Mine forms the Company’s “ | Island Gold District | ”. | Property Description, Location and Access | In 2017, Argonaut conducted a feasibility study evaluating | conventional open-pit mining and gold extraction via a 10,000 tonnes per day carbon-in-pulp mineral processing facility. Following additional studies from 2018 through 2020, Argonaut advanced the project towards construction in October 2020. Development began in early 2021, with construction completed in the first half of 2023. Commercial production was declared effective as of November 1, 2023. | The Magino Mine is located near Dubreuilville, Ontario, approximately 10 km southwest of town. | It is accessible via an all-weather road from Highway 519, west of Dubreuilville, and about 35 km east of Highways 17 and 519 junction. | The Company owns and/or holds 100% of the mineral rights to all the Mineral Resource and Mineral Reserve at the Magino Mine. It also holds full title and/or interest to the Magino Mine and its surrounding project lands (collectively, the “ | Magino Property | ”). The Magino Property is divided into eleven (11) property areas, namely: Aguonie, Dog Lake, Doherty, Highland South, Magino Mine, Magino – Goudreau, Magino – Kremzar, Mountain Lake, Murphy, Rand2 and Selkirk Lake, consisting of | 47 | Alamos Gold Inc. | patented fee simple and/or patented Crown leasehold mining rights and surface rights claims, and unpatented cell claims covering approximately 4,735 hectares, with approximately 2,219 hectares supporting the Magino Mine area.', 'production-v2', 0.8, '2026-06-17T12:00:30.323551+00:00', '2026-06-17T12:00:30.323551+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AGI', '0001178819', '0001178819-25-000031', '40-F', '2025-03-31', '2024-12-31', 2024, 'FY', 'annual', 'for the Island Gold District, incorporating Magino.', 'gold', 33000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1178819/000117881925000031/ex9912024annualinformation.htm', 'Capital and Operating Costs | The Magino Mine was acquired by the Company on July 12, 2024. Actual results for 2024 operating costs, and capital are summarized below and reflects the Company’s ownership period starting July 12, 2024. For guidance for 2025 production please refer to the Island Gold Capital and Operating Costs on page | 46 | for the Island Gold District, incorporating Magino. | 2024 Actual | Gold Production | (ounces) | 33,000 | Total Cash Costs | (1) | ($/ounce) | 1,836 | Mine Site All-in Sustaining Costs', 'production-v2', 0.8, '2026-06-17T12:00:30.323551+00:00', '2026-07-01T23:07:25.161512+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AGI', '0001178819', '0001178819-25-000031', '40-F', '2025-03-31', '2024-12-31', 2024, 'FY', 'annual', '”) by Mexico’s Secretariat of Environment and Natural Resources (“', 'gold', 212800.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1178819/000117881925000031/ex9912024annualinformation.htm', 'Capital and Operating Costs | Actual results for 2023 and 2024, and guidance for 2025 production, operating costs, and capital are depicted below. | 2023 Actual | 2024 Actual | 2025 Guidance | Gold Production | (1) | (ounces) | 212,800 | 205,000 | 130,000 - 140,000 | Total Cash Costs | (2)', 'production-v2', 0.8, '2026-06-17T12:00:30.323551+00:00', '2026-07-01T23:07:25.161512+00:00');
