INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ARIS', '0001964504', '0001964504-26-000012', '40-F', '2026-03-11', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 256503.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1964504/000196450426000012/arismining-mdaq42025.htm', 'Net debt | was | reduced to $86 million, down from $241 million at year-end 2024. | 2025 Operational Highlights | • | Gold production | totaled 256,503 ounces in 2025, exceeding the annual guidance midpoint (230,000-275,000 ounces), and representing a 22% increase from the 210,955 ounces produced in 2024. | • | Segovia | ◦ | Produced | 227,762 ounces in 2025, driven by average gold grades of 9.82g/t, gold recoveries of 96.1%, and a 17% increase in tonnes milled compared to 2024, driven by the installation of a second ball mill in June 2025. | ◦', 'production-v2', 0.8, '2026-06-17T12:47:20.952194+00:00', '2026-07-01T23:22:57.579562+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ARIS', '0001964504', '0001964504-26-000021', '6-K', '2026-05-06', '2026-03-31', 2026, 'Q1', 'quarter', 'Consolidated', 'gold', 74339.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1964504/000196450426000021/arismining-mdaq12026.htm', 'was | reduced to $1.6 million, down from $86 million at year-end 2025. | Q1 2026 | Operational Highlights | • | Gold production | totaled 74,339 ounces, representing a 6% increase from the 69,852 ounces produced in Q4 2025. | • | Segovia | ◦ | Produced | 66,567 ounces in Q1 2026, a 5% increase over Q4 2025, reflecting the processing of 175,370 tonnes at an average gold grade of 12.41 g/t, compared to 201,060 tonnes at 10.10 g/t in Q4 2025. Gold recoveries were 95.3%, compared to 96.1% in Q4 2025. | ◦', 'production-v2', 0.8, '2026-07-01T23:10:09.598753+00:00', '2026-07-01T23:10:09.598753+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ASM', '0000316888', '0001477932-10-000380', '20-F', '2010-07-15', '2009-12-31', 2009, 'FY', 'annual', 'Consolidated', 'gold', 1987.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/316888/000147793210000380/avino_20f.htm', 'kilometers east of Goldbridge in the Bridge River gold district of British Columbia and adjoins the Olympic-Kelvin Property. The property covers approximately 204 hectares. The claims occupy the lake bed and north side of Carpenter Lake. Access from Goldbridge is made via an all-weather gravel road which skirts the north shore of Carpenter Lake. | Gold Bridge can be reached from Vancouver via Hope and Lillooet, a distance of 445 kilometers, or via Pemberton using the four-wheel-drive Hurley Pass route, a distance of 225 km. | The terrain is rugged, typical of the eastern margin of the Coast Range Mountains. The claim group ranges in elevation from 650 meters on Carpenter Lake to a maximum of 1020 meters. | The climate of the Bridge River District is transitional between humid coastal belt and more arid interior plateau. Annual precipitation is modest with a significant proportion falling as snow in the winter. Summers tend to be warm to hot depending on the altitude, and winters are moderately cold. | History. | The claim group has been explored intermittently for over sixty years and several gold-bearing structures are known on the property. Production from the Minto mine between 1934 and 1940 amounted to 88,900 tons of ore returning 17,558 ounces of gold and 50,582 ounces of silver. During 1985, geological, geochemical, and geophysical (VLF-EM) surveys were conducted and trenches were excavated in anomalous areas. In-fill soil geochemistry and further trenching were undertaken in 1987. | A mechanized trenching program was carried out on the Minto Property in June, 2005 to test the Minto North and Jumper Zones. Seven trenches were excavated, sampled, mapped and reclaimed, usually in a one day period. Chip samples from all the trenches returned values from anomalous to economic levels in gold. | In December 2006, the Company announced the results of the 2006 drilling program on the Minto Property. The four diamond core holes were drilled to explore down dip extensio', 'production-v2', 0.8, '2026-07-01T23:13:44.106047+00:00', '2026-07-01T23:13:44.106047+00:00');
