INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ATCX', '0001684688', '0001493152-22-011483', '20-F', '2022-04-29', '2021-12-31', 2021, 'FY', 'annual', 'Consolidated', 'gold', 1950.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1684688/000149315222011483/form20-f.htm', 'has quadrupled and gold markets have flourished across the globe. Currently the global gold market has attracted a lot of attention and | the price of gold is relatively higher than its historical trend. Gold is now bought by a far more diverse set of consumers and investors | than at any previous time in history. In 2016, 3,100 tons were produced worldwide, with the main producing countries being: China, 455 | t (largest producer in the last 10 years); Australia, 270 t; Russia, 250 t; United States of America, 209 t; Canada, 170 t; Peru, 150 | t; South Africa, 140 t; Mexico, 125 t; Indonesia, 100 t; Uzbekistan, 100 t; Ghana, 90 t; and Brazil, 80 t (USGS 2017). An estimated 187,200 | t of gold has been produced throughout history, with two-thirds since 1950. | Gold’s | diverse uses, in jewelry, technology and by central banks and investors, mean different sectors of the gold market rise to prominence | at different points in the global economic cycle. This diversity of demand and self-balancing nature of the gold market underpin gold’s | robust qualities as an investment asset. The price of gold, as each price, is determined by the market forces of demand and supply. The | demand is the amount of a good demanded for purchase at a given price. Therefore, the demand for gold is the amount of a gold demanded | for purchase at a given price. Gold demand is often analyzed on an annual basis and divided into jewelry demand, technology demand, central | banks’ demand or investment demand.', 'production-v2', 0.8, '2026-07-01T23:14:44.575710+00:00', '2026-07-01T23:14:44.575710+00:00');
