INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AU', '0001973832', '0001973832-26-000066', '20-F', '2026-03-26', '2025-12-31', 2025, 'FY', 'annual', 'Australia', 'gold', 2024.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1973832/000197383226000066/au-20251231.htm', '3% | “N/M” - Not meaningful | (1) | On an attributable basis. Tropicana is owned 70% by AngloGold Ashanti. | Australia | In the Australia region, gold production (on an attributable basis) decreased 6% year-on-year in 2025 compared to 2024. | Revenue from product sales from the Australia operations increased by $483 million, or 35%, from $1,399 million in 2024 to | $1,882 million in 2025, mainly as a result of an increase in gold income. Gold income increased 35% year-on-year in 2025 | compared to 2024, mainly due to an increase in the average gold price received per ounce, partially offset by lower ounces of | gold sold. The increase in the average gold price received of $1,073 per ounce from 2024 to 2025 resulted in an increase in gold | income of $575 million. Gold sold decreased 7% year-on-year in 2025 compared to 2024, which resulted in a decrease in gold | income of $93 million. By-product revenue increased $1 million from $5 million in 2024 to $6 million in 2025. | Cost of sales increased 7% year-on-year in 2025 compared to 2024, mainly due to an increase in total operating costs partially', 'production-v2', 0.8500000000000001, '2026-06-01T22:34:15.879644+00:00', '2026-06-17T12:15:02.026963+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AU', '0001973832', '0001973832-26-000066', '20-F', '2026-03-26', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 2690000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1973832/000197383226000066/au-20251231.htm', 'in a net $71 million loss recorded in 2024. All gold hedges expired at 31 December 2024 and the Company has been fully | unhedged with respect to its gold production since 1 January 2025. | Gold production levels | In addition to gold prices, AngloGold Ashanti’s gold income in any year is also influenced by its level of gold production. Gold | production levels are in turn influenced by grades, tonnages mined and processed through the plant, and metallurgical | recoveries. Attributable gold production (including non-managed joint ventures) fluctuated between 2023 to 2025, from 2.69 | million ounces (of which 42,000 ounces from CdS) in 2023 to 2.66 million ounces in 2024 to | 3.09 | million ounces in 2025. For | more information on the Company’s business and operations, see | “Item 4 | B: Business Overview” | .', 'production-v2', 0.8500000000000001, '2026-06-11T02:57:34.447569+00:00', '2026-07-01T23:23:06.168443+00:00');
