INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('AUGO', '0001468642', '0001171843-26-002127', '20-F', '2026-04-01', '2025-12-31', 2025, 'FY', 'annual', 'Aura Minerals Inc.', 'gold', 2025000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1468642/000117184326002127/f20f_033126.htm', 'Notes to the Consolidated Financial Statements | For the years ended December 31, 2025, 2024 and 2023 | Expressed in thousands of United States dollars, except where otherwise noted. | ii) Derivative Options | ii) a - Derivative Collars – Almas and Apoena | As of December 31, 2025, the Company did not have any outstanding zero-cost put/call collar contracts related to gold production. As of December 31, 2024, the Company had outstanding zero-cost put/call collar arrangements covering gold production at the Almas Project and Apoena Mines. All such contracts expired during 2025. | ii) b – Derivative Collars Borborema Project | As of December 31, 2025, the Company had 198,561 ounces outstanding for the Borborema Project. The put/calls collars have floor prices of $1,745 and ceiling prices at $2,400 per ounce of gold expiring between January 2025 and June 2028. | The fair value effect of both the Derivative Collars - Apoena and the Derivative Collars Borborema Project for the year ended December 31, 2025 is ($281,489) (($80,241) in December 31, 2024 and ($25,683) as of December 31, 2023), recorded as a finance expenses loss in the financial statements. | As of the date of this Consolidated Financial Statements, the Company have no agreements in place with financial institutions which would require the Company to post cash or any other type of collateral to cover fair value exposure against the Company. | b) Fair value of financial instruments | The Company measures certain of its financials assets and liabilities at fair value on a recurring basis and these are classified in their entirety based on the lowest level of input that is significant to the fair value measurement. There are three levels of the fair value hierarchy that prioritize the inputs to valuation techniques used to measure fair value: | 1)', 'production-v2', 0.8, '2026-06-11T02:57:35.908135+00:00', '2026-06-17T12:15:21.072372+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('B', '0000756894', '0001193125-26-079253', '40-F', '2026-02-27', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 2030000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/756894/000119312526079253/d833573dex991.htm', 'As at December 31, 2025, the recorded amount of estimated future | reclamation and closure costs that were recorded under IFRS, as defined by IAS 37, and that have been updated each reporting period, was $25.8 million (Barrick’s 45% attributable share was $11.6 million) (as described in Note 2r to the | Consolidated Financial Statements). | Exploration and Drilling | The strategic focus of exploration at Kibali is to prioritize near surface opportunities close to the plant, particularly with | down-plunge extension drilling at depth, thereby increasing years of production (with complementary underground and open pit sources) and maintaining a gold production profile target of 700 thousand ounces beyond 2030. | During 2025, new indicated mineral resources were added at KCD, Gorumbwa and most importantly at the ARK deposits. The majority of | drilling for resource and reserves was focused on the ARK system to better define the extents of mineralization. Exploration drilling also advanced the understanding of potential satellite and system extensions at KZ North and KZ South, while | sterilization drilling was conducted around Megi-Marakeke-Sayi, | Mandungu-Memekazi-Renzi | and the ARK area. A total of 135,701 meters of diamond drill core in 834 holes and 158,013 meters of RC in 2,733 holes | were drilled from surface exploration and grade control drilling programs in 2025. | - 88 -', 'production-v2', 0.8, '2026-06-17T12:00:45.968674+00:00', '2026-06-17T12:14:58.083590+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('B', '0000756894', '0001193125-26-079258', '6-K', '2026-02-27', '2026-02-27', 2026, NULL, 'quarter', 'Consolidated', 'gold', 2030000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/756894/000119312526079258/d85391dex991.htm', 'drop in grade is due to mining depletion of higher grade from underground and lowering the | cut-off | grade due to an increase in the gold price from US$1,900/oz to US$2,000/oz. | ● | The strategic focus of exploration at Kibali is to prioritise near surface opportunities close to the processing plant | and down-plunge extensions to existing deposits. The objective is to increase years of production with complementary underground and open pit sources to meet a gold production profile target of 700 koz beyond 2030. | ● | In 2025, SLR USA Advisory Inc. (SLR) completed a site visit and independent review of the Mineral Resource and its | informing data and processes. SLR concluded that the processes underlying the generation and declaration of the Mineral Resource are appropriate and consistent with industry best practice. | 1.13.2 | Mining and Mineral Reserves | ● | Barrick, as the owner operator of the Project, has significant experience in other mining operations within Africa and', 'production-v2', 0.8, '2026-06-16T14:48:47.589962+00:00', '2026-06-17T12:00:45.192452+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('B', '0000756894', '0001193125-26-079268', '6-K', '2026-02-27', '2026-02-27', 2026, NULL, 'quarter', 'The Pueblo Viejo mine achieved first in', 'gold', 2012.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/756894/000119312526079268/d134256dex991.htm', 'Barrick | In March 2006, Barrick acquired Placer Dome Inc. and, in May 2006, amalgamated the companies. At the same time, Barrick sold a 40% stake in Pueblo Viejo | to Goldcorp Inc. (Goldcorp Inc. was subsequently acquired by Newmont in 2019). On 26 February 2008, PV delivered the Project Notice to the Government of the Dominican Republic pursuant to the SLA and delivered the Pueblo Viejo Feasibility Study | to the Government. In 2009, the Dominican Republic and PV agreed to amend the terms of the SLA. The amendment became effective on 12 November 2009, following its ratification by the Dominican National Congress. A second amendment to the SLA | became effective on October 5, 2013, and has resulted in additional and accelerated tax revenues to the government of the Dominican Republic. | The Pueblo Viejo mine achieved first gold production in 2012. | 6.9 | Past Production | In August 2010, the open pit | pre-stripping | started. The ore mined from 2010 to 2025 totalled 205 Mt | averaging 3.0 g/t Au. Ore processed during this period totalled 108 Mt at 3.7 g/t Au with an average | February 27, 2026', 'production-v2', 0.8, '2026-06-16T14:48:47.744197+00:00', '2026-06-17T12:00:45.445484+00:00');
