INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('BTG', '0001429937', '0001104659-26-050245', '6-K', '2026-04-28', '2026-04-13', 2026, NULL, 'quarter', 'commence underground operations, including stope ore', 'gold', 15000000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1429937/000110465926050245/tm265010d3_ex99-1.htm', 'production profile. In July 2025, the State of Mali granted | the Underground Mining Approval for the Company to | commence underground operations, including stope ore | production at the Fekola Mine—where we also celebrated | a significant milestone in 2025 with 4 million ounces of | gold produced since inception. On September 15, 2025, | we announced the approval of a development decision | on the Antelope underground deposit at the Otjikoto Mine, | which is expected to be a low-cost underground operation | to supplement production and extend Otjikoto’s life into | the next decade. Our most significant growth milestone | in 2025 was the achievement of commercial production | at the Goose Mine in early October 2025. As a Canadian', 'production-v2', 0.8, '2026-06-16T14:48:48.664329+00:00', '2026-06-17T12:00:46.809804+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('BTG', '0001429937', '0001171843-26-003084', '6-K', '2026-05-07', '2026-05-06', 2026, NULL, 'quarter', 'Consolidated', 'gold', 1005.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1429937/000117184326003084/exh_991.htm', 'VANCOUVER, British Columbia, May 06, 2026 (GLOBE NEWSWIRE) -- B2Gold Corp. (TSX: BTO, NYSE AMERICAN: BTG, NSX: B2G) (“B2Gold” or the “Company”) is pleased to announce its operational and financial results for the first quarter of 2026. All dollar figures are in United States dollars unless otherwise indicated. | 2026 First Quarter Highlights | Gold production of 237,763 ounces | : Total gold production in the first quarter of 2026 was 237,763 ounces. All operations exceeded expected production in the first quarter. | Consolidated cash operating costs of | $1,005 | per gold ounce produced | : Consolidated cash operating costs (see “ | Non-IFRS Measures', 'production-v2', 0.65, '2026-06-16T14:48:48.547142+00:00', '2026-07-01T23:23:14.989566+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('BTG', '0001429937', '0001171843-26-003084', '6-K', '2026-05-07', '2026-05-06', 2026, NULL, 'quarter', 'Consolidated operations results', 'gold', 1005.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1429937/000117184326003084/exh_991.htm', '(2) | ($/ gold ounce sold) | 846 | 880 | Cash operating costs | (2) | ($/ gold ounce produced) | 1,005 | 832', 'production-v2', 0.65, '2026-06-16T14:48:48.547142+00:00', '2026-07-01T23:23:14.989566+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('BTG', '0001429937', '0001171843-26-003084', '6-K', '2026-05-07', '2026-05-06', 2026, NULL, 'quarter', 'The Goose Mine''s cash operating costs (refer to “', 'gold', 1446.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1429937/000117184326003084/exh_991.htm', '(1) Non-IFRS measure. For a description of how these measures are calculated and a reconciliation of these measures to the most directly comparable measures specified, defined or determined under IFRS and presented in the Company’s financial statements, refer to “Non-IFRS Measures”. | The Back River Gold District consists of eleven mineral claims blocks along an 80 km belt and contains the most advanced asset in the district, the 100% owned Goose Mine. | B2Gold acknowledges our partner the Kitikmeot Inuit Association (“KIA”), who has played a critical role for many years to ensure the development of a successful gold mining operation at the Goose Mine. Respect and collaboration with the KIA is central to the license to operate in the Back River Gold District and the Company will continue to prioritize developing the district in a manner that recognizes Inuit priorities, addresses concerns and brings long-term socio-economic benefits to the Kitikmeot Region. B2Gold looks forward to continuing to build on its strong collaboration with the KIA and Kitikmeot communities. With its significant gold resource endowment, the Back River Gold District is expected to be a large, long life mining complex. | For the first quarter of 2026, production from the Goose Mine was 42,876 ounces of gold, higher than expected. Gold production in the first quarter of 2026 was higher than anticipated as higher grade and gold recovery more than offset the lower throughput. For the first quarter of 2026, mill feed grade was 7.92 g/t, mill throughput was 0.18 million tonnes, and gold recovery averaged 93.5%. | The Goose Mine''s cash operating costs (refer to “ | Non-IFRS Measures | ”) for the first quarter of 2026 were $1,653 per gold ounce produced ($1,446 per gold ounce sold), lower than expected. Cash operating costs per ounce produced for the first quarter of 2026 were lower than anticipated due to lower than planned underground mining and site general costs. | All-in sustaining costs (refer', 'production-v2', 0.65, '2026-06-16T14:48:48.547142+00:00', '2026-07-01T23:23:14.989566+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('CDE', '0000215466', '0000215466-14-000083', '10-Q', '2014-08-06', '2014-06-30', 2014, 'Q2', 'quarter', 'Consolidated', 'gold', 61025.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/215466/000021546614000083/cde-06301410q.htm', 'Silver ounces produced | (2) | 4,465,387 | 4,612,455 | 8,538,159 | 8,427,320 | Gold ounces produced | (2) | 61,025', '10q-production-v1', 0.65, '2026-05-17T13:57:51.283282+00:00', '2026-05-17T13:57:51.283282+00:00');
