INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('CGAU', '0001854640', '0001171843-26-002836', '6-K', '2026-04-29', '2026-04-29', 2026, NULL, 'quarter', 'Consolidated', 'gold', 2026.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1854640/000117184326002836/exh_991.htm', 'Öksüt | Öksüt produced 38,429 ounces of gold in the first quarter of 2026, higher than planned due to higher than expected grades. During the quarter, mining activities were focused on phase 5 and phase 6 of the Keltepe pit. A total of 3.1 million tonnes of ore and waste were mined in the quarter and 1.0 million tonnes were stacked at an average grade of 1.23 g/t. Full year 2026 production guidance at Öksüt remains in the range of 110,000 to 125,000 ounces, with production in the remaining quarters of 2026 expected to be more evenly weighted and lower than first quarter production. | At Öksüt, gold production costs and AISC on a by-product basis | NG | for the first quarter 2026 were $1,547 per ounce and $1,653 per ounce, respectively. AISC on a by-product basis | NG | was lower compared to last quarter driven by higher gold ounces produced and sold, and lower sustaining capital expenditures | NG | , partially offset by higher royalty expense per ounce due to higher gold prices.', 'production-v2', 0.65, '2026-06-16T14:48:49.506751+00:00', '2026-06-17T12:00:49.968149+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('CTGO', '0001502377', '0001193125-26-107141', '10-K', '2026-03-16', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 142700.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1502377/000119312526107141/ctgo-20251231.htm', 'oz/t | Gold recovery (%) | 93.00 | 88.00 | % | Gold production | 142,700 | 261,500 | oz | Silver production | 185,800 | 288,000 | oz', 'production-v2', 0.7, '2026-06-01T22:34:30.995935+00:00', '2026-07-01T23:23:24.061530+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('CTGO', '0001502377', '0001193125-26-107141', '10-K', '2026-03-16', '2025-12-31', 2025, 'FY', 'annual', 'Lucky Shot Project', 'gold', 2027.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1502377/000119312526107141/ctgo-20251231.htm', '• | All-in sustaining Costs (“AISC”) estimated at $860 per GEO sold | • | Non-discounted payback period 1.3 years | Lucky Shot Project | In November 2025, the Company mobilized a drill rig at the Lucky Shot mine site to commence the first phase of a 15,000-meter underground in-fill drilling program. The Company started reporting assay results in the first quarter of 2026. This work, along with detailed engineering, hydrology and geotechnical work will form the basis for a feasibility level mine and transportation plan for Lucky Shot, with an objective of targeting to produce 40,000 to 50,000 ounces of gold per year using the Direct Shipping Ore (DSO) approach, assuming positive exploration success. The Company expects to complete the feasibility study in the first half of 2027 and make a production decision in 2027. | Underwritten Offering | On September 25, 2025, the Company sold 1,975,000 shares of common stock and pre-funded warrants to purchase up to 525,000 shares of common stock at an offering price of $20.00 per share and $19.99 per pre-funded warrant and received gross proceeds of $50.0 million before deducting underwriting discounts and offering expenses of $3.0 million. The offering price of the pre-funded warrant equaled the public offering price per share of the common stock less the $0.01 per share exercise price of each pre-funded warrant. The September offering was made pursuant to the Company’s effective shelf registration statement on Form S-3. | On February 12, 2026, the Company entered into an underwriting agreement with Canaccord Genuity LLC as representative of the several underwriters named therein, relating to an underwritten public offering to two institutional investors of (i) 1,678,206 shares of the Company’s common stock, $0.01 par value, at a public offering price of $24.96 per share and (ii) a pre-funded warrant to purchase up to 325,000 shares of the Company’s common stock at a purchase price of $24.95 per share with an exercise price o', 'production-v2', 0.7, '2026-06-01T22:34:30.995935+00:00', '2026-06-01T22:34:30.995935+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('CTGO', '0001502377', '0001193125-26-107141', '10-K', '2026-03-16', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'silver', 185800.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1502377/000119312526107141/ctgo-20251231.htm', '% | Gold production | 142,700 | 261,500 | oz | Silver production | 185,800 | 288,000 | oz | Contango’s Share (on a 30% basis) | 1 | Gold oz production guidance | 40,000 to 45,000', 'production-v2', 0.7, '2026-06-01T22:34:30.995935+00:00', '2026-07-01T23:23:24.061530+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('CTGO', '0001502377', '0001193125-26-222855', '10-Q', '2026-05-14', '2026-03-31', 2026, 'Q1', 'quarter', 'Johnson Tract Project', 'gold', 2027.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1502377/000119312526222855/ctgo-20260331.htm', 'During the first quarter of 2026, the Peak Gold JV (on a 100% basis) processed 187,479 tons of ore with an average grade of 0.125 ounces (“oz”) per ton and containing approximately 23,435 oz of gold. Gold recovery averaged 88.5%, resulting in approximately 20,600 oz of recovered gold, of which Contango’s 30% share amounted to 6,187 oz of gold. During the first quarter of 2026, a total of 8,012 oz of gold and 15,042 oz of silver were delivered to Contango and sold. | Johnson Tract Project | During the first quarter of 2026, activities at the Johnson Tract Project focused on planning, resourcing, permitting coordination, and logistical preparations in support of the Company’s planned 2026 field program. On December 1, 2025, the Johnson Tract Critical Metals Project was posted to the Federal Permitting Dashboard as a covered project under Title 41 of the Fixing America’s Surface Transportation Act, commonly referred to as FAST-41. The Federal Permitting Improvement Steering Council announced the project’s FAST-41 coverage on December 2, 2025. The U.S. Army Corps of Engineers ("Corps") is identified as the lead federal permitting agency for the project. | During the first quarter of 2026, the Company advanced planning activities for the proposed 2026 field season, including solicitation and review of bids for road construction and helicopter support associated with planned access improvements between the Johnson Tract camp and the proposed portal site. These activities are intended to support the Company’s operational timeline and continued advancement of the project through the permitting and development planning process. | Lucky Shot Property | In November 2025, the Company mobilized a drill rig at the Lucky Shot mine site to commence the first phase of a 15,000-meter underground in-fill drilling program. The Company began reporting assay results from this program during the first quarter of 2026. This drilling program, along with detailed engineering, hydrology and g', 'production-v2', 0.7, '2026-06-01T22:34:29.497033+00:00', '2026-06-01T22:34:29.497033+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('DRD', '0001023512', '0001628280-25-047346', '20-F', '2025-10-30', '2025-06-30', 2025, 'Q2', 'annual', 'Consolidated', 'gold', 1191.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1023512/000162828025047346/drd-20250630.htm', '2025 | June 30, 2025 | % | change | Production | Gold produced | kg | 1,191 | 1,173 | 2% | oz | 38,291 | 37,713', 'production-v2', 0.8, '2026-06-01T22:34:35.730706+00:00', '2026-07-01T23:23:28.694494+00:00');
