INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('FSM', '0001341335', '0001104659-26-047439', '6-K', '2026-04-23', '2026-04-23', 2026, NULL, 'quarter', 'The Company previously disclosed Mineral Reserves', 'gold', 2026.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1341335/000110465926047439/tm2612570d1_ex99-1.htm', '). Since that publication, | Mineral Reserves have increased by 73,000 ounces of gold and Inferred Mineral Resources have increased by 143,000 ounces of gold. These | changes reflect the inclusion of 55 exploration drill holes totaling 29,442 meters at the Sunbird deposit, which supported the conversion | of resources to reserves and extended known mineralization by a further 100 meters down plunge. The increase in Mineral Reserves was partially | offset by the impact of grade control drilling at the Sunbird open pit and mining depletion at the Antenna, Ancien, and Koula deposits | associated with gold production in the first three months of 2026. | - | 3 | - | At Séguéla, the 2026 Brownfields | exploration budget is $12.2 million and includes approximately 69,000 meters of exploration drilling. Exploration programs are focused | on additional resource conversion drilling primarily at the Sunbird underground project, infill and expansion drilling at the Kingfisher | deposit, and continued target generation (refer to', 'production-v2', 0.8, '2026-06-16T14:48:55.638428+00:00', '2026-06-17T12:00:57.408971+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('GAU', '0001377757', '0001199073-11-000676', '20-F', '2011-06-29', '2011-03-31', 2011, 'Q1', 'annual', 'Consolidated', 'gold', 2006.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1377757/000119907311000676/form_20-f.htm', 'On September 7, 2004, Keegan entered into agreements with the Hunter Dickinson Group, Inc. (“HDG”), Anaconda Gold Corp. and Barrick Gold Exploration Inc. whereby it acquired the right to earn an interest in the Horse Mountain Project located in Nevada. | On January 31, 2005, Keegan announced that the TSX-V had accepted the transaction pertaining to the Horse Mountain Project as the “Qualifying Transaction” for the Company and that it no longer considered Keegan to be a Capital Pool Company. Keegan was reclassified by the TSX-V as a “Gold Ore Mining” company. On March 1, 2005, the Company began trading on the TSX-V under the name “Keegan Resources Inc.” with the stock symbol of “KGN”. | On March 11, 2005, Keegan announced that it had entered into an option agreement with GTE Ventures Limited, an unrelated privately held Ghanaian company, to acquire the Asumura gold project located in West Ghana (the “Asumura Property”). The option agreement allowed Keegan to acquire 100% of the private interest in the Asumura Property, subject to a 3.5% net smelter return (“NSR”) royalty, 50% of which could be purchased by Keegan for US$2,000,000, Keegan’s interest could be earned by performing work expenditures totaling US$1,000,000, delivering cash payments totaling US$100,000 and delivering shares of Keegan totaling US$100,000 in value over a period of three years. During the year ended March 31, 2008, the Company acquired an option to purchase the remaining 50% of the NSR royalty for an additional US$4,000,000. Keegan’s interest in the Asumura Property is also subject to the government of Ghana’s 10% carried interest. See “Item 4.D Property, Plant and Equipment - Asumura Property”. | 9 | During the fiscal year ended March 31, 2006, management announced that it had decided not to pursue the Company’s option to earn an interest in the Horse Mountain Claims and, as a result, $1,018,587 in acquisition and deferred exploration expenditures associated with the property were written-off', 'production-v2', 0.8, '2026-06-01T22:34:38.880006+00:00', '2026-06-17T12:15:26.903250+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('GFI', '0001172724', '0001628280-26-021904', '20-F', '2026-03-30', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 2342000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1172724/000162828026021904/gfi-20251231.htm', 'Year ended 31 December | 2025 | 2024 | 2023 | Gold production (koz) | 2,342 | 1,985 | 2,304 | Copper production (kt) | 23', 'production-v2', 0.85, '2026-06-01T22:34:43.427306+00:00', '2026-07-01T23:23:37.552701+00:00');
