INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('GROY', '0001834026', '0001193125-26-114767', '20-F', '2026-03-19', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 2028.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1834026/000119312526114767/groy-20251231.htm', 'Orla also disclosed that South Railroad is currently advancing under the guidance of the US Bureau of Land Management (" | BLM | ") in accordance with the National Environmental Policy Act for permitting and it stated that the Notice of Intent is expected to be published shortly after the news release, with it targeting a Record of Decision (" | ROD | ") approximately 12 months after. Following approval of the ROD, construction on the South Railroad project would begin, with first gold produced targeted for 2028. | In its third quarter 2025 financial results issued on November 11, 2025, Orla published new exploration results over the South Railroad project. For the third quarter of 2025, Orla disclosed that it had drilled a total of 7,232 m in Nevada. Additionally, Orla expects BLM''s ROD for the second quarter of 2026, with construction following shortly after. Orla also reiterated that first gold production is expected in 2028. | 48 | In a news release issued on December 2, 2025, Orla announced exploration results over the South Carlin Complex, which contains the South Railroad project. Orla noted that drilling intersected significant oxide mineralization 100 to 130 m beyond current feasibility pit shells at both Pinion and Dark Star deposits, and repeated that the updated feasibility study for South Railroad is expected in the first quarter of 2026. | In a news release issued on January 14, 2026, Orla announced the results of the updated feasibility study and the approval of construction spending at the South Railroad project. | In its fourth quarter 2025 financial results issued on January 20, 2026, Orla disclosed that it intends to allocate $215 million towards project construction at South Railroad in 2026. | In a news release issued on March 2, 2026, Orla announced the filing of an updated technical report over the South Railroad project and outlined that construction is expected to commence mid-2026 pending the receipt of final project permits. | For further ', 'production-v2', 0.8, '2026-06-01T22:34:45.486908+00:00', '2026-06-01T22:34:45.486908+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('GROY', '0001834026', '0001193125-26-114767', '20-F', '2026-03-19', '2025-12-31', 2025, 'FY', 'annual', 'Ren Project', 'gold', 2040000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1834026/000119312526114767/groy-20251231.htm', '") and owned by Nevada Gold Mines, a joint venture between Barrick (61.5%) and Newmont Gold Corporation (38.5%). | In its management''s discussion and analysis for the year ended December 31, 2024, Barrick disclosed that the Ren Project is anticipated to produce an average of 140,000 oz of gold per year once in full production by 2027. It stated that, to support mining of the deposit, an additional set of twin declines will be driven from the Betze-Post open pit to the north with the intent to provide life of mine ventilation to the deposit as well as a direct path for material to be hauled and hoisted out via the existing Meikle Headframe. Barrick further stated that, to complete the project, a 7 m ventilation shaft will be sunk 550 m to serve as an exhaust raise and utility conduit for the orebody. | On May 7, 2025, Barrick reiterated its targeted production of 140,000 oz of gold per year in 2027, stating that, as at March 31, 2025, project spend was $95 million (including $23 million in Q1 2025) out of an estimated capital cost of $410 to $470 million. It further stated that secondary drift development is ongoing, and that infill conversion drilling began mid-March, with the first assay results expected to be returned in May to support the update for conversion by year-end. Barrick disclosed that final contract negotiations advanced for the Ren ventilation shaft construction and a contract award is expected in the second quarter of 2025. | 47 | In its management''s discussion and analysis for the three months ended March 31, 2025, Barrick reiterated its targeted production of 140,000 oz of gold per year in 2027. It disclosed that as at March 31, 2025, project spend was $95 million (including $23 million in the first quarter of 2025) out of an estimated capital cost of $410 to $470 million. It stated that secondary drift development is ongoing and that infill conversion drilling began mid-March 2025, with the first assay results expected to be returned in May 2025 t', 'production-v2', 0.8, '2026-06-01T22:34:45.486908+00:00', '2026-06-01T22:34:45.486908+00:00');
