INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('IAG', '0001203464', '0001062993-26-002334', '6-K', '2026-05-06', '2026-05-05', 2026, NULL, 'quarter', 'Consolidated', 'gold', 183600.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1203464/000106299326002334/exhibit99-1.htm', '"Westwood and Essakane both delivered strong performances, with quarterly production improvements year-over-year, driven by higher grades and improved operating efficiency across both sites. At Côté Gold, throughput in the quarter was limited by unplanned conveyor downtime as increased crushed ore volumes from the additional secondary cone crusher accelerated prior wear and splits on the belt. Performance improved in April following repairs as we control throughput ahead of the upcoming belt replacement in May that will allow for operations at full capacity. We remain confident in our full-year attributable production guidance for Côté of 270,000 to 310,000 ounces. Production and costs at the mine are expected to improve progressively through 2026 as throughput increases, the temporary aggregate crushing circuit is phased out, the pit pushback advances, and as we continue to optimize the operation and lengthen maintenance cycles." | "Looking ahead, we have significant catalysts across all of our assets. An updated mineral resource estimate for Côté is planned for the second quarter, followed by a technical report that is on track by year-end and is expected to outline a larger-scale mine incorporating both the Côté and Gosselin zones. Technical reports are also planned for Westwood, Essakane, and our Nelligan Mining Complex - which combined are expected to illustrate meaningful potential for production growth, mine life extension and value accretion. Combined with approximately $1.1 billion in available liquidity, an increasing production profile, and our continued execution on share buybacks and debt reduction, we are well-positioned to deliver value for our shareholders in 2026 and beyond." | HIGHLIGHTS: | Operating and Financial | • | Attributable gold production | was | 183,600 ounces in the first quarter, positioning the Company well to achieve its 2026 production guidance of 720,000 to 820,000 ounces. Production is expected to increase through the year as Côté', 'production-v2', 0.8500000000000001, '2026-06-16T14:48:56.964595+00:00', '2026-07-01T23:23:46.120622+00:00');
