INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('IAUX', '0001853962', '0001628280-26-034207', '10-Q', '2026-05-12', '2026-03-31', 2026, 'Q1', 'quarter', 'Archimedes underground project', 'gold', 2026.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1853962/000162828026034207/iaux-20260331.htm', 'During the three months ended March 31, 2026, underground development at the Archimedes project advanced ahead of schedule, with approximately 660 meters completed during the quarter supported by favorable ground conditions. A new dewatering well was completed during the quarter, with pump testing scheduled for the second quarter of 2026. Predictive groundwater modeling and geochemical technical studies are ongoing in support of the Lower Archimedes permitting process. The timeframe for first gold mined is in the second half of 2026. | 30 | The Company also completed 4,262 meters of infill drilling at the 426 zone of Upper Archimedes, with infill drilling of the Ruby Deeps zone within Lower Archimedes expected to commence in the second quarter of 2026, following the completion of the exploration drift. Together, these programs will form the technical basis for the Archimedes Underground feasibility study, which is targeting late in the first quarter of 2027, pending the potential expansion of the current drill program. New assay results from the first 20 holes from the Upper Archimedes drill program were reported subsequent to the first quarter on April 8, 2026, and continue to demonstrate high-grade mineralization throughout Upper Archimedes, returning high-grade intercepts consistent with the current geological model. | Capital expenditures for the three months ended March 31, 2026 were primarily from construction of a dry room trailer, office infrastructure upgrades, power upgrades and mine load centers for the underground. | Pre-development, evaluation and exploration expenditures were $12.4 million for the three months ended March 31, 2026, primarily due to increased underground development at the Archimedes underground project which began in the third quarter of 2025. During the first quarter of 2026, the higher expenditure is driven by a decline advance rate that exceeded expectations, resulting in accelerated development activity and the construction of surf', 'production-v2', 0.7, '2026-06-01T22:34:55.014862+00:00', '2026-06-11T02:58:05.316509+00:00');
