INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('MAKO', '0001784930', '0001062993-26-002209', '40-F', '2026-04-29', '2025-12-31', 2025, 'FY', 'annual', 'Filing of Moss Mine Technical Report', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1784930/000106299326002209/exhibit99-1.htm', 'On March 10, 2026, the Company announced the filing of the Moss Mine technical report for the updated mineral resource estimate announced January 26, 2026. | Completion of Nasdaq Listing | On March 30, 2026, the common shares of the Company were listed and commenced trading on the Nasdaq. | DESCRIPTION OF THE BUSINESS | General | The Company is a gold mining, development, and exploration company continued under the BCBCA. The Company''s principal asset is the San Albino Mine, located in Nueva Segovia, Nicaragua, which ranks among the highest-grade open pit gold mines globally. Commercial production at San Albino commenced in July 2021. | In addition to its Nicaraguan operations, the Company owns the Eagle Mountain Project in Guyana, South America, the Moss Mine, in Mohave County, Arizona, United States, and the Mt. Hamilton Project in Nevada, United States. The Eagle Mountain Project is currently in the PEA stage, with active engineering, environmental, and permitting activities underway. The Moss Mine was acquired during the year ended December 31, 2025, and legal ownership of the Mt. Hamilton Project was acquired during the current financial year by the Company''s wholly-owned subsidiary Mako US Corp. See " | General Development of the Business - Three Year History | ". | The material properties of the Company as of date of this AIF, were as follows: | Property | Location | Property ownership', 'production-v2', 0.8, '2026-06-17T12:01:13.791288+00:00', '2026-06-17T12:15:25.163446+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('MAKO', '0001784930', '0001062993-26-002209', '40-F', '2026-04-29', '2025-12-31', 2025, 'FY', 'annual', 'Ontario', 'gold', 2019.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1784930/000106299326002209/exhibit99-1.htm', 'July 3, 2024 | Laurence (Laurie) Gaborit | (2) (3) | Ontario, Canada | Director | Chief Executive Officer of LG IRServices Inc., an investor relations consulting firm, since July 2019; Vice President Investor Relations of Dore Copper Mining Corp. (a mineral exploration and development company) from September 2020 to December 2024; Vice President Investor Relations of Detour Gold Corporation (a mineral exploration and production company) from January 2007 to June 2019. | July 3, 2024 | John Hick | (1) (2) | Ontario, Canada | Director | Corporate director | November 9, 2018', 'production-v2', 0.8, '2026-06-17T12:01:13.791288+00:00', '2026-06-17T12:15:25.163446+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('NAMM', '0002026514', '0001213900-26-038838', '20-F', '2026-04-02', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 2012.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/2026514/000121390026038838/ea0280623-20f_namib.htm', 'were finally acquired by Lonrho in 1962. From 1962 onwards, production became steady and continuous. Production peaked between 1965 and | 1973 when it averaged approximately 3.2koz per month. After 1973, it declined reaching its lowest levels in 1991. In the same year, Independence | Gold Mining (Pvt) Limited (“IGM”) took over the mine. | In | 2002, BCM acquired IGM and took over GFM.Since then, post-Independence gold mining production rose from a low of 12.1koz in 2001 to 15.1koz | in 2005. After 2005, production declined due to poor economic conditions. Gold production sat at around ten to 12koz for the period 2012 | to 2016 and declined to approximately 6koz in 2017 and 1koz in 2018 when the mine was placed on care and maintenance. | The | Zimbabwe Supreme Court ordered a Corporate Rescue of the mine in February 2020. The Corporate Rescue proceedings were nullified in October 2021. | Mineral | Tenure | Access | to the mine site and to the ore is authorized by the applicable mining legislation and the Mazowe Mining Company’s title and mining', 'production-v2', 0.8, '2026-06-11T02:58:11.142140+00:00', '2026-06-17T12:15:30.931637+00:00');
