INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001410578-25-000372', '40-F', '2025-03-19', '2024-12-31', 2024, 'FY', 'annual', 'Consolidated', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000141057825000372/orla-20241231xex99d1.htm', 'Federal regulations require staged postings of a bond or financial guarantee for the estimated cost of reclamation, proportional to the pending reclamation work created by the project in each development phase, as determined by a technical economic study. On November 11, 2020, Minera Camino Rojo submitted the required first stage reclamation bond of $89.5 million Pesos (approximately $4.5 million) which was accepted by the Federal Treasury, with formal notice given to the Federal Attorney General’s Office for Environmental Protection ( | Procuraduria Federal de Proteccion al Ambiente | ) on November 13, 2020. All MIA and CUS permit conditions were satisfied, which allowed for site activities to commence for the Project described in the 2019 Camino Rojo Report. In November 2024, the reclamation bond was renewed for $263.5 , million Pesos (approximately $13 million). The increase related to additional disturbance from site activities. | Minera Camino Rojo currently has all major permits required to operate the project described in the 2019 Camino Rojo Report, including the permits by the Secretariat of National Defense ( | Secretaría de la Defensa Nacional | ) for the purchase, storage and use explosives in mining activities. There are no impediments to mining and processing activities for the already authorized project. Minera Camino Rojo commenced the start of earthworks on November 26, 2020. Camino Rojo achieved first gold pour on December 13, 2021 and reached commercial production effective April 1, 2022. | Approximately two-thirds of the mineral reserves described below are within the currently permitted mine plan. The remaining portion will require additional permits for an expanded pit, as further described above. These permits are expected to be approved in a reasonable timeline. | HISTORY | The mining concessions comprising the Camino Rojo property were originally staked to the benefit of Canplats de Mexico, S.A. de C.V., a subsidiary of Canplats Resources Co', 'production-v2', 0.8, '2026-06-17T12:01:20.960594+00:00', '2026-06-17T12:01:20.960594+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001410578-25-000372', '40-F', '2025-03-19', '2024-12-31', 2024, 'FY', 'annual', 'Mined Grade', 'gold', 2021.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000141057825000372/orla-20241231xex99d1.htm', '​ | ​ | ​ | Stacked Grade | ​ | Gold Production | Year | Ore Mined (t) | (g/t) | Ore Stacked (t) | (g/t) | (oz) | 2021', 'production-v2', 0.8, '2026-06-17T12:01:20.960594+00:00', '2026-06-17T12:01:20.960594+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001104659-26-032222', '40-F', '2026-03-20', '2025-12-31', 2025, 'FY', 'annual', 'PROCESSING AND RECOVERY OPERATIONS', 'gold', 2022.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000110465926032222/orla-20251231xex99d1.htm', 'Operating and monitoring advice provided by Piteau was incorporated into MCR open pit design and operating procedures. Additional site visits by Piteau are planned to monitor the North wall, above the annual reviews. Based on the performance of the North wall push back, Piteau will be issuing design parameters for the final design in 2026. | The waste dump is currently being constructed with a face angle of 36 degrees, 20 m height and 50 m berms. The remaining capacity for the WRSF is sufficient for the remaining LOM, with 46.4 Mt of storage capacity as of the end of September 2025. | The current LOM plan assumes a supply of ore to the crushing and heap leach facilities at a stacking rate of 18,900 tpd, based on current crusher performance. | From 2025 to 2027, the current LOM plan mining rate of total material moved rate ranges from 38,000 tpd to 70,000 tpd on a month-to-month basis, and from 2028 to 2030, ranges from 18,500 tpd to 48,500 tpd, including rehandling of the low-grade. | PROCESSING AND RECOVERY OPERATIONS | The Camino Rojo Project is an open pit heap leach operation which has been in production since late 2021. Open pit mining commenced in August 2021, with processing facilities commissioned in Q4 2021 (with the Merrill-Crowe Plant in operation in December 2021). The first gold pour occurred on December 13, 2021, and commercial production was achieved on April 1, 2022. | ​ | Page 43 | ​ | Table of Contents | ORLA MINING LTD. | ​ | Annual Information Form', 'production-v2', 0.8, '2026-06-17T12:01:20.772965+00:00', '2026-06-17T12:15:21.779183+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001279569-26-000299', '6-K', '2026-04-14', '2026-04-13', 2026, NULL, 'quarter', 'Camino Rojo', 'gold', 18221.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000127956926000299/ex991.htm', 'tonnes | 1,828,000 | Stacked Ore Gold Grade | g/t | 0.59 | Gold Produced | oz | 18,221 | Gold Sold | oz | 17,436 | "2026 was always going to be a catalyst-rich | year, and the opening months have not disappointed. We delivered the updated feasibility study at South Railroad, completed the PEA for', 'production-v2', 0.8, '2026-06-16T14:49:00.367316+00:00', '2026-06-17T12:01:20.156042+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001279569-26-000299', '6-K', '2026-04-14', '2026-04-13', 2026, NULL, 'quarter', 'Consolidated', 'gold', 81206.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000127956926000299/ex991.pdf', 'is pleased to provide an operational update for the first quarter ended March 31, 2026. Orla remains on  | track to meet its full year consolidated gold production guidance range of 340,000–360,000 ounces. | (All amounts expressed in millions of US dollars, as at March 31, 2026, and are unaudited) | First Quarter Operational Update | Total Gold Production & Sales Q1 2026 | Total Gold Produced oz 81,206 | Total Gold Sold oz 81,540 | Musselwhite, Canada |   Ore Milled tonnes 332,822 |   Milled Ore Gold Head Grade g/t 6.29 |   Gold Produced oz 62,985 |   Gold Sold oz 64,104 | Camino Rojo, Mexico', 'production-v2', 0.8, '2026-06-16T14:49:00.367316+00:00', '2026-06-17T12:01:20.145747+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001279569-26-000299', '6-K', '2026-04-14', '2026-04-13', 2026, NULL, 'quarter', 'Musselwhite', 'gold', 62985.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000127956926000299/ex991.htm', 'tonnes | 332,822 | Milled Ore Gold Head Grade | g/t | 6.29 | Gold Produced | oz | 62,985 | Gold Sold | oz | 64,104 | Camino Rojo, Mexico | Ore Stacked', 'production-v2', 0.8, '2026-06-16T14:49:00.367316+00:00', '2026-06-17T12:01:20.156042+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001279569-26-000299', '6-K', '2026-04-14', '2026-04-13', 2026, NULL, 'quarter', 'Musselwhite Operations', 'gold', 62985.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000127956926000299/ex991.htm', 'our team in all three nations who contributed to all these successes giving us real confidence for the remainder of 2026." | - | Jason Simpson, President and Chief Executive Officer, Orla Mining | Musselwhite Operations | During the quarter, Musselwhite mined 333,495 tonnes | of ore and processed 332,822 tonnes at a mill head grade of 6.29 g/t gold. Gold recovery was 95.91% resulting in gold production of 62,985 | ounces. | Musselwhite completed 3,437 metres of lateral development. | 367 metres of the completed lateral development was attributed to the advance of the 1080 exploration drift. The 1080 exploration drift | is being used to provide platforms for underground diamond drilling in the PQ Extensions area with the objective to continue growing reserves | and resources in the extension of the Mine Trend. During the quarter, 2,300 metres of reserve, 9,200 metres of resource, 5,300 deep directional, | and 2,700 metres of brownfields drilling were completed. All drilling programs continue to produce encouraging results. | Camino Rojo Operations', 'production-v2', 0.8, '2026-06-16T14:49:00.374956+00:00', '2026-06-17T12:01:20.156042+00:00');
