INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001279569-26-000420', '6-K', '2026-05-11', '2026-05-11', 2026, NULL, 'quarter', 'Consolidated', 'gold', 81206.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000127956926000420/ex991.pdf', '- Jason Simpson, President and Chief Executive Officer, Orla Mining | First Quarter Operational Update | Table 1a: Operating Highlights | Operating Q1 2026 Q1 2025 | Consolidated | Total Gold Produced oz 81,206 47,759 | Total Gold Sold oz 81,540 46,356 | Average Realized Gold Price1 $/oz $4,575 $2,915 | Cash Cost per Ounce1,2 $/oz $1,251 $597 | All-in Sustaining Cost per Ounce1,2 $/oz $1,668 $845 | Q | Musselwhite, Canada3 | Ore Milled tonnes 332,822 104,287', 'production-v2', 0.8, '2026-06-16T14:49:00.337921+00:00', '2026-06-17T12:01:20.102481+00:00');
