INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('ORLA', '0001680056', '0001279569-26-000420', '6-K', '2026-05-11', '2026-05-11', 2026, NULL, 'quarter', 'Musselwhite Operations', 'gold', 62985.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1680056/000127956926000420/ex991.htm', 'Gold produced during the quarter totaled 81,206 ounces, | from the Musselwhite Mine and the Camino Rojo Oxide Mine. Gold sold during the quarter totaled 81,540 ounces. Consolidated cash costs | and AISC totaled $1,251 and $1,668 per ounce of gold sold, respectively. | Musselwhite Operations | During the quarter, Musselwhite mined 333,495 tonnes | of ore and processed 332,822 tonnes at a mill head grade of 6.29 g/t gold. Gold recovery was 95.9% resulting in gold production of 62,985 | ounces. Plant performance was stable with an average milling rate of 3,698 tonnes per day over the quarter. | Musselwhite exceeded production targets through strategic | mine plan resequencing due to strong development and production results in late 2025. This provided access to higher-grade ore earlier | in the year than originally planned. Mining and development performance in the quarter was driven by strong execution from the site team. | Development rates increased 20% from 2025 to first quarter achieving an average of 38.2 metres per day. | Development performance remained consistent, with | each month achieving over 1,000 metres of advance. This was largely driven by reliable equipment availability and strong execution across', 'production-v2', 0.8, '2026-06-16T14:49:00.352021+00:00', '2026-06-17T12:01:20.124132+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('PAAS', '0000771992', '0000771992-26-000019', '40-F', '2026-02-18', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'gold', 742200.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/771992/000077199226000019/aif-2025ye.htm', 'Attributable production of 22.8 million ounces of silver and 742.2 thousand ounces of gold, led by silver production from the La Colorada vein mine (the “La Colorada mine”) of 6.0 million ounces and gold production of 190.5 thousand ounces from the Jacobina mine. Attributable silver production included 2.49 million ounces produced from the Juanicipio mine after the MAG Acquisition, representing the attributable amount of production for the Company’s 44% interest in the Juanicipio joint venture.', 'production-v2', 0.9, '2026-06-17T12:12:32.584891+00:00', '2026-07-01T23:24:02.409323+00:00');
