INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('SSRM', '0000921638', '0000921638-26-000035', '10-K', '2026-02-17', '2025-12-31', 2025, 'FY', 'annual', 'Consolidated', 'silver', 2009.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/921638/000092163826000035/ssrm-20251231.htm', 'Table of | Contents | The Chinchillas property is composed of three contiguous claims, totaling 2,043 hectares. The Pirquitas property comprises 54 exploitation concessions that cover an area of approximately 9,742 hectares. All the exploitation concessions are valid and in good standing. | Ore from the Chinchillas mine is transported approximately 45 kilometers to the Pirquitas plant for processing. Concentrates produced at Puna are subject to a maximum 3% ‘mouth of mine value’ royalty that is payable to the Province of Jujuy. This royalty payment is based on the net recoverable value of the contained metals less certain operating costs. | History | Chinchillas was first prospected and mined in small scale in the eighteenth century by Jesuit missionaries. An initial mining concession was granted in 1956, with small scale production beginning in 1968 and continuing through 1982. Sporadic exploration and sampling programs were conducted at Chinchillas between 1982 and the mid-2010’s. Between the 1930’s and 1995 multiple small mining operations recovered silver and tin from placer and vein deposits in the vicinity of the Pirquitas mine. Comprehensive mineral exploration was conducted on the property between 1995 and 2000. The Pirquitas mine was formally inaugurated in April 2009, with commercial production starting in December of that year. Mining was completed in mid-January 2017. The Pirquitas processing plant has been in continuous operation since 2009. | Geological Setting, Mineralization, and Deposit Types | The Chinchillas and Pirquitas deposits are considered part of the Bolivian tin-silver–zinc belt that extends from the San Rafael tin-copper deposit in southern Peru into Bolivia and then the Puna region of Jujuy. Deposits with similar styles of mineralization include San Cristóbal, Potosí, and Pulacayo. These deposits are characterized by dacite dome complexes with mineralization hosted in shears and breccias within the dacite domes or within shears and brecc', 'production-v2', 0.7, '2026-06-01T22:35:15.792034+00:00', '2026-06-17T12:15:17.685592+00:00');
INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('SVM', '0001340677', '0001279569-26-000320', '6-K', '2026-04-17', '2026-04-16', 2026, NULL, 'quarter', 'Consolidated', 'silver', 1500000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1340677/000127956926000320/ex991.htm', '• | Record revenue | of approximately $147.4 million, an | increase of 96% over the same quarter last year ("Q4 Fiscal 2025"); | • | Silver production | of 1.5 million ounces, a decrease | of 11% over Q4 Fiscal 2025; silver equivalent (only silver and gold) | i | production of 1.6 million ounces, a decrease of 17% compared | to 1.9 million ounces in Q4 Fiscal 2025; | • | Lead production', 'production-v2', 0.8, '2026-06-16T14:49:03.267599+00:00', '2026-06-17T12:01:26.549506+00:00');
