INSERT INTO production (symbol, cik, accession_number, form, filing_date, report_date, fiscal_year, fiscal_period, period_type, mine_name, metal, ounces_produced, unit, source_url, source_text, parser_version, confidence, created_at, updated_at) VALUES ('USAS', '0001286973', '0001477932-24-002432', '20-F', '2024-04-30', '2023-12-31', 2023, 'FY', 'annual', 'Consolidated', 'silver', 8000000.0, 'ounces', 'https://www.sec.gov/Archives/edgar/data/1286973/000147793224002432/usas_20f.htm', 'Table of Contents | B. Business Overview | Overview | The Company is a precious metals producer with two operations in some of the world''s leading silver mining regions: the Galena Complex in Idaho, U.S.A. and the Cosalá Operations in Sinaloa, Mexico. The Company owns the Relief Canyon project in Nevada, U.S.A.which is currently in a status of care & maintenance following a suspension of mining activities in August 2021. | In Idaho, U.S.A., the Company operates the 60%-owned producing Galena Complex (40% owned by Sprott) whose primary assets are the operating Galena mine, the Coeur mine, and the contiguous Caladay development project in the Coeur d’Alene Mining District of the northern Idaho Silver Valley. The Galena Complex has recorded production of over 230 million ounces of silver along with associated by-product metals of copper and lead over a production history of more than sixty years. The Company entered into a joint venture agreement with Sprott effective October 1, 2019 for a 40% non-controlling interest of the Galena Complex. The continuing goal of the joint venture agreement is to support the rejuvenation of the mine’s infrastructure while growing the mineral reserve base through exploration and operate the mine safely and profitably. | In Sinaloa, Mexico, the Company operates the 100%-owned Cosalá Operations, which is currently producing from the San Rafael orebody having declared commercial production in December 2017. Prior to that time, it operated the Nuestra Señora silver-zinc-copper-lead mine which began commercial production after commissioning the Los Braceros processing facility in January 2009. The Cosalá area land holdings also host several other known precious metals and polymetallic deposits, past-producing mines, and development projects including the Zone 120 silver-copper deposit and the El Cajón silver-copper deposit. These properties are located in close proximity to the Los Braceros processing plant. The Company also owns a 100% inte', 'production-v2', 0.8, '2026-06-01T22:35:23.114088+00:00', '2026-07-01T23:24:19.935104+00:00');
